# 14. TRANSKRIPTIONS-ENGINE & DUMMY
# =============================================================================

class TranscriptionEngine:
    """
    Optimierte Transkriptions-Engine mit automatischer Hardware-Erkennung und Fallback.

    **Unterstützte Geräte und Compute-Typen:**
    - NVIDIA GPU (Compute Capability >= 6.0): int8 (schnell, speichereffizient)
    - NVIDIA GPU (CC 3.5 - 5.x): float16 (kompatibel, etwas langsamer)
    - NVIDIA GPU (CC < 3.5): float32 (sehr langsam, nur als Notlösung)
    - AMD GPU (ROCm): float16 (empfohlen)
    - Apple Silicon (MPS): float16
    - CPU: int8

    **Fallback-Strategie beim Laden eines Modells:**
    1. Versuche den vom Device empfohlenen Compute-Typ.
    2. Bei Fehler (OOM / fehlendes Kernel-Image) → nächster Compute-Typ (float16/float32).
    3. Wenn alle GPU-Versuche scheitern → CPU-Fallback mit int8.

    **GPU-Acceleration-Einstellung:**
    - Kann zur Laufzeit über `set_gpu_acceleration()` umgeschaltet werden.
    - Bei Deaktivierung wird erzwungen auf CPU ausgewichen (VRAM bleibt frei).
    - Modell wird synchron neu geladen – sofort wirksam (force=True entfernt altes Modell).

    **Debug-Ausgaben:**
    - Bei DEBUG_LEVEL >= 3 werden alle relevanten Entscheidungen protokolliert.
    - Zusätzliche Logs in load_model, _reload_model_sync und _detect_optimal_device.
    """

    MODEL_SIZE_ORDER = [
        "tiny", "tiny.en", "base", "base.en", "small", "small.en",
        "medium", "medium.en", "large-v1", "large-v2", "large-v3", "large-v3-turbo"
    ]

    _ALLOWED_FASTER = {
        "language", "task", "beam_size", "best_of", "temperature",
        "compression_ratio_threshold", "log_prob_threshold", "no_speech_threshold",
        "condition_on_previous_text", "vad_filter", "vad_parameters",
        "without_timestamps", "word_timestamps", "initial_prompt", "prefix",
        "suppress_blank", "suppress_tokens", "hotwords", "language_detection_threshold",
        "language_detection_segments", "multilingual", "repetition_penalty",
        "no_repeat_ngram_size", "prompt_reset_on_temperature"
    }

    _ALLOWED_OPENAI = {
        "language", "task", "temperature", "best_of", "beam_size", "patience",
        "length_penalty", "repetition_penalty", "no_repeat_ngram_size",
        "initial_prompt", "prefix", "suppress_tokens", "without_timestamps",
        "max_initial_timestamp", "word_timestamps", "prepend_punctuations",
        "append_punctuations", "max_new_tokens", "clip_timestamps",
        "hallucination_silence_threshold", "compression_ratio_threshold",
        "log_prob_threshold", "no_speech_threshold", "condition_on_previous_text"
    }

    __slots__ = (
        "model", "model_size", "whisper_backend", "settings", "config", "device",
        "compute_type", "_cache", "_lock", "_max_cached_models", "_model_cache",
        "_model_usage_lock", "_performance_monitor", "_last_transcription_text",
        "_model_loaded_flag", "_disposing", "forced_language", "_last_detected_language",
        "_torch", "_np", "_scipy_signal", "_last_confidence_threshold",
        "_confidence_lock", "_audio_enhancer", "_cache_manager", "_model_locks",
        "_model_locks_lock", "_reloading", "_model_load_stop_event", "_vad_fallback_enabled",
        "_debug", "_state_lock", "_last_oom", "event_bus", "_requested_model",
        "_model_size_cache", "_nvml_initialized"
    )

    _global_load_semaphore = threading.Semaphore(1)

    def __init__(
        self,
        settings: Optional["AdvancedSettings"] = None,
        cache_manager: Optional[CacheManager] = None,
        event_bus: Optional[EventBus] = None,
    ) -> None:
        """
        Initialisiert die TranscriptionEngine mit optimierten Einstellungen.
        Die GPU‑Acceleration-Einstellung aus `settings` wird beachtet.
        """
        self.settings = settings or AdvancedSettings()
        self.config = self.settings.config
        self.model: Any = None
        self.model_size: Optional[str] = None
        self.whisper_backend: Optional[str] = None
        self._lock = threading.RLock()
        self._state_lock = threading.RLock()
        self._model_usage_lock = threading.RLock()
        self._max_cached_models = 1
        self._cache_manager = cache_manager or AppContext().cache_manager
        self._cache = self._cache_manager.transcription_cache
        self._performance_monitor = SimplePerformanceTracker()
        self._last_transcription_text = ""
        self._model_loaded_flag = False
        self._disposing = False
        self._model_cache: OrderedDict[Tuple[str, str], Any] = OrderedDict()
        self.forced_language: Optional[str] = None
        self._last_detected_language: Optional[str] = None
        self._torch = None
        self._np = None
        self._scipy_signal = None
        self._last_confidence_threshold = 0.6
        self._confidence_lock = threading.Lock()
        self._audio_enhancer = AudioEnhancer(self.config, self.settings)
        self._reloading = False
        self._vad_fallback_enabled = True

        # Debug: Ausgabe der aktuellen GPU-Einstellung aus den geladenen Settings
        log_debug("engine", f"Initializing TranscriptionEngine: gpu_acceleration={self.settings.gpu_acceleration}")

        # Device-Erkennung (beachtet self.settings.gpu_acceleration)
        self.device, self.compute_type = self._detect_optimal_device()
        self._debug = logger.isEnabledFor(logging.DEBUG)

        # Warnung, wenn GPU-Acceleration aktiviert, aber kein CUDA/MPS erkannt wurde
        if self.settings.gpu_acceleration and self.device == "cpu":
            logger.warning(
                "⚠️ GPU acceleration is enabled in settings, but no compatible GPU was found or PyTorch does not support your GPU. "
                "Falling back to CPU. You can disable GPU acceleration in advanced settings to suppress this warning."
            )

        self._model_locks: Dict[str, threading.Lock] = {}
        self._model_locks_lock = threading.Lock()
        self._model_load_stop_event = threading.Event()
        self._last_oom = False

        self.event_bus = event_bus
        self._model_size_cache: Dict[str, float] = {}
        self._requested_model: Optional[str] = None

        if DEBUG_LEVEL >= 3:
            log_debug("engine", f"TranscriptionEngine initialisiert (event_bus={event_bus is not None})")

    # -------------------------------------------------------------------------
    #  Öffentliche Methoden
    # -------------------------------------------------------------------------
    def set_vad_fallback_enabled(self, enabled: bool) -> None:
        self._vad_fallback_enabled = enabled
        if self._debug:
            log_debug("vad", f"VAD-Fallback {'aktiviert' if enabled else 'deaktiviert'}")

    def set_gpu_acceleration(self, enabled: bool) -> None:
        """
        Aktiviert oder deaktiviert die GPU-Beschleunigung zur Laufzeit.
        Bei Änderung wird das Modell asynchron neu geladen (nicht blockierend).
        """
        log_debug("gpu", f"set_gpu_acceleration called with enabled={enabled}")

        if not hasattr(self, "settings") or self.settings is None:
            log_debug("gpu", "settings not available, aborting")
            return

        # Einstellung speichern
        self.settings.gpu_acceleration = enabled
        try:
            self.settings.save_to_file()
            log_debug("gpu", "Settings saved to disk")
        except Exception as e:
            logger.warning(f"Konnte GPU-Einstellung nicht speichern: {e}")
            log_debug("gpu", f"Failed to save settings: {e}")

        # Alte Gerätekonfiguration merken
        old_device = self.device
        old_compute = self.compute_type
        log_debug("gpu", f"Old device={old_device}, compute_type={old_compute}")

        # Gerät neu ermitteln (unter Beachtung der neuen Einstellung)
        self._refresh_device()
        new_device = self.device
        new_compute = self.compute_type
        log_debug("gpu", f"New device={new_device}, compute_type={new_compute}")

        # Wenn sich das Device oder der Compute-Typ geändert hat, Modell asynchron neu laden
        if old_device != new_device or old_compute != new_compute:
            current_model = self.get_current_model()
            if current_model and current_model != "None" and not self._disposing:
                logger.info(
                    f"🔄 Device changed from {old_device}/{old_compute} to "
                    f"{new_device}/{new_compute} – reloading model {current_model} asynchronously..."
                )
                log_debug("gpu", f"Calling reload_model({current_model}) asynchronously")
                success = self.reload_model(current_model)   # <-- ASYNCHRON
                if not success:
                    logger.error("Failed to start asynchronous model reload")
                    log_debug("gpu", "reload_model returned False")
            else:
                log_debug("gpu", "No model to reload (model is None or disposing)")
        else:
            log_debug("gpu", "Device unchanged, no reload needed")

        # Event-Bus benachrichtigen (der neue GPU-Status gilt sofort)
        if self.event_bus:
            self.event_bus.emit("gpu_status_changed", enabled)
            log_debug("gpu", f"Emitted gpu_status_changed event with value {enabled}")
        else:
            log_debug("gpu", "No event bus available")

    def _refresh_device(self) -> None:
        """Ermittelt Device und Compute-Typ neu (unter Beachtung der aktuellen gpu_acceleration-Einstellung)."""
        old_device = self.device
        old_compute = self.compute_type
        new_device, new_compute = self._detect_optimal_device()
        self.device = new_device
        self.compute_type = new_compute
        if old_device != new_device or old_compute != new_compute:
            logger.info(f"Device/Compute-Typ geändert: {old_device}/{old_compute} → {new_device}/{new_compute}")
            if self._debug:
                log_debug("device", f"Refreshed device: {self.device}, compute_type={self.compute_type}")

    def _reload_model_sync(self, model_size: str, force: bool = False) -> bool:
        """
        Lädt ein Modell synchron (wartet auf Abschluss).
        Wenn force=True, wird das aktuell geladene Modell zuerst entladen.
        """
        with self._lock:
            if self._reloading and not force:
                logger.warning("Model reload already in progress, waiting...")
                self._model_load_stop_event.wait(timeout=30.0)
                if self._reloading:
                    logger.error("Timeout waiting for background reload")
                    return False

        if force:
            # Altes Modell vollständig entfernen
            logger.info("Force unloading current model before reload...")
            self._force_model_cleanup()
            # Kurze Pause für GPU-Speicherbereinigung
            if self.device == "cuda" and self._torch:
                self._torch.cuda.empty_cache()
                time.sleep(0.2)

        # Synchrones Laden (ohne Thread)
        result = self.load_model(model_size, set_active=True)
        return result is not None

    def load_model(self, model_size: str, set_active: bool = False) -> Optional[Tuple[Any, str]]:
        self._requested_model = model_size
        if DEBUG_LEVEL >= 3:
            log_debug("model", f"load_model aufgerufen: {model_size}, set_active={set_active}")

        if self._disposing:
            logger.warning("TranscriptionEngine wird entsorgt – Laden eines Modells nicht möglich")
            return None

        if set_active:
            with self._model_usage_lock:
                if self.model is not None and self.model_size == model_size:
                    if self._debug:
                        logger.debug(f"Modell {model_size} bereits aktiv – verwende bestehendes (device={self.device})")
                    return self.model, self.whisper_backend

        if FASTER_WHISPER_AVAILABLE:
            backend = "faster_whisper"
        elif OPENAI_WHISPER_AVAILABLE:
            backend = "openai_whisper"
        else:
            logger.error("❌ Kein Whisper-Backend verfügbar")
            return None

        cache_key = (model_size, backend)
        with self._lock:
            if cache_key in self._model_cache:
                model = self._model_cache[cache_key]
                self._model_cache.move_to_end(cache_key)
                if set_active:
                    self._set_active_model(model, model_size, backend, cache_key)
                return model, backend

        return self._load_model_with_checks(model_size, backend, cache_key, set_active)

    def reload_model(self, model_size: str) -> bool:
        with self._lock:
            if self._reloading:
                if self._debug:
                    logger.debug("Model reload already in progress, skipping")
                return False
            self._reloading = True
            self._model_load_stop_event.clear()

        def _load_in_background():
            try:
                result = self.load_model(model_size, set_active=False)
                if result is None:
                    logger.error("❌ Background model loading failed")
                    return
                new_model, new_backend = result
                cache_key = (model_size, new_backend)
                with self._lock, self._model_usage_lock:
                    old_model = self.model
                    old_key = (self.model_size, self.whisper_backend) if self.model_size else None
                    self.model = new_model
                    self.model_size = model_size
                    self.whisper_backend = new_backend
                    self._model_loaded_flag = True
                    if old_model is not None and old_key is not None:
                        if old_key in self._model_cache:
                            del self._model_cache[old_key]
                        self._unload_model(old_model)
                    if cache_key not in self._model_cache:
                        self._model_cache[cache_key] = new_model
                with self._confidence_lock:
                    self._last_confidence_threshold = 0.6
                logger.info(f"✅ Model switched to {model_size} ({new_backend})")
            except Exception as e:
                logger.exception(f"❌ Background model loading error: {e}")
            finally:
                with self._lock:
                    self._reloading = False
                    self._model_load_stop_event.set()
                if self.device == "cuda" and self._torch:
                    try:
                        self._torch.cuda.empty_cache()
                    except Exception:
                        pass

        threading.Thread(target=_load_in_background, daemon=True, name=f"ModelLoader-{model_size}").start()
        return True

    def is_functional(self) -> bool:
        return self.model is not None and not isinstance(self, DummyTranscriptionEngine)

    def is_model_loading(self) -> bool:
        with self._lock:
            return self._reloading

    def safe_transcribe(self, audio_data: bytes, max_retries: int = 2) -> Optional[TranscriptionResult]:
        if self._disposing or self._reloading:
            return None

        is_valid, msg = self.validate_audio_data(audio_data)
        if not is_valid:
            if self._debug:
                log_debug("transcribe", f"Audio validation failed: {msg}")
            return None

        last_error = None
        for attempt in range(max_retries + 1):
            try:
                with self._confidence_lock:
                    last_conf = self._last_confidence_threshold
                processed = self._audio_enhancer.enhance_audio(audio_data, last_conf, 0) if attempt == 0 or last_conf < 0.5 else audio_data
                result = self.transcribe_audio(processed)
                if result and result.text and result.text.strip():
                    with self._confidence_lock:
                        self._last_confidence_threshold = getattr(result, "confidence", 0.5)
                    return result
            except (RuntimeError, TranscriptionError) as e:
                last_error = e
                if self._last_oom or ("out of memory" in str(e).lower() and self.device == "cuda"):
                    self._handle_cuda_oom()
                    continue
                if attempt < max_retries:
                    time.sleep(0.5 * (attempt + 1))
            except Exception as e:
                last_error = e
                if attempt < max_retries:
                    time.sleep(0.5 * (attempt + 1))

        if last_error:
            raise last_error
        return None

    def transcribe_audio(self, audio_data: bytes, include_timestamps: bool = False) -> Any:
        if self._disposing:
            return [] if include_timestamps else None
        with self._model_usage_lock:
            model = self.model
            if not model:
                return None if not include_timestamps else []
        processed, language, beam_size, vad_params = self._prepare_transcription(audio_data)
        return self._transcribe_worker(
            model, processed, language, beam_size, vad_params, include_timestamps,
            hotwords=self.settings.hotwords, best_of=self.settings.best_of,
            patience=self.settings.patience, no_speech_threshold=self.settings.no_speech_threshold,
            log_prob_threshold=self.settings.log_prob_threshold,
            compression_ratio_threshold=self.settings.compression_ratio_threshold,
            condition_on_previous_text=self.settings.condition_on_previous_text,
            suppress_tokens=self.settings.suppress_tokens
        )

    def emergency_fallback_transcription(self, audio_data: Union[bytes, Any]) -> Optional[TranscriptionResult]:
        if self._disposing:
            return None
        self._load_modules()
        with self._model_usage_lock:
            model = self.model
            if not model:
                return None
            try:
                if isinstance(audio_data, self._np.ndarray):
                    audio_np = audio_data.astype(self._np.float32)
                    if audio_np.dtype == self._np.int16:
                        audio_np = audio_np / 32768.0
                else:
                    audio_np = self._np.frombuffer(audio_data, dtype=self._np.int16).astype(self._np.float32) / 32768.0
                return self._transcribe_minimal(model, audio_np, None)
            except Exception as e:
                logger.exception(f"❌ Emergency fallback exception: {e}")
                return None

    def get_current_model(self) -> str:
        if self._disposing:
            return "disposing"
        with self._model_usage_lock:
            return self.model_size if self.model_size else "None"

    def test_model_functionality(self) -> bool:
        if self._disposing:
            return False
        with self._model_usage_lock:
            if not self.model:
                return False
            try:
                self._load_modules()
                test_audio = self._np.random.randn(16000).astype(self._np.float32) * 0.1
                segments, info = self._universal_transcribe(self.model, test_audio, language=None, task="transcribe", temperature=0.0, best_of=1, beam_size=1, without_timestamps=False)
                list(segments)
                return True
            except Exception as e:
                logger.exception(f"❌ Model-Test fehlgeschlagen: {e}")
                return False

    def validate_audio_data(self, audio_data: bytes) -> Tuple[bool, str]:
        self._load_modules()
        if not isinstance(audio_data, bytes):
            return False, "Audio data must be bytes"
        if len(audio_data) == 0:
            return False, "Audio data is empty"
        if len(audio_data) < 1600:
            return False, f"Audio data too short: {len(audio_data)} bytes"
        if self._np is not None:
            try:
                audio_np = self._np.frombuffer(audio_data, dtype=self._np.int16)
                if self._np.all(audio_np == 0):
                    return False, "Audio data is completely silent"
                if self._np.var(audio_np) < 100:
                    return False, "Audio variance too low (likely silent)"
            except Exception:
                pass
        return True, "Valid"

    def is_valid_segment(self, text: str, confidence: float) -> bool:
        if not text or len(text.strip()) < 2:
            return False
        clean = text.strip()
        if clean.isspace():
            return False
        if len(clean) > 500:
            return False
        if not any(c.isalpha() for c in clean):
            return False
        if confidence < self.settings.min_confidence:
            return False
        return True

    def clear_cache(self) -> None:
        with self._lock:
            self._cache.clear()
            self._last_transcription_text = ""
        gc.collect()
        if self.device == "cuda" and self._torch is not None:
            try:
                self._torch.cuda.empty_cache()
            except Exception:
                pass

    def dispose(self) -> None:
        logger.info("🧹 Transcription Engine Dispose...")
        self._disposing = True
        if hasattr(self, "_reloading") and self._reloading:
            if hasattr(self, "_model_load_stop_event"):
                self._model_load_stop_event.set()
                self._model_load_stop_event.wait(timeout=5.0)
        with self._lock:
            self._cache.clear()
            self._last_transcription_text = ""
            for (size, backend), model in list(self._model_cache.items()):
                self._unload_model(model)
            self._model_cache.clear()
        self._force_model_cleanup()
        if self.device == "cuda" and self._torch:
            try:
                self._torch.cuda.empty_cache()
            except Exception:
                pass
        gc.collect()
        logger.info("✅ Transcription Engine disposed")

    # -------------------------------------------------------------------------
    #  Private Hilfsmethoden (optimiert)
    # -------------------------------------------------------------------------
    def _load_modules(self) -> None:
        if self._np is None and NUMPY_AVAILABLE:
            self._np = FastLazyLoader.load("numpy")
        if self._scipy_signal is None and SCIPY_AVAILABLE:
            self._scipy_signal = FastLazyLoader.load("scipy.signal")
        if self._torch is None and TORCH_AVAILABLE:
            self._torch = FastLazyLoader.load("torch")

    def _detect_optimal_device(self) -> Tuple[str, str]:
        """
        Ermittelt das beste verfügbare Gerät und den optimalen Compute-Typ.
        Beachtet die Einstellung `self.settings.gpu_acceleration`.
        """
        self._load_modules()
        device = "cpu"
        compute_type = "int8"

        # Wenn GPU-Beschleunigung explizit deaktiviert ist, sofort CPU zurückgeben
        if self.settings and not self.settings.gpu_acceleration:
            logger.info("GPU acceleration disabled by user – forcing CPU")
            if DEBUG_LEVEL >= 3:
                log_debug("device", "gpu_acceleration=False → CPU forced")
            return "cpu", "int8"

        if self._torch is not None:
            torch = self._torch

            # NVIDIA CUDA
            if torch.cuda.is_available():
                try:
                    cc_major, cc_minor = torch.cuda.get_device_capability(0)
                    gpu_name = torch.cuda.get_device_name(0)
                    logger.info(f"✅ NVIDIA GPU: {gpu_name} (CC {cc_major}.{cc_minor})")

                    if cc_major >= 6:          # Pascal oder neuer
                        compute_type = "int8"
                        logger.info("   → Verwende int8 (optimal)")
                    elif cc_major >= 3:        # Kepler, Maxwell
                        compute_type = "float16"
                        logger.warning("   → GPU zu alt für int8 – verwende float16")
                    else:                      # CC < 3.5 (sehr alt)
                        compute_type = "float32"
                        logger.warning("   → Sehr alte GPU – verwende float32 (langsam, fallback auf CPU möglich)")
                    device = "cuda"
                except Exception as e:
                    logger.warning(f"⚠️ CUDA-Capability nicht ermittelbar, versuche int8: {e}")
                    compute_type = "int8"
                    device = "cuda"

            # AMD ROCm
            if hasattr(torch.version, "hip") and torch.version.hip:
                try:
                    if torch.cuda.device_count() > 0:
                        device = "cuda"
                        compute_type = "float16"
                        logger.info("✅ AMD GPU (ROCm) erkannt – verwende float16")
                except (AttributeError, RuntimeError) as e:
                    if self._debug:
                        logger.warning(f"⚠️ ROCm test failed: {e}")

            # Apple MPS
            if hasattr(torch.backends, "mps") and torch.backends.mps.is_available():
                device = "mps"
                compute_type = "float16"
                logger.info("✅ Apple Silicon (MPS) erkannt – verwende float16")

        logger.info(f"✅ Verwende Device: {device} (compute_type={compute_type})")
        if DEBUG_LEVEL >= 3:
            log_debug("device", f"Selected device={device}, compute_type={compute_type}")
            if device == "cuda" and self._torch:
                free = self._get_free_gpu_memory(device)
                if free is not None:
                    log_debug("vram", f"Free VRAM at startup: {free:.2f} GB")
                else:
                    log_debug("vram", "Free VRAM unknown")
        return device, compute_type

    def _get_free_gpu_memory(self, device: Optional[str] = None) -> Optional[float]:
        """Ermittelt freien GPU-Speicher in GB (bevorzugt pynvml, sonst torch)."""
        if device is None:
            device = getattr(self, "device", "cpu")
        if device != "cuda" or self._torch is None:
            return None
        torch = self._torch
        if not torch.cuda.is_available():
            return None
        try:
            import pynvml
            if not getattr(self, "_nvml_initialized", False):
                pynvml.nvmlInit()
                self._nvml_initialized = True
            if device.startswith("cuda:"):
                device_idx = int(device.split(":")[1])
            else:
                device_idx = torch.cuda.current_device()
            handle = pynvml.nvmlDeviceGetHandleByIndex(device_idx)
            mem_info = pynvml.nvmlDeviceGetMemoryInfo(handle)
            return mem_info.free / (1024**3)
        except (ImportError, pynvml.NVMLError, AttributeError):
            pass
        try:
            if device.startswith("cuda:"):
                device_idx = int(device.split(":")[1])
            else:
                device_idx = torch.cuda.current_device()
            total = torch.cuda.get_device_properties(device_idx).total_memory / (1024**3)
            reserved = torch.cuda.memory_reserved(device_idx) / (1024**3)
            return max(0.0, total - reserved)
        except (RuntimeError, AttributeError):
            return None

    def _estimate_model_memory(self, model_size: str) -> float:
        """Schätzt benötigten GPU-Speicher in GB, abhängig vom aktuellen compute_type."""
        estimates = {
            "tiny": 0.8, "tiny.en": 0.8,
            "base": 1.2, "base.en": 1.2,
            "small": 2.0, "small.en": 2.0,
            "medium": 3.0, "medium.en": 3.0,
            "large": 3.5, "large-v1": 3.5, "large-v2": 3.5,
            "large-v3": 3.5, "large-v3-turbo": 2.5,
        }
        base = estimates.get(model_size.lower(), 3.0)
        if self.compute_type == "float16":
            factor = 1.6
        elif self.compute_type == "float32":
            factor = 3.2
        else:
            factor = 1.0
        return base * factor

    def _has_enough_vram(self, model_size: str) -> bool:
        if self.device != "cuda":
            return True
        free = self._get_free_gpu_memory()
        if free is None:
            return True
        needed = self._estimate_model_memory(model_size)
        return free >= needed + 1.0   # 1 GB Puffer

    def _check_vram_before_load(self, model_size: str) -> Tuple[bool, str]:
        if self.device != "cuda":
            return True, "CPU, no VRAM check needed"
        free = self._get_free_gpu_memory()
        if free is None:
            return True, "Could not determine free VRAM"
        needed = self._estimate_model_memory(model_size)
        if free < needed:
            return False, f"Only {free:.2f} GB VRAM free, but model {model_size} needs ~{needed:.1f} GB ({self.compute_type})"
        return True, f"OK: {free:.2f} GB free, model needs ~{needed:.1f} GB"

    def _load_faster_whisper(self, model_size: str) -> Any:
        """
        Lädt faster-whisper mit automatischem Fallback über verschiedene compute_types.
        """
        try:
            WhisperModel = FastLazyLoader.load("faster_whisper")
            compute_types = [self.compute_type]
            if self.compute_type != "float16":
                compute_types.append("float16")
            if self.compute_type != "float32":
                compute_types.append("float32")
            # Entferne Duplikate, behalte Reihenfolge
            compute_types = list(dict.fromkeys(compute_types))

            for ct in compute_types:
                logger.info(f"🔄 Versuche {model_size} mit device={self.device}, compute_type={ct}")
                try:
                    model = WhisperModel(
                        model_size,
                        device=self.device,
                        compute_type=ct,
                        cpu_threads=4,
                        num_workers=1,
                    )
                    self.compute_type = ct
                    logger.info(f"✅ faster-whisper '{model_size}' geladen (compute_type={ct})")
                    return model
                except RuntimeError as e:
                    error_msg = str(e).lower()
                    if "out of memory" in error_msg or "no kernel image" in error_msg:
                        logger.warning(f"⚠️ Compute-Typ {ct} fehlgeschlagen: {e}")
                        if self.device == "cuda" and self._torch:
                            self._torch.cuda.empty_cache()
                        continue
                    else:
                        logger.exception(f"❌ faster-whisper RuntimeError: {e}")
                        return None

            # Fallback auf CPU
            logger.warning("⚠️ Alle Compute-Typen auf GPU fehlgeschlagen, versuche CPU-Fallback...")
            model = WhisperModel(
                model_size,
                device="cpu",
                compute_type="int8",
                cpu_threads=4,
                num_workers=1,
            )
            logger.info(f"✅ faster-whisper '{model_size}' auf CPU geladen (Fallback)")
            self.device = "cpu"
            self.compute_type = "int8"
            return model

        except ImportError as e:
            logger.error(f"❌ faster-whisper nicht installiert: {e}")
            return None
        except Exception as e:
            logger.exception(f"⚠️ Unerwarteter Fehler beim Laden von {model_size}: {e}")
            return None

    def _load_openai_whisper(self, model_size: str) -> Any:
        try:
            import whisper
            device = "cuda" if self.device == "cuda" else "cpu"
            model = whisper.load_model(model_size, device=device, download_root=None)
            logger.info(f"✅ openai-whisper '{model_size}' erfolgreich geladen")
            return model
        except RuntimeError as e:
            if "out of memory" in str(e).lower():
                logger.warning(f"⚠️ CUDA OOM with openai-whisper {model_size}. Trying CPU fallback.")
                if self._torch:
                    self._torch.cuda.empty_cache()
                try:
                    import whisper
                    model = whisper.load_model(model_size, device="cpu", download_root=None)
                    logger.info(f"✅ openai-whisper '{model_size}' auf CPU geladen")
                    return model
                except Exception as e2:
                    logger.exception(f"❌ openai-whisper CPU fallback failed: {e2}")
                    return None
            else:
                logger.exception(f"❌ openai-whisper fehlgeschlagen: {e}")
                return None
        except Exception as e:
            logger.exception(f"❌ openai-whisper fehlgeschlagen: {e}")
            return None

    def _perform_load(self, backend: str, model_size: str) -> Any:
        model = None
        if backend == "faster_whisper":
            model = self._load_faster_whisper(model_size)
            if model is None and OPENAI_WHISPER_AVAILABLE:
                backend = "openai_whisper"
        if backend == "openai_whisper" and model is None:
            model = self._load_openai_whisper(model_size)
        return model

    def _load_model_with_checks(self, model_size: str, backend: str, cache_key: Tuple[str, str], set_active: bool) -> Optional[Tuple[Any, str]]:
        with self._get_model_lock(model_size):
            with self._lock:
                if cache_key in self._model_cache:
                    model = self._model_cache[cache_key]
                    self._model_cache.move_to_end(cache_key)
                    if set_active:
                        self._set_active_model(model, model_size, backend, cache_key)
                    return model, backend

            # Fallback-Kette
            all_models = Config.WHISPER_MODELS
            try:
                start_index = all_models.index(model_size)
            except ValueError:
                start_index = -1
            models_to_try = [model_size]
            if start_index >= 0:
                for candidate in all_models[start_index - 1 :: -1]:
                    if candidate not in models_to_try:
                        models_to_try.append(candidate)
            backends_to_try = ["faster_whisper", "openai_whisper"]

            for current_model in models_to_try:
                for current_backend in backends_to_try:
                    if not self._is_backend_available(current_backend):
                        continue
                    if not self._has_enough_vram(current_model):
                        free = self._get_free_gpu_memory()
                        needed = self._estimate_model_memory(current_model)
                        logger.warning(f"⚠️ VRAM für {current_model} nicht ausreichend: {free:.2f} GB frei, benötigt ~{needed:.2f} GB")
                        continue
                    current_cache_key = (current_model, current_backend)
                    with self._lock:
                        if current_cache_key in self._model_cache:
                            model = self._model_cache[current_cache_key]
                            self._model_cache.move_to_end(current_cache_key)
                            if set_active and current_model == model_size and current_backend == backend:
                                self._set_active_model(model, current_model, current_backend, current_cache_key)
                            return model, current_backend

                    logger.info(f"📁 Lade Modell {current_model} mit {current_backend}...")
                    model = self._perform_load(current_backend, current_model)
                    if model is not None:
                        with self._lock:
                            self._model_cache[current_cache_key] = model
                            if len(self._model_cache) > self._max_cached_models:
                                oldest_key, old_model = next(iter(self._model_cache.items()))
                                del self._model_cache[oldest_key]
                                self._unload_model(old_model)
                        if set_active:
                            self._set_active_model(model, current_model, current_backend, current_cache_key)
                        logger.info(f"✅ {current_model} erfolgreich geladen ({current_backend})")
                        return model, current_backend
                    else:
                        logger.warning(f"❌ Laden von {current_model} mit {current_backend} fehlgeschlagen")
            raise RuntimeError("Kein Modell konnte geladen werden")

    def _is_backend_available(self, backend: str) -> bool:
        if backend == "faster_whisper":
            return FASTER_WHISPER_AVAILABLE
        if backend == "openai_whisper":
            return OPENAI_WHISPER_AVAILABLE
        return False

    def _set_active_model(self, model: Any, model_size: str, backend: str, cache_key: Tuple[str, str]) -> None:
        with self._model_usage_lock:
            if self.model is model and self.model_size == model_size and self.whisper_backend == backend:
                return
            old_model = self.model
            old_key = (self.model_size, self.whisper_backend) if self.model_size else None
            self.model = model
            self.model_size = model_size
            self.whisper_backend = backend
            self._model_loaded_flag = True

        with self._confidence_lock:
            self._last_confidence_threshold = 0.6

        if old_model is not None:
            self._unload_model(old_model)
            if old_key is not None:
                with self._lock:
                    if old_key in self._model_cache:
                        del self._model_cache[old_key]

        if self.event_bus:
            requested = getattr(self, "_requested_model", model_size)
            self.event_bus.emit("model_changed", {
                "requested": requested,
                "actual": model_size,
                "backend": backend,
                "fallback_occurred": (requested != model_size)
            })

        if self.device == "cuda" and self._torch:
            try:
                self._torch.cuda.empty_cache()
            except Exception:
                pass
        logger.info(f"✅ Aktives Modell: {model_size} ({backend})")

    def _get_model_lock(self, model_size: str) -> threading.Lock:
        with self._model_locks_lock:
            if model_size not in self._model_locks:
                self._model_locks[model_size] = threading.Lock()
            return self._model_locks[model_size]

    def _unload_model(self, model: Any) -> None:
        if model is None:
            return
        if hasattr(model, "unload_model"):
            try:
                model.unload_model()
            except Exception as e:
                logger.warning(f"⚠️ Fehler beim Aufruf von unload_model: {e}")
        else:
            del model
        if self._torch and self.device == "cuda":
            try:
                self._torch.cuda.empty_cache()
            except Exception:
                pass

    def _try_smaller_model_iterative(self) -> bool:
        current = self.model_size or "medium"
        if current not in self.MODEL_SIZE_ORDER:
            for size in self.MODEL_SIZE_ORDER:
                if size.startswith(current.split(".")[0]):
                    current = size
                    break
            else:
                current = "medium"
        current_idx = self.MODEL_SIZE_ORDER.index(current)
        for smaller in reversed(self.MODEL_SIZE_ORDER[:current_idx]):
            logger.info(f"🔄 Versuche kleineres Modell: {smaller}")
            result = self.load_model(smaller, set_active=True)
            if result is not None:
                if self.test_model_functionality():
                    return True
                else:
                    logger.warning(f"⚠️ Modell {smaller} funktioniert nicht, lösche aus Cache")
                    with self._lock:
                        cache_key = (smaller, self.whisper_backend)
                        if cache_key in self._model_cache:
                            del self._model_cache[cache_key]
                    self._unload_model(result[0])
        return False

    def _fallback_to_cpu(self) -> None:
        logger.warning("⚠️ Schalte wegen OOM auf CPU um")
        with self._model_usage_lock:
            self.device = "cpu"
            self.compute_type = "int8"
        self.set_gpu_acceleration(False)  # Auch die Einstellung aktualisieren
        current = self.model_size or "medium"
        self.load_model(current, set_active=True)

    def _handle_cuda_oom(self) -> None:
        if self.device == "cpu":
            return
        with self._lock:
            self._reloading = True
        try:
            if self._torch:
                self._torch.cuda.empty_cache()
                time.sleep(0.2)
                free = self._get_free_gpu_memory()
                if free is not None and free > 1.0:
                    logger.info(f"✅ Nach Cache‑Leerung: {free:.1f} GB frei – versuche weiter")
                    return
            if self._try_smaller_model_iterative():
                return
            self._fallback_to_cpu()
        except Exception as e:
            logger.exception(f"❌ Fehler in _handle_cuda_oom: {e}")
        finally:
            with self._lock:
                self._reloading = False

    def _force_model_cleanup(self) -> None:
        with self._model_usage_lock:
            old_model = self.model
            old_size = self.model_size
            old_backend = self.whisper_backend
            self.model = None
            self.model_size = None
            self._model_loaded_flag = False
        if old_model is not None:
            self._unload_model(old_model)
        if old_size is not None and old_backend is not None:
            with self._lock:
                cache_key = (old_size, old_backend)
                if cache_key in self._model_cache:
                    del self._model_cache[cache_key]
        gc.collect()
        if self.device == "cuda" and self._torch:
            try:
                self._torch.cuda.empty_cache()
            except Exception:
                pass

    def _prepare_transcription(self, audio_data: bytes) -> Tuple[Any, Optional[str], int, Dict[str, Any]]:
        self._load_modules()
        if self._np is None:
            raise RuntimeError("numpy is required but not available")
        with self._confidence_lock:
            last_conf = self._last_confidence_threshold
        processed = self._audio_enhancer.enhance_audio(audio_data, last_conf, 0)
        audio_np = self._np.frombuffer(processed, dtype=self._np.int16).astype(self._np.float32) / 32768.0
        beam_size = self.settings.beam_size
        language = self.forced_language if self.forced_language else None
        with self._state_lock:
            vad_language = self.forced_language or self._last_detected_language
        vad_params = self._get_vad_parameters(vad_language)
        return audio_np, language, beam_size, vad_params

    def _get_vad_parameters(self, language: Optional[str]) -> Dict[str, Any]:
        if language and language in self.config.LANGUAGE_VAD:
            lang_vad = self.config.LANGUAGE_VAD[language]
            return {
                "threshold": lang_vad["threshold"],
                "min_speech_duration_ms": lang_vad["min_speech_ms"],
                "min_silence_duration_ms": lang_vad["min_silence_ms"],
            }
        else:
            return {
                "threshold": self.settings.vad_threshold,
                "min_speech_duration_ms": self.settings.vad_min_speech_duration_ms,
                "min_silence_duration_ms": self.settings.vad_min_silence_duration_ms,
            }

    def _universal_transcribe(self, model: Any, audio_np: Any, **kwargs: Any) -> Tuple[List[Any], Any]:
        if model is None:
            raise ValueError("Kein Modell geladen")
        backend = self.whisper_backend
        allowed = self._ALLOWED_FASTER if backend == "faster_whisper" else self._ALLOWED_OPENAI
        filtered = {k: v for k, v in kwargs.items() if k in allowed}
        for attempt in range(2):
            try:
                if backend == "faster_whisper":
                    return self._faster_whisper_transcribe(model, audio_np, **filtered)
                else:
                    return self._openai_whisper_transcribe(model, audio_np, **filtered)
            except RuntimeError as e:
                if "out of memory" in str(e).lower():
                    logger.error(f"🚨 CUDA out of memory (Versuch {attempt+1}/2) – leere GPU-Cache")
                    self._handle_universal_cuda_oom()
                    if attempt == 0:
                        continue
                    else:
                        self._last_oom = True
                        raise TranscriptionError(f"CUDA OOM after retry: {e}") from e
                else:
                    raise
            except Exception as e:
                logger.warning(f"⚠️ Transkriptionsfehler: {e}")
                if attempt == 1:
                    break
                continue
        return [], _EmptyInfo()

    def _handle_universal_cuda_oom(self) -> None:
        if self._torch and self.device == "cuda":
            self._torch.cuda.empty_cache()
            time.sleep(0.5)

    def _faster_whisper_transcribe(self, model: Any, audio_np: Any, **kwargs: Any) -> Tuple[List[Any], Any]:
        try:
            vad_params = kwargs.pop("vad_parameters", None)
            if kwargs.get("vad_filter", False) and vad_params is None:
                vad_params = {
                    "threshold": self.settings.vad_threshold,
                    "min_speech_duration_ms": self.settings.vad_min_speech_duration_ms,
                    "min_silence_duration_ms": self.settings.vad_min_silence_duration_ms,
                }
                language = kwargs.get("language")
                if language and language in self.config.LANGUAGE_VAD:
                    lang_vad = self.config.LANGUAGE_VAD[language]
                    vad_params.update({
                        "threshold": lang_vad["threshold"],
                        "min_speech_duration_ms": lang_vad["min_speech_ms"],
                        "min_silence_duration_ms": lang_vad["min_silence_ms"],
                    })
            if vad_params is not None:
                kwargs["vad_parameters"] = vad_params
            segments, info = model.transcribe(audio_np, **kwargs)
            return list(segments), info
        except (TypeError, ValueError) as e:
            if self._debug:
                logger.warning(f"⚠️ faster-whisper Parameterfehler: {e} – verwende minimale Parameter")
            minimal = {k: v for k, v in kwargs.items() if k in ["language", "task", "temperature", "beam_size", "best_of"]}
            segments, info = model.transcribe(audio_np, **minimal)
            return list(segments), info
        except Exception as e:
            logger.exception(f"❌ faster-whisper Fehler: {e}")
            return [], _EmptyInfo()

    def _openai_whisper_transcribe(self, model: Any, audio_np: Any, **kwargs: Any) -> Tuple[List[Any], Any]:
        filtered = {k: v for k, v in kwargs.items() if k in self._ALLOWED_OPENAI}
        filtered.setdefault("language", None)
        filtered.setdefault("task", "transcribe")
        filtered.setdefault("temperature", 0.0)
        try:
            result = model.transcribe(audio_np, **filtered)
            segments = result.get("segments", [])
            converted = [_UniversalSegment(seg) for seg in segments if seg.get("text", "").strip()]
            info = _UniversalInfo(result)
            return converted, info
        except Exception as e:
            logger.exception(f"❌ openai-whisper Fehler: {e}")
            try:
                fallback_result = model.transcribe(audio_np, language=None, task="transcribe", temperature=0.1)
                emergency = [_EmergencySegment(seg) for seg in fallback_result.get("segments", [])]
                return emergency, _UniversalInfo(fallback_result)
            except Exception as e2:
                logger.error(f"💥 Auch Fallback fehlgeschlagen: {e2}")
                return [], _EmptyInfo()

    def _prepare_transcribe_kwargs(self, language: Optional[str], beam_size: int, vad_params: Dict[str, Any],
                                   include_timestamps: bool, hotwords: str = "", best_of: int = 5,
                                   patience: float = 1.0, no_speech_threshold: float = 0.6,
                                   log_prob_threshold: float = -1.2, compression_ratio_threshold: float = 2.8,
                                   condition_on_previous_text: bool = True, suppress_tokens: str = "-1") -> Dict[str, Any]:
        kwargs = {
            "language": language,
            "task": "transcribe",
            "temperature": self.settings.temperature,
            "best_of": best_of,
            "beam_size": beam_size,
            "patience": patience,
            "no_speech_threshold": no_speech_threshold,
            "log_prob_threshold": log_prob_threshold,
            "compression_ratio_threshold": compression_ratio_threshold,
            "condition_on_previous_text": condition_on_previous_text,
            "suppress_tokens": self._parse_suppress_tokens(suppress_tokens),
            "without_timestamps": False,
            "word_timestamps": include_timestamps,
        }
        if self.settings.vad_filter:
            kwargs["vad_filter"] = True
            kwargs["vad_parameters"] = vad_params
        else:
            kwargs["vad_filter"] = False
        if hotwords:
            kwargs["hotwords"] = hotwords
        return kwargs

    def _transcribe_worker(self, model: Any, audio_np: Any, language: Optional[str], beam_size: int,
                          vad_params: Dict[str, Any], include_timestamps: bool, **kwargs) -> Any:
        transcribe_kwargs = self._prepare_transcribe_kwargs(language, beam_size, vad_params, include_timestamps, **kwargs)
        configs = [{"name": "Standard", "kwargs": transcribe_kwargs}]
        if self.settings.vad_filter:
            no_vad = transcribe_kwargs.copy()
            no_vad["vad_filter"] = False
            no_vad.pop("vad_parameters", None)
            configs.append({"name": "VAD deaktiviert", "kwargs": no_vad})
            no_vad_low = no_vad.copy()
            no_vad_low["no_speech_threshold"] = 0.3
            configs.append({"name": "VAD deaktiviert + low threshold", "kwargs": no_vad_low})

        segments, info = [], None
        for cfg in configs:
            try:
                seg, inf = self._universal_transcribe(model, audio_np, **cfg["kwargs"])
                if seg:
                    segments, info = seg, inf
                    break
            except Exception as e:
                logger.warning(f"⚠️ Transkriptionsversuch {cfg['name']} fehlgeschlagen: {e}")
        if info is not None:
            self._update_detected_language(info)
        valid_segments, total_confidence = self._process_segments(segments, info)
        if not valid_segments:
            minimal = self._transcribe_minimal(model, audio_np, language)
            if minimal:
                if include_timestamps:
                    duration = audio_np.shape[0] / self.config.SAMPLE_RATE
                    return [TranscriptionResult(text=minimal.text, confidence=minimal.confidence,
                                                language=minimal.language, start=0.0, end=duration)]
                return minimal
            return [] if include_timestamps else None
        if include_timestamps:
            return self._create_timestamped_results(valid_segments, info)
        else:
            return self._create_continuous_result(valid_segments, info, total_confidence)

    def _update_detected_language(self, info: Any) -> None:
        if hasattr(info, "language") and info.language != "unknown":
            with self._state_lock:
                self._last_detected_language = info.language

    def _process_segments(self, segments: List[Any], info: Any) -> Tuple[List[Any], float]:
        valid = []
        total_conf = 0.0
        for seg in segments:
            text = seg.text.strip()
            conf = self._calculate_enhanced_confidence(seg, text)
            if self.is_valid_segment(text, conf):
                valid.append(seg)
                total_conf += conf
        return valid, total_conf

    def _create_timestamped_results(self, segments: List[Any], info: Any) -> List[TranscriptionResult]:
        return [TranscriptionResult(text=seg.text.strip(),
                                    confidence=self._calculate_enhanced_confidence(seg, seg.text.strip()),
                                    language=getattr(info, "language", "unknown"),
                                    start=getattr(seg, "start", 0.0),
                                    end=getattr(seg, "end", 0.0)) for seg in segments]

    def _create_continuous_result(self, segments: List[Any], info: Any, total_confidence: float) -> TranscriptionResult:
        full_text = " ".join(seg.text.strip() for seg in segments)
        avg_conf = total_confidence / len(segments)
        return TranscriptionResult(text=full_text, confidence=avg_conf, language=getattr(info, "language", "unknown"))

    def _transcribe_minimal(self, model: Any, audio_np: Any, language: Optional[str],
                            fallback_config: Optional[Dict[str, Any]] = None) -> Optional[TranscriptionResult]:
        try:
            if fallback_config is None:
                segments, info = self._universal_transcribe(
                    model, audio_np, language=language, task="transcribe", temperature=0.0,
                    best_of=1, beam_size=1, no_speech_threshold=0.9, log_prob_threshold=-2.0,
                    compression_ratio_threshold=3.5, condition_on_previous_text=False,
                    without_timestamps=False, vad_filter=False
                )
            else:
                segments, info = self._universal_transcribe(model, audio_np, **fallback_config)
            if segments:
                seg = segments[0]
                text = seg.text.strip()
                if text:
                    conf = self._calculate_enhanced_confidence(seg, text)
                    return TranscriptionResult(text=text, confidence=conf, language=getattr(info, "language", "unknown"))
        except Exception as e:
            if self._debug:
                logger.debug(f"Minimal transcription failed: {e}")
        return None

    def _calculate_enhanced_confidence(self, segment: Any, text: str) -> float:
        base = max(getattr(segment, "confidence", 0.0), 0.1)
        words = text.split()
        word_count = len(words)
        text_len = len(text.strip())
        lang = getattr(segment, "language", "unknown")
        if lang in ("zh", "ja", "ko", "th", "vi"):
            chars = list(text)
            unique_ratio = len(set(chars)) / max(len(chars), 1)
        else:
            unique_ratio = len(set(words)) / max(word_count, 1)
        boosts = (min(0.2, text_len / 300.0) +
                  min(0.15, word_count * 0.03) +
                  (0.08 if any(c in text for c in ".!?,;:") else 0.0) +
                  (0.1 if any(c.isalpha() for c in text) else 0.0) +
                  min(0.1, unique_ratio * 0.1))
        total_boost = min(0.3, boosts)
        return min(0.95, base + total_boost)

    def _parse_suppress_tokens(self, token_str: str) -> List[int]:
        if not token_str:
            return [-1]
        try:
            return [int(x.strip()) for x in token_str.split(",")]
        except ValueError:
            if self._debug:
                logger.warning(f"Ungültiges suppress_tokens Format: {token_str}, verwende [-1]")
            return [-1]


class DummyTranscriptionEngine:
    """
    Platzhalter‑Engine, wenn kein Whisper‑Backend verfügbar ist.
    Thread‑sicher und gibt konsistente Dummy‑Ergebnisse zurück.

    Implementiert alle Methoden der echten TranscriptionEngine,
    sodass sie ohne weitere Anpassungen in der GUI und im AudioProcessor
    verwendet werden kann.
    """

    def __init__(
        self,
        settings: Optional["AdvancedSettings"] = None,
        cache_manager: Optional[CacheManager] = None,
        event_bus: Optional[EventBus] = None,      # optional, wird ignoriert
    ) -> None:
        """
        Initialisiert die Dummy‑Engine.

        Args:
            settings: Erweiterte Einstellungen (optional).
            cache_manager: Cache‑Manager (optional).
            event_bus: Event‑Bus (optional, wird ignoriert).
        """
        self.settings = settings or AdvancedSettings()
        self.cache_manager = cache_manager or AppContext().cache_manager
        self.model: Any = None
        self.model_size = "dummy"
        self.whisper_backend: Optional[str] = None
        self.demo_mode = True
        self.device = "cpu"
        self.compute_type = "int8"
        self.forced_language: Optional[str] = None

        self._lock = threading.RLock()
        self._last_result: Optional[TranscriptionResult] = None
        self._last_audio_hash: Optional[str] = None
        self._disposing = False
        self._reloading = False
        self._model_loaded_flag = True
        self._vad_fallback_enabled = False

        # Dummy‑Cache für Audiodaten (optional)
        self._audio_cache: Dict[str, TranscriptionResult] = {}
        self._cache_max_size = 50

        logger.info("📟 DummyTranscriptionEngine initialisiert (Demo‑Modus)")

    # -------------------------------------------------------------------------
    # Öffentliche Methoden (kompatibel zu TranscriptionEngine)
    # -------------------------------------------------------------------------
    def load_model(
        self, model_size: str, set_active: bool = False
    ) -> Optional[Tuple[Any, str]]:
        """
        Simuliert das Laden eines Modells.
        Gibt immer ein Dummy‑Modell zurück.
        """
        with self._lock:
            logger.info(f"Dummy‑Modus: Laden von '{model_size}' nicht erforderlich.")
            self.model_size = model_size
            return (None, "dummy")

    def transcribe_audio(
        self, audio_data: bytes, include_timestamps: bool = False
    ) -> Any:
        """
        Gibt ein Dummy‑Transkriptionsergebnis zurück.
        Bei wiederholten Aufrufen mit identischen Audiodaten wird das gleiche
        Ergebnis geliefert (optionales Caching).
        """
        with self._lock:
            # Optional: Cache basierend auf Audio‑Hash
            audio_hash = hashlib.sha256(audio_data).hexdigest() if audio_data else None
            if self._last_audio_hash == audio_hash and self._last_result is not None:
                result = self._last_result
            else:
                if include_timestamps:
                    # Für Untertitel‑Modus: Liste von Segmenten
                    result = [
                        TranscriptionResult(
                            text="[Whisper nicht verfügbar – Dummy‑Transkription]",
                            confidence=0.5,
                            language="de",
                            start=0.0,
                            end=5.0,
                        )
                    ]
                else:
                    result = TranscriptionResult(
                        text="[Whisper nicht verfügbar – Dummy‑Transkription]",
                        confidence=0.5,
                        language="de",
                    )
                # Cache speichern (für identische Audiodaten)
                self._last_audio_hash = audio_hash
                self._last_result = result

                # Cache‑Größe begrenzen
                if len(self._audio_cache) >= self._cache_max_size:
                    self._audio_cache.pop(next(iter(self._audio_cache)))
                if audio_hash:
                    self._audio_cache[audio_hash] = result

            return result

    def safe_transcribe(
        self, audio_data: bytes, max_retries: int = 2
    ) -> Optional[TranscriptionResult]:
        """
        Sicherer Aufruf, der die gleiche Dummy‑Transkription wie transcribe_audio
        liefert, aber im nicht‑Timestamp‑Modus.
        """
        result = self.transcribe_audio(audio_data, include_timestamps=False)
        if isinstance(result, list) and result:
            return result[0]
        return result

    def emergency_fallback_transcription(
        self, audio_data: Union[bytes, Any]
    ) -> Optional[TranscriptionResult]:
        """Notfall‑Methode – identisch zu safe_transcribe."""
        return self.safe_transcribe(audio_data)

    def is_functional(self) -> bool:
        """Gibt immer False zurück, da es sich um eine Dummy‑Engine handelt."""
        return False

    def get_current_model(self) -> str:
        """Gibt den Namen des aktuell geladenen Modells zurück."""
        with self._lock:
            return self.model_size

    def is_model_loading(self) -> bool:
        """Gibt immer False zurück (kein asynchrones Laden)."""
        return False

    def reload_model(self, model_size: str) -> bool:
        """Simuliert das Neuladen eines Modells."""
        with self._lock:
            self.model_size = model_size
            logger.info(f"Dummy: Modell auf '{model_size}' gewechselt")
            return True

    def test_model_functionality(self) -> bool:
        """Gibt immer True zurück (Dummy ist funktional)."""
        return True

    def set_vad_fallback_enabled(self, enabled: bool) -> None:
        """
        Aktiviert oder deaktiviert den VAD‑Fallback.
        Dummy‑Implementierung – hat keine Wirkung, speichert nur den Zustand.
        """
        with self._lock:
            self._vad_fallback_enabled = enabled
            logger.debug(f"Dummy: VAD‑Fallback auf {enabled} gesetzt")

    def set_gpu_acceleration(self, enabled: bool) -> None:
        """
        Aktiviert oder deaktiviert die GPU‑Beschleunigung.
        Dummy‑Implementierung – hat keine Wirkung.
        """
        logger.debug(f"Dummy: GPU‑Acceleration auf {enabled} gesetzt (ignoriert)")

    def validate_audio_data(self, audio_data: bytes) -> Tuple[bool, str]:
        """Überprüft, ob Audiodaten gültig sind (minimale Prüfung)."""
        if not isinstance(audio_data, bytes):
            return False, "Audio data must be bytes"
        if len(audio_data) == 0:
            return False, "Audio data is empty"
        return True, "Valid"

    def is_valid_segment(self, text: str, confidence: float) -> bool:
        """Prüft, ob ein Segment gültig ist (minimale Prüfung)."""
        return bool(text and text.strip())

    def clear_cache(self) -> None:
        """Leert den internen Cache."""
        with self._lock:
            self._audio_cache.clear()
            self._last_result = None
            self._last_audio_hash = None

    def dispose(self) -> None:
        """Gibt alle Ressourcen frei."""
        with self._lock:
            self._disposing = True
            self._audio_cache.clear()
            self._last_result = None
            self._last_audio_hash = None
        logger.info("🧹 DummyTranscriptionEngine disposed")

    # -------------------------------------------------------------------------
    # Zusätzliche Kompatibilitätsmethoden (von GUI erwartet)
    # -------------------------------------------------------------------------
    def get_status(self) -> Dict[str, Any]:
        """Gibt einen Status‑Dictionary zurück (für Statistiken)."""
        return {
            "model": self.model_size,
            "device": self.device,
            "compute_type": self.compute_type,
            "backend": "dummy",
            "functional": False,
            "demo_mode": True,
        }

    def __repr__(self) -> str:
        return f"<DummyTranscriptionEngine model='{self.model_size}'>"


# =============================================================================
# 15. PLUGIN-KLASSEN (Plugin, PluginManager)
# =============================================================================
class Plugin(ABC):
    def __init__(self, name: str, version: str = "1.0.0", max_errors: int = 3):
        self.name = name
        self.version = version
        self.enabled = True
        self._disabled = False
        self._error_count = 0
        self._max_errors = max_errors
        self.config: Dict[str, Any] = {}
        self._lock = threading.RLock()

    def _handle_error(self, method_name: str, error: Exception) -> None:
        with self._lock:
            self._error_count += 1
            logger.warning(
                f"Plugin '{self.name}' Fehler in {method_name}: {error} "
                f"({self._error_count}/{self._max_errors})"
            )
            if self._error_count >= self._max_errors:
                self._disabled = True
                logger.error(
                    f"❌ Plugin '{self.name}' wurde wegen zu vieler Fehler deaktiviert. "
                    f"Bitte überprüfen Sie das Plugin oder laden Sie es neu."
                )

    def is_functional(self) -> bool:
        with self._lock:
            return self.enabled and not self._disabled

    def reset_errors(self) -> None:
        with self._lock:
            self._error_count = 0
            self._disabled = False
            logger.info(f"Plugin '{self.name}' Fehlerzähler zurückgesetzt.")

    def on_load(self, manager: "PluginManager") -> None:
        try:
            self._on_load_impl(manager)
        except Exception as e:
            self._handle_error("on_load", e)

    def _on_load_impl(self, manager: "PluginManager") -> None:
        pass

    def on_unload(self) -> None:
        try:
            self._on_unload_impl()
        except Exception as e:
            self._handle_error("on_unload", e)

    def _on_unload_impl(self) -> None:
        pass

    def on_config_change(self, new_config: Dict[str, Any]) -> None:
        try:
            with self._lock:
                self.config.update(new_config)
            self._on_config_change_impl(new_config)
        except Exception as e:
            self._handle_error("on_config_change", e)

    def _on_config_change_impl(self, new_config: Dict[str, Any]) -> None:
        pass

    def on_start(self) -> None:
        try:
            self._on_start_impl()
        except Exception as e:
            self._handle_error("on_start", e)

    def _on_start_impl(self) -> None:
        pass

    def on_stop(self) -> None:
        try:
            self._on_stop_impl()
        except Exception as e:
            self._handle_error("on_stop", e)

    def _on_stop_impl(self) -> None:
        pass

    def on_transcription(self, result: TranscriptionResult) -> TranscriptionResult:
        if not self.is_functional():
            return result
        try:
            return self._on_transcription_impl(result)
        except Exception as e:
            self._handle_error("on_transcription", e)
            return result

    def _on_transcription_impl(
        self, result: TranscriptionResult
    ) -> TranscriptionResult:
        return result

    def on_translation(self, result: TranslationResult) -> TranslationResult:
        if not self.is_functional():
            return result
        try:
            return self._on_translation_impl(result)
        except Exception as e:
            self._handle_error("on_translation", e)
            return result

    def _on_translation_impl(self, result: TranslationResult) -> TranslationResult:
        return result

    def get_config_ui(self, parent) -> Optional[Any]:
        try:
            return self._get_config_ui_impl(parent)
        except Exception as e:
            self._handle_error("get_config_ui", e)
            return None

    def _get_config_ui_impl(self, parent) -> Optional[Any]:
        return None

    def __repr__(self) -> str:
        status = "enabled" if self.is_functional() else "disabled"
        return f"<Plugin {self.name} v{self.version} {status}>"


class PluginManager:
    def __init__(self):
        self._plugins: List[Plugin] = []
        self._plugin_map: Dict[str, Plugin] = {}
        self._lock = threading.RLock()
        self._global_enabled = True
        self._event_handlers = {
            "transcription": [],
            "translation": [],
            "start": [],
            "stop": [],
        }

    def register_plugin(self, plugin: Plugin) -> bool:
        with self._lock:
            if plugin.name in self._plugin_map:
                logger.warning(
                    f"Plugin '{plugin.name}' bereits registriert – überspringe."
                )
                return False
            self._plugins.append(plugin)
            self._plugin_map[plugin.name] = plugin
            try:
                plugin.on_load(self)
                logger.info(f"✅ Plugin geladen: {plugin.name} v{plugin.version}")
            except Exception as e:
                logger.error(f"❌ Fehler beim Laden von Plugin {plugin.name}: {e}")
                plugin.enabled = False
            return True

    def unregister_plugin(self, plugin_name: str) -> bool:
        with self._lock:
            if plugin_name not in self._plugin_map:
                return False
            plugin = self._plugin_map[plugin_name]
            try:
                plugin.on_unload()
            except Exception as e:
                logger.error(f"Fehler beim Entladen von {plugin_name}: {e}")
            self._plugins.remove(plugin)
            del self._plugin_map[plugin_name]
            logger.info(f"Plugin entfernt: {plugin_name}")
            return True

    def get_plugin(self, name: str) -> Optional[Plugin]:
        return self._plugin_map.get(name)

    def list_plugins(self) -> List[Plugin]:
        with self._lock:
            return self._plugins.copy()

    def set_plugin_enabled(self, name: str, enabled: bool) -> bool:
        plugin = self.get_plugin(name)
        if plugin:
            plugin.enabled = enabled
            logger.info(f"Plugin {name} {'aktiviert' if enabled else 'deaktiviert'}")
            return True
        return False

    def set_global_enabled(self, enabled: bool) -> None:
        with self._lock:
            self._global_enabled = enabled

    def process_transcription(self, result: TranscriptionResult) -> TranscriptionResult:
        if not self._global_enabled:
            return result
        with self._lock:
            plugins = self._plugins.copy()
        for plugin in plugins:
            if not plugin.enabled:
                continue
            try:
                result = plugin.on_transcription(result)
            except Exception as e:
                logger.warning(f"Plugin {plugin.name} Fehler in on_transcription: {e}")
        return result

    def process_translation(self, result: TranslationResult) -> TranslationResult:
        if not self._global_enabled:
            return result
        with self._lock:
            plugins = self._plugins.copy()
        for plugin in plugins:
            if not plugin.enabled:
                continue
            try:
                result = plugin.on_translation(result)
            except Exception as e:
                logger.warning(f"Plugin {plugin.name} Fehler in on_translation: {e}")
        return result

    def on_start(self) -> None:
        if not self._global_enabled:
            return
        with self._lock:
            plugins = self._plugins.copy()
        for plugin in plugins:
            if not plugin.enabled:
                continue
            try:
                plugin.on_start()
            except Exception as e:
                logger.warning(f"Plugin {plugin.name} Fehler in on_start: {e}")

    def on_stop(self) -> None:
        if not self._global_enabled:
            return
        with self._lock:
            plugins = self._plugins.copy()
        for plugin in plugins:
            if not plugin.enabled:
                continue
            try:
                plugin.on_stop()
            except Exception as e:
                logger.warning(f"Plugin {plugin.name} Fehler in on_stop: {e}")

    def load_config(self, config_data: Dict[str, Dict[str, Any]]) -> None:
        for name, data in config_data.items():
            plugin = self.get_plugin(name)
            if plugin:
                enabled = data.get("enabled", True)
                plugin.enabled = enabled
                plugin_config = data.get("config", {})
                plugin.on_config_change(plugin_config)

    def save_config(self) -> Dict[str, Dict[str, Any]]:
        config = {}
        with self._lock:
            for plugin in self._plugins:
                config[plugin.name] = {
                    "enabled": plugin.enabled,
                    "config": plugin.config.copy(),
                }
        return config

    def dispose(self) -> None:
        with self._lock:
            plugins = self._plugins.copy()
        for plugin in plugins:
            try:
                plugin.on_unload()
            except Exception as e:
                logger.warning(f"Fehler beim Entladen von {plugin.name}: {e}")
        with self._lock:
            self._plugins.clear()
            self._plugin_map.clear()


# =============================================================================
# 16. MANAGER (StreamManager, YtDlpHelper, FFmpegManager, StreamInfoExtractor, ExportManager, ResourceManager, LanguageDetector, OllamaSummarizer, QueueManager)
# =============================================================================
class StreamManager:
    _YOUTUBE_DOMAINS = ("youtube.com", "youtu.be", "googlevideo.com")
    _LIVE_INDICATORS = (
        "/live",
        "live=1",
        "/stream",
        "livestream",
        "live/",
        "&live",
        "?live",
        "/watch_live",
    )
    _DVB_SCHEMES = ("dvb://", "dvb-s://")
    _FILE_SCHEME = "file://"
    _HTTP_SCHEMES = ("http://", "https://")

    _FORMAT_PRIORITIES = {
        "youtube": ["bestaudio[ext=m4a]/bestaudio/best", "bestaudio/best", "ba"],
        "youtube_live": ["bestaudio/best", "ba"],
        "twitch": ["bestaudio/best", "audio_only"],
        "tiktok": ["bestaudio/best"],
        "facebook": ["bestaudio/best"],
        "hls": ["bestaudio/best"],
        "dash": ["bestaudio/best"],
        "generic": ["bestaudio/best", "ba"],
        "kick": ["bestaudio/best", "ba"],
        "rumble": ["bestaudio/best", "ba"],
        "dailymotion": ["bestaudio/best", "ba"],
        "vimeo": ["bestaudio/best", "ba"],
        "twitter": ["bestaudio/best", "ba"],
    }

    _BROWSERS = [
        ("firefox", "Firefox"),
        ("chrome", "Chrome"),
        ("brave", "Brave"),
        ("edge", "Edge"),
        ("chromium", "Chromium"),
        ("opera", "Opera"),
        ("vivaldi", "Vivaldi"),
    ]

    _YOUTUBE_ID_REGEX = re.compile(
        r"(?:youtube\.com/(?:watch\?v=|embed/|v/|shorts/)|youtu\.be/)([a-zA-Z0-9_-]{11})"
    )

    def __init__(
        self,
        enable_debug: bool = False,
        use_browser_cookies: bool = True,
        proxy: str = "",
        proxy_enabled: bool = False,
        cache_ttl_platform: int = 3600,
        cache_ttl_audio: int = 1800,
        cache_ttl_fail: int = 300,
        cache_ttl_live: int = 300,
        cache_ttl_info: int = 600,
    ) -> None:
        self._platform_cache = TTLCache(maxsize=50, ttl=cache_ttl_platform)
        self._audio_url_cache = TTLCache(maxsize=50, ttl=cache_ttl_audio)
        self._audio_url_fail_cache = TTLCache(maxsize=50, ttl=cache_ttl_fail)
        self._live_status_cache = TTLCache(maxsize=30, ttl=cache_ttl_live)
        self._stream_info_cache = TTLCache(maxsize=30, ttl=cache_ttl_info)

        self._debug = enable_debug
        self.use_browser_cookies = use_browser_cookies
        self._proxy = proxy
        self._proxy_enabled = proxy_enabled
        self._last_error: Optional[str] = None
        self._last_method: Optional[str] = None

        self._stats = {
            "extraction_attempts": 0,
            "successful_extractions": 0,
            "cache_hits": 0,
            "errors": 0,
            "start_time": time.time(),
        }
        self._stats_lock = threading.RLock()

        self._dvb_processes: List[subprocess.Popen] = []
        self._dvb_lock = threading.RLock()
        self._dvb_monitor_stop = threading.Event()
        self._dvb_monitor_thread: Optional[threading.Thread] = None
        self._start_dvb_monitor()

        self._user_agents = {
            "desktop": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36",
            "mobile": "Mozilla/5.0 (Linux; Android 10; SM-G975F) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Mobile Safari/537.36",
        }

        # --- NEU: atexit-Handler für saubere DVB-Prozessbereinigung ---
        self._disposed = False
        atexit.register(self._atexit_cleanup)

    def _atexit_cleanup(self) -> None:
        """Wird bei Programmende aufgerufen, falls dispose noch nicht erfolgte."""
        if not self._disposed:
            self.dispose()

    def set_proxy(self, proxy: str, enabled: bool = False) -> None:
        self._proxy = proxy
        self._proxy_enabled = enabled
        if self._debug:
            logger.debug(f"🌐 Proxy gesetzt: {proxy} (aktiv: {enabled})")

    def detect_platform(self, url: str) -> Tuple[str, str]:
        if not url:
            return ("unknown", "Invalid URL")

        url = PlatformUtils.sanitize_url(url)
        cached = self._platform_cache.get(url)
        if cached is not None:
            with self._stats_lock:
                self._stats["cache_hits"] += 1
            if self._debug:
                logger.debug(f"🔍 detect_platform: Cache-Treffer für {url[:50]}...")
            return cached

        result, reason_str = self._detect_platform_impl(url)
        self._platform_cache.put(url, result)
        if self._debug:
            logger.debug(
                f"🔍 detect_platform: {url[:50]}... -> {result}, reason: {reason_str}"
            )
        return result

    def extract_audio_url(self, url: str, force_refresh: bool = False) -> Optional[str]:
        """
        Extrahiert die direkte Audio-URL aus einer Video-URL.
        Unterstützt lokale Dateien, DVB-Streams, YouTube und viele andere Plattformen.
        Verwendet Caching, um wiederholte Anfragen zu vermeiden.
        """
        with self._stats_lock:
            self._stats["extraction_attempts"] += 1

        self._last_error = None
        self._last_method = None

        # URL-Validierung
        valid, msg = PlatformUtils.validate_url(url)
        if not valid:
            logger.error(f"❌ Ungültige URL: {msg}")
            self._last_error = msg
            with self._stats_lock:
                self._stats["errors"] += 1
            return None

        # Prüfe, ob yt-dlp verfügbar ist
        if not shutil.which("yt-dlp"):
            self._last_error = "yt-dlp not found in PATH"
            logger.error(self._last_error)
            with self._stats_lock:
                self._stats["errors"] += 1
            return None

        url = PlatformUtils.sanitize_url(url)
        if not url:
            self._last_error = "Empty URL"
            with self._stats_lock:
                self._stats["errors"] += 1
            return None

        # --- DVB-Streams: Normalisierung und Start ---
        if url.startswith(self._DVB_SCHEMES):
            # Normalisiere dvb:// nach dvb-s://, falls nötig
            if url.startswith("dvb://"):
                url = url.replace("dvb://", "dvb-s://", 1)
                logger.debug(f"Normalized DVB URL: {url}")

            logger.info("📡 DVB-Stream erkannt, starte VLC-Server...")
            result = self._start_dvb_stream(url)
            if result:
                with self._stats_lock:
                    self._stats["successful_extractions"] += 1
                self._last_method = "dvb_vlc"
            else:
                with self._stats_lock:
                    self._stats["errors"] += 1
                self._last_error = "DVB stream could not be started"
            return result

        # Cache prüfen
        if not force_refresh:
            cached = self._audio_url_cache.get(url)
            if cached:
                with self._stats_lock:
                    self._stats["cache_hits"] += 1
                if self._debug:
                    if DEBUG_LEVEL >= 3:
                        logger.debug(f"📦 Audio-URL Cache-Treffer für {url}")
                    else:
                        logger.debug(f"📦 Audio-URL Cache-Treffer für {url[:50]}...")
                return cached

            if self._audio_url_fail_cache.get(url):
                if self._debug:
                    if DEBUG_LEVEL >= 3:
                        logger.debug(f"📦 Audio-URL Fail-Cache-Treffer für {url}")
                    else:
                        logger.debug(
                            f"📦 Audio-URL Fail-Cache-Treffer für {url[:50]}..."
                        )
                return None

        platform_id, platform_name = self.detect_platform(url)
        if self._debug:
            logger.debug(f"🔍 Plattform erkannt: {platform_id} ({platform_name})")

        result = None
        extraction_method = "unknown"

        # Lokale Datei
        if url.startswith(self._FILE_SCHEME):
            ok, real_path = PlatformUtils.validate_file_path(url)
            if ok:
                result = url
                extraction_method = "local_file"
            else:
                self._last_error = real_path

        # Direkte Media-URL (z.B. mp3, mp4)
        elif self._is_direct_media_url(url):
            result = url
            extraction_method = "direct_link"

        # YouTube optimierte Extraktion
        if not result and platform_id in ("youtube", "youtube_live"):
            if self._debug:
                logger.debug("🎯 YouTube erkannt, verwende optimierte Extraktion...")
            result = self._extract_youtube_audio_optimized(url, platform_id)
            extraction_method = "youtube_optimized"

        # Generische Extraktion
        if not result:
            result, method = self._extract_generic_audio(url, platform_id)
            if method:
                extraction_method = method

        # JSON-Fallback
        if not result:
            result, error = self._try_json_fallback(url)
            if result:
                extraction_method = "json_fallback"
            elif error:
                self._last_error = error

        if result:
            self._audio_url_cache.put(url, result)
            with self._stats_lock:
                self._stats["successful_extractions"] += 1
        else:
            self._audio_url_fail_cache.put(url, True)
            if not self._last_error:
                self._last_error = "No audio URL could be extracted"
            with self._stats_lock:
                self._stats["errors"] += 1

        self._last_method = extraction_method
        if self._debug and result:
            if DEBUG_LEVEL >= 3:
                logger.debug(f"🎵 EXTRACT_AUDIO_URL ENDE - Ergebnis: {result}")
            else:
                logger.debug(f"🎵 EXTRACT_AUDIO_URL ENDE - Ergebnis: {result[:80]}...")
        return result

    def reset_stats(self) -> None:
        with self._stats_lock:
            self._stats = {
                "extraction_attempts": 0,
                "successful_extractions": 0,
                "cache_hits": 0,
                "errors": 0,
                "start_time": time.time(),
            }

    def dispose(self, force: bool = False) -> None:
        """
        Gibt alle Ressourcen des StreamManagers frei, insbesondere DVB‑Prozesse.

        Args:
            force: Wenn True, werden Ressourcen sofort freigegeben (kein Warten auf Threads,
                   Prozesse werden direkt gekillt). Für reguläres Beenden sollte force=False
                   verwendet werden.
        """
        if self._disposed:
            return
        self._disposed = True

        # 1. DVB-Monitor-Thread beenden (mit Event)
        if hasattr(self, "_dvb_monitor_stop"):
            self._dvb_monitor_stop.set()
            if self._dvb_monitor_thread and self._dvb_monitor_thread.is_alive():
                timeout = 0.5 if force else 2.0
                self._dvb_monitor_thread.join(timeout=timeout)
                if self._dvb_monitor_thread.is_alive():
                    logger.warning(
                        "⚠️ DVBMonitor thread did not terminate within timeout"
                    )
                else:
                    logger.debug("✅ DVBMonitor thread terminated")
        else:
            # Fallback für ältere Instanzen ohne Event
            if self._dvb_monitor_thread and self._dvb_monitor_thread.is_alive():
                logger.debug(
                    "DVBMonitor thread still alive, but no stop event – forcing termination"
                )
                # Daemon-Thread wird beim Programmende ohnehin abgeschossen – nur Log

        # 2. Alle Caches leeren
        self.clear_caches()

        # 3. DVB-Prozesse terminieren
        with self._dvb_lock:
            for proc in self._dvb_processes:
                try:
                    if force:
                        # Bei erzwungenem Shutdown sofort killen
                        proc.kill()
                        if self._debug:
                            logger.debug(f"Killed DVB process {proc.pid}")
                    else:
                        # Normaler Shutdown: erst terminieren, dann ggf. killen
                        proc.terminate()
                        try:
                            proc.wait(timeout=1)
                        except subprocess.TimeoutExpired:
                            proc.kill()
                            proc.wait(timeout=0.5)
                        if self._debug:
                            logger.debug(f"Terminated DVB process {proc.pid}")
                except Exception as e:
                    if self._debug:
                        logger.debug(f"Error while terminating DVB process: {e}")
            self._dvb_processes.clear()

        if self._debug:
            logger.debug("🔌 StreamManager disposed")

    def clear_caches(self) -> None:
        self._platform_cache.clear()
        self._audio_url_cache.clear()
        self._audio_url_fail_cache.clear()
        self._live_status_cache.clear()
        self._stream_info_cache.clear()
        if self._debug:
            logger.debug("🗑️ Alle Caches geleert")

    def get_stats(self) -> Dict[str, Any]:
        with self._stats_lock:
            stats = self._stats.copy()
            stats["uptime_seconds"] = time.time() - stats["start_time"]
            if stats["extraction_attempts"] > 0:
                stats["success_rate"] = (
                    stats["successful_extractions"] / stats["extraction_attempts"] * 100
                )
            else:
                stats["success_rate"] = 0.0
            stats["last_error"] = self._last_error
            stats["last_method"] = self._last_method
            return stats

    def _detect_platform_impl(self, url: str) -> Tuple[Tuple[str, str], str]:
        url_lower = url.lower()
        reasons = []

        if url_lower.startswith(self._DVB_SCHEMES):
            return (("dvb", "DVB-S Stream"), "dvb protocol")

        if url_lower.startswith(self._FILE_SCHEME):
            ok, _ = PlatformUtils.validate_file_path(url)
            if not ok:
                return (("invalid", "Invalid file path"), "invalid file")
            return (("local", "Local File"), "file://")

        audio_ext = (".mp3", ".wav", ".m4a", ".flac", ".ogg", ".aac", ".opus", ".webm")
        video_ext = (".mp4", ".avi", ".mkv", ".mov", ".webm", ".m4v", ".wmv", ".flv")
        if any(url_lower.endswith(ext) for ext in audio_ext):
            return (("direct_audio", "Direct Audio"), "audio extension")
        if any(url_lower.endswith(ext) for ext in video_ext):
            return (("direct_video", "Direct Video"), "video extension")

        domain_map = {
            "youtube.com": ("youtube", "YouTube Video"),
            "youtu.be": ("youtube", "YouTube Video"),
            "twitch.tv": ("twitch", "Twitch"),
            "kick.com": ("kick", "Kick"),
            "rumble.com": ("rumble", "Rumble"),
            "dailymotion.com": ("dailymotion", "Dailymotion"),
            "vimeo.com": ("vimeo", "Vimeo"),
            "twitter.com": ("twitter", "Twitter/X"),
            "x.com": ("twitter", "Twitter/X"),
            "tiktok.com": ("tiktok", "TikTok"),
            "facebook.com": ("facebook", "Facebook"),
            "fb.watch": ("facebook", "Facebook"),
        }
        for domain, (plat, name) in domain_map.items():
            if domain in url_lower:
                reasons.append(domain)
                if plat == "youtube" and self._check_youtube_live_status(url):
                    return (("youtube_live", "YouTube Live"), "live pattern")
                return ((plat, name), ", ".join(reasons))

        if ".m3u8" in url_lower:
            return (("hls", "HLS Stream"), ".m3u8")
        if ".mpd" in url_lower:
            return (("dash", "DASH Stream"), ".mpd")

        if url_lower.startswith(self._HTTP_SCHEMES):
            return (("generic", "Website/Stream"), "http(s) fallback")

        return (("unknown", "Unknown Source"), "no pattern matched")

    def _is_direct_media_url(self, url: str) -> bool:
        url_lower = url.lower()
        audio_ext = (".mp3", ".wav", ".m4a", ".flac", ".ogg", ".aac", ".opus", ".webm")
        video_ext = (".mp4", ".avi", ".mkv", ".mov", ".webm", ".m4v", ".wmv", ".flv")
        return url_lower.endswith(audio_ext + video_ext)

    def _check_youtube_live_status(self, url: str) -> bool:
        cached = self._live_status_cache.get(url)
        if cached is not None:
            return cached
        url_lower = url.lower()
        is_live = any(indicator in url_lower for indicator in self._LIVE_INDICATORS)
        self._live_status_cache.put(url, is_live)
        return is_live

    def _extract_generic_audio(
        self, url: str, platform_id: str
    ) -> Tuple[Optional[str], str]:
        format_list = self._FORMAT_PRIORITIES.get(
            platform_id, self._FORMAT_PRIORITIES["generic"]
        )
        proxy_arg = self._proxy if self._proxy_enabled else ""

        audio_url = None  # <-- Initialisierung, um UnboundLocalError zu vermeiden
        method_used = ""

        for i, format_str in enumerate(format_list[:2]):
            if self._debug:
                logger.debug(f"  🔄 Versuche Format {i+1}: {format_str}")
            audio_url = YtDlpHelper.get_audio_url(
                url, format_str, timeout=15, proxy=proxy_arg
            )
            if audio_url:
                if self._debug:
                    logger.debug(f"  ✅ Erfolg mit Format {format_str}")
                method_used = f"generic_{format_str}"
                break

        if audio_url:
            return audio_url, method_used
        else:
            return None, ""

    def _extract_youtube_audio_optimized(
        self, url: str, platform_id: str
    ) -> Optional[str]:
        if self._debug:
            logger.debug(f"  🔍 Optimierte YouTube-Extraktion für: {url[:60]}...")

        video_id = self._extract_youtube_video_id(url)
        if not video_id or len(video_id) != 11:
            if self._debug:
                logger.debug("  ❌ Ungültige Video-ID")
            return None

        is_live = self._check_youtube_live_status(url)
        format_str = "bestaudio" if is_live else "bestaudio[ext=m4a]/bestaudio/best"

        if self.use_browser_cookies:
            result = self._try_browser_cookies(url, format_str)
            if result:
                return result

        result = self._try_standard_methods(url, format_str)
        if result:
            return result

        result, error = self._try_json_fallback(url)
        if result:
            return result
        elif error and self._debug:
            logger.debug(f"    ⚠️ JSON-Fallback Fehler: {error}")

        if self._debug:
            logger.debug("    🔄 Alle Methoden fehlgeschlagen")
        return None

    def _extract_youtube_video_id(self, url: str) -> Optional[str]:
        match = self._YOUTUBE_ID_REGEX.search(url)
        return match.group(1) if match else None

    def _try_browser_cookies(self, url: str, format_str: str = "bestaudio[ext=m4a]/bestaudio[ext=webm]/bestaudio/worstaudio") -> Optional[str]:
        """
        Versucht, die Audio-URL mit Cookies aus dem konfigurierten Browser zu extrahieren.
        Bevorzugt reine Audio-Formate (m4a, webm) und vermeidet Video-Streams.
        Bei Fehlschlag wird ein zweiter Versuch ohne Cookies gestartet.
        """
        proxy_arg = self._proxy if self._proxy_enabled else ""

        # Browser aus den Einstellungen lesen
        try:
            if hasattr(self, "settings") and self.settings is not None:
                browser = getattr(self.settings, "cookies_browser", "firefox")
            else:
                settings = AppSettings.load_from_file()
                browser = getattr(settings, "cookies_browser", "firefox")
        except Exception:
            browser = "firefox"

        if self._debug:
            logger.debug(f"    🧪 Versuche Cookies von {browser} (Format: {format_str})...")

        # Erster Versuch mit Cookies
        audio_url = YtDlpHelper.get_audio_url(
            url,
            format_str=format_str,
            timeout=20,
            use_cookies=True,
            browser=browser,
            proxy=proxy_arg,
        )

        if audio_url:
            # Prüfen, ob die URL auf einen Videostream hindeutet (itag=18,22,37 etc.)
            video_tags = ["itag=18", "itag=22", "itag=37"]
            if any(tag in audio_url for tag in video_tags):
                if self._debug:
                    logger.warning(f"    ⚠️ Extrahiert möglicherweise Video-URL: {audio_url[:100]}...")
                    logger.debug("    🔄 Versuche Fallback ohne Cookies...")
                # Zweiter Versuch ohne Cookies mit "worstaudio"
                audio_url2 = YtDlpHelper.get_audio_url(
                    url,
                    format_str="worstaudio",
                    timeout=20,
                    use_cookies=False,
                    proxy=proxy_arg,
                )
                if audio_url2 and not any(tag in audio_url2 for tag in video_tags):
                    if self._debug:
                        logger.debug(f"    ✅ Fallback zu worstaudio ohne Cookies: {audio_url2[:100]}...")
                    return audio_url2
                # Falls das auch nicht hilft, trotzdem die erste URL zurückgeben (besser als nichts)
            if self._debug:
                logger.debug(f"    ✅ Erfolg mit {browser}-Cookies")
            return audio_url

        # Zweiter Versuch ohne Cookies (falls erster komplett fehlschlug)
        if self._debug:
            logger.debug("    🔄 Cookies fehlgeschlagen, versuche ohne Cookies...")
        audio_url = YtDlpHelper.get_audio_url(
            url,
            format_str=format_str,
            timeout=20,
            use_cookies=False,
            proxy=proxy_arg,
        )
        if audio_url:
            if self._debug:
                logger.debug("    ✅ Erfolg ohne Cookies")
            return audio_url

        if self._debug:
            logger.debug("    ❌ Alle Versuche fehlgeschlagen")
        return None

    def _try_standard_methods(
        self, url: str, format_str: str = "bestaudio[ext=m4a]/bestaudio/best"
    ) -> Optional[str]:
        proxy_arg = self._proxy if self._proxy_enabled else ""
        methods = [
            {"name": "Standard yt-dlp", "format": format_str, "timeout": 20},
            {"name": "Lowest Quality", "format": "worstaudio", "timeout": 20},
        ]
        for method in methods:
            if self._debug:
                logger.debug(f"    🧪 Teste: {method['name']}")
            audio_url = YtDlpHelper.get_audio_url(
                url, method["format"], timeout=method["timeout"], proxy=proxy_arg
            )
            if audio_url:
                if self._debug:
                    logger.debug(f"    ✅ Erfolg mit {method['name']}")
                return audio_url
        return None

    def _try_json_fallback(self, url: str) -> Tuple[Optional[str], Optional[str]]:
        proxy_arg = self._proxy if self._proxy_enabled else ""
        try:
            if self._debug:
                logger.debug("    🔄 Versuche JSON-Fallback...")
            data = YtDlpHelper.get_json(url, timeout=25, proxy=proxy_arg)
            if not data:
                return None, "yt-dlp returned no data"

            best_audio = None
            best_score = 0
            for fmt in data.get("formats", []):
                if fmt.get("acodec") != "none" and fmt.get("url"):
                    score = fmt.get("abr", 0) or fmt.get("tbr", 0) or 0
                    if fmt.get("vcodec") == "none":
                        score += 1000
                    ext = fmt.get("ext", "").lower()
                    if ext in ["m4a", "mp4"]:
                        score += 500
                    elif ext in ["webm", "opus"]:
                        score += 300
                    if score > best_score:
                        best_score = score
                        best_audio = fmt["url"]
            if best_audio:
                if self._debug:
                    logger.debug("    ✅ JSON-Fallback erfolgreich")
                return best_audio, None
            else:
                return None, "No suitable audio format found in JSON"
        except Exception as e:
            return None, str(e)

    def _start_dvb_monitor(self) -> None:
        """
        Startet einen Hintergrundthread, der regelmäßig prüft, ob DVB‑Prozesse
        noch laufen, und sie ggf. bereinigt. Der Thread kann über das interne
        _dvb_monitor_stop‑Event sauber beendet werden.
        """
        if self._dvb_monitor_thread is not None:
            return

        # Stop‑Event für den Monitor‑Thread (wird bei dispose() gesetzt)
        self._dvb_monitor_stop = threading.Event()

        def monitor() -> None:
            """Überwachungsfunktion, läuft im eigenen Thread."""
            logger.debug("🛰️ DVBMonitor thread started")
            while not self._dvb_monitor_stop.is_set():
                try:
                    # Warte 30 Sekunden oder bis Stop gesetzt wird
                    if self._dvb_monitor_stop.wait(30):
                        break

                    # Prüfe alle DVB‑Prozesse
                    with self._dvb_lock:
                        for proc in self._dvb_processes[:]:
                            if proc.poll() is not None:
                                logger.warning(
                                    "⚠️ VLC-DVB-Prozess beendet – versuche Neustart?"
                                )
                                self._dvb_processes.remove(proc)
                except Exception as e:
                    logger.error(f"Fehler im DVB-Monitor-Thread: {e}", exc_info=True)

            logger.debug("✅ DVBMonitor thread terminated")

        # Thread-Objekt erstellen und SOFORT zuweisen, bevor gestartet wird
        self._dvb_monitor_thread = threading.Thread(
            target=monitor,
            daemon=False,  # Nicht‑Daemon, damit wir kontrolliert beenden können
            name="DVBMonitor",
        )
        self._dvb_monitor_thread.start()

    def _start_dvb_stream(self, dvb_url: str) -> Optional[str]:
        """
        Startet einen VLC‑Prozess für DVB‑S‑Streaming.
        Args:
            dvb_url: DVB‑URL im Format dvb-s://frequency=...&symbolrate=...&polarization=...
        Returns:
            Die HTTP‑URL des VLC‑Streams oder None bei Fehler.
        """
        if not shutil.which("vlc"):
            logger.error(
                "❌ VLC nicht gefunden – für DVB wird VLC benötigt.",
                extra={"component": "stream"},
            )
            return None

        if not dvb_url.startswith("dvb-s://"):
            logger.error(
                "❌ Bitte vollständige Parameter-URL angeben, z.B. dvb-s://frequency=...",
                extra={"component": "stream"},
            )
            return None

        query_string = dvb_url[8:]
        allowed_params = {
            "frequency",
            "symbolrate",
            "polarization",
            "fec",
            "satno",
            "dvb_scan",
            "program",
            "video_pid",
            "audio_pid",
        }
        params = {}

        for pair in query_string.split("&"):
            if not pair:
                continue
            if "=" not in pair:
                logger.error(
                    f"❌ Ungültiger Parameter (kein '='): {pair}",
                    extra={"component": "stream"},
                )
                return None
            key, value = pair.split("=", 1)

            if not re.match(r"^[a-zA-Z0-9_]+$", key):
                logger.error(
                    f"❌ Ungültiger Parametername: {key}", extra={"component": "stream"}
                )
                return None

            if not re.match(r"^[a-zA-Z0-9._-]+$", value):
                logger.error(
                    f"❌ Ungültiger Wert: {value} (erlaubt: a-z, A-Z, 0-9, . _ -)",
                    extra={"component": "stream"},
                )
                return None

            if key not in allowed_params:
                logger.error(
                    f"❌ Nicht erlaubter Parameter: {key}",
                    extra={"component": "stream"},
                )
                return None

            params[key] = value

        if "frequency" not in params:
            logger.error(
                "❌ 'frequency' ist ein Pflichtparameter für DVB-S.",
                extra={"component": "stream"},
            )
            return None

        # Lokalen Port finden
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.bind(("localhost", 0))
        port = sock.getsockname()[1]
        sock.close()
        mount = "/dvb"
        http_url = f"http://localhost:{port}{mount}"

        dvb_options = [
            f"{key}={params[key]}" for key in allowed_params if key in params
        ]
        dvb_input = "dvb-s://" + "&".join(dvb_options)

        vlc_cmd = [
            "vlc",
            dvb_input,
            "--dvb-adapter=0",
            "--sout",
            f"#standard{{access=http,mux=ts,dst=0.0.0.0:{port}{mount}}}",
            "--intf",
            "dummy",
            "--no-audio",
            "--no-video",
            "--live-caching",
            "300",
        ]

        if logger.isEnabledFor(logging.DEBUG):
            logger.debug(
                f"🚀 Starte VLC: {' '.join(vlc_cmd)}", extra={"component": "stream"}
            )

        process = None
        try:
            process = subprocess.Popen(
                vlc_cmd,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                stdin=subprocess.DEVNULL,
                start_new_session=True,
            )

            time.sleep(2)
            if process.poll() is not None:
                logger.error(
                    "❌ VLC-Prozess für DVB ist sofort beendet.",
                    extra={"component": "stream"},
                )
                # Prozess terminieren (obwohl bereits tot, sicherheitshalber)
                self._terminate_dvb_process(process)
                return None

            # Optionaler Stream‑Test, nur wenn requests verfügbar
            if requests is not None:
                try:
                    r = requests.get(http_url, timeout=3)
                    if r.status_code != 200:
                        logger.warning(
                            f"⚠️ DVB-Stream antwortet mit Status {r.status_code}, aber VLC läuft.",
                            extra={"component": "stream"},
                        )
                except Exception as e:
                    logger.warning(
                        f"⚠️ DVB-Stream-Test fehlgeschlagen: {e}",
                        extra={"component": "stream"},
                    )
                    # Stream-Test fehlgeschlagen → VLC trotzdem weiterlaufen lassen? Entscheidung: wir geben trotzdem URL zurück,
                    # da VLC läuft und der Stream später möglicherweise funktioniert. Aber um Ressourcenlecks zu vermeiden,
                    # werden wir den Prozess trotzdem registrieren, damit er später bereinigt werden kann.
            else:
                logger.warning(
                    "⚠️ requests nicht installiert – DVB‑Stream‑Test übersprungen."
                )

            # Prozess in die Liste aufnehmen (nach erfolgreicher Prüfung)
            with self._dvb_lock:
                self._dvb_processes.append(process)

            logger.info(
                f"✅ VLC-DVB-Server gestartet: {http_url}",
                extra={"component": "stream"},
            )
            return http_url

        except Exception as e:
            logger.error(
                f"❌ Fehler beim Starten von VLC für DVB: {e}",
                exc_info=True,
                extra={"component": "stream"},
            )
            if process is not None:
                self._terminate_dvb_process(process)
            return None

    def _terminate_dvb_process(self, process: subprocess.Popen) -> None:
        """Hilfsmethode zum Beenden eines VLC-Prozesses und Entfernen aus der Liste."""
        try:
            if process.poll() is None:
                process.terminate()
                try:
                    process.wait(timeout=2.0)
                except subprocess.TimeoutExpired:
                    process.kill()
                    process.wait(timeout=1.0)
        except Exception as e:
            logger.debug(f"Fehler beim Beenden des DVB-Prozesses: {e}")
        finally:
            # Aus der Liste entfernen, falls vorhanden
            with self._dvb_lock:
                if process in self._dvb_processes:
                    self._dvb_processes.remove(process)


class YtDlpHelper:
    """
    Hilfsklasse für yt-dlp-Aufrufe.
    Bietet Methoden zum Abrufen von JSON-Metadaten und direkten Audio-URLs.
    Die Ausführung erfolgt immer ohne Shell (sicher gegen Injection).
    """

    _ALLOWED_BROWSERS = {
        "firefox",
        "chrome",
        "brave",
        "edge",
        "chromium",
        "opera",
        "vivaldi",
        "safari",
    }

    _ALLOWED_PROXY_SCHEMES = ("http://", "https://", "socks4://", "socks5://")

    _ALLOWED_FORMAT_CHARS = set(
        "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_/[]=+-"
    )

    # RFC 3986 erlaubte Zeichen für URLs (zusätzliche Sicherheit)
    _ALLOWED_PROXY_CHARS = re.compile(r"^[a-zA-Z0-9\-._~:/?#\[\]@!$&\'()*+,;=]*$")

    @classmethod
    def _validate_browser(cls, browser: str) -> bool:
        """Prüft, ob der angegebene Browser-Name unterstützt wird."""
        return browser in cls._ALLOWED_BROWSERS

    @classmethod
    def _validate_proxy(cls, proxy: str) -> bool:
        """
        Validiert eine Proxy-URL auf gültiges Schema, netloc und erlaubte Zeichen.
        """
        if not proxy:
            return False

        # Verbot von Steuerzeichen
        if re.search(r"[\x00-\x1f\x7f]", proxy):
            return False

        try:
            parsed = urllib.parse.urlparse(proxy)
            if parsed.scheme not in cls._ALLOWED_PROXY_SCHEMES:
                return False
            if not parsed.netloc:
                return False
            # Whitelist für erlaubte Zeichen im gesamten Proxy-String
            if not re.fullmatch(r"^[a-zA-Z0-9\-._~:/?#\[\]@!$&\'()*+,;=]*$", proxy):
                return False
            return True
        except Exception:
            return False

    @classmethod
    def _validate_format_str(cls, format_str: str) -> bool:
        """Prüft, ob der Format-String nur erlaubte Zeichen enthält."""
        return all(c in cls._ALLOWED_FORMAT_CHARS for c in format_str)

    @staticmethod
    def run_command(
        cmd: List[str],
        timeout: int = 15,
        method_name: str = "unknown",
        prefer_ipv4: bool = False,
    ) -> Optional[str]:
        """
        Führt einen externen Befehl aus (ohne Shell) und gibt die stdout-Ausgabe zurück.
        Bei Timeout oder Fehler wird None zurückgegeben.
        """
        if logger.isEnabledFor(logging.DEBUG):
            logger.debug(f"  Ausführen: {' '.join(cmd)}", extra={"component": "ytdlp"})

        start = time.perf_counter()
        proc = None

        # Stelle sicher, dass "--" als Trennzeichen vor der URL gesetzt ist
        if "--" not in cmd:
            if cmd and not cmd[-1].startswith("-") and cmd[-1] != "--":
                url = cmd.pop()
                cmd.append("--")
                cmd.append(url)

        if prefer_ipv4 and "-4" not in cmd:
            try:
                dash_index = cmd.index("--")
                cmd.insert(dash_index, "-4")
            except ValueError:
                cmd.insert(-1, "-4")

        if cmd:
            url = cmd[-1]
            if url == "--" and len(cmd) >= 2:
                url = cmd[-2]
            if not url or any(ord(c) < 32 for c in url):
                logger.error(
                    "Ungültige URL enthält Steuerzeichen", extra={"component": "ytdlp"}
                )
                return None

        try:
            proc = subprocess.Popen(
                cmd,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                encoding="utf-8",
                errors="replace",
                shell=False,
            )
            stdout, stderr = proc.communicate(timeout=timeout)
            duration = (time.perf_counter() - start) * 1000
            if proc.returncode == 0 and stdout.strip():
                if logger.isEnabledFor(logging.DEBUG):
                    logger.debug(
                        f"  ✅ {method_name} erfolgreich in {duration:.2f}ms",
                        extra={"component": "ytdlp"},
                    )
                return stdout.strip()
            else:
                if logger.isEnabledFor(logging.DEBUG):
                    if DEBUG_LEVEL >= 3:
                        stderr_preview = stderr.replace("\n", " ")
                    else:
                        stderr_preview = stderr[:200].replace("\n", " ")
                    logger.debug(
                        f"  ⚠️ {method_name} fehlgeschlagen (Code {proc.returncode}): {stderr_preview}",
                        extra={"component": "ytdlp"},
                    )
                return None
        except subprocess.TimeoutExpired:
            if proc:
                try:
                    proc.kill()
                    proc.communicate(timeout=1)
                except subprocess.TimeoutExpired:
                    pass
            if logger.isEnabledFor(logging.DEBUG):
                logger.debug(
                    f"  ⏰ {method_name} Timeout nach {timeout}s – Prozess wurde gekillt",
                    extra={"component": "ytdlp"},
                )
            return None
        except (OSError, ValueError) as e:
            if logger.isEnabledFor(logging.DEBUG):
                logger.debug(
                    f"  ⚠️ {method_name} Fehler: {e}", extra={"component": "ytdlp"}
                )
            return None
        except Exception as e:
            logger.error(
                f"Unerwarteter Fehler in {method_name}: {e}",
                exc_info=True,
                extra={"component": "ytdlp"},
            )
            return None
        finally:
            if proc and proc.poll() is None:
                try:
                    proc.kill()
                    proc.wait(timeout=1)
                except Exception:
                    pass

    @classmethod
    def get_json(
        cls,
        url: str,
        timeout: int = 20,
        use_cookies: bool = False,
        browser: Optional[str] = None,
        proxy: str = "",
        prefer_ipv4: bool = False,
    ) -> Optional[Dict[str, Any]]:
        """
        Ruft die JSON-Metadaten eines Videos/Streams ab.
        """
        if use_cookies and browser:
            if not cls._validate_browser(browser):
                logger.warning(
                    f"Ungültiger Browser-Name: {browser}, Cookies werden ignoriert",
                    extra={"component": "ytdlp"},
                )
                use_cookies = False

        if proxy and not cls._validate_proxy(proxy):
            logger.warning(
                f"Ungültige Proxy-URL: {proxy}, Proxy wird ignoriert",
                extra={"component": "ytdlp"},
            )
            proxy = ""

        cmd = [
            "yt-dlp",
            "--dump-json",
            "--no-warnings",
            "--no-check-certificate",
            "--socket-timeout",
            str(timeout),
        ]
        if proxy:
            cmd.extend(["--proxy", proxy])
        if use_cookies and browser:
            cmd.extend(["--cookies-from-browser", browser])
        cmd.append(url)

        stdout = cls.run_command(
            cmd, timeout=timeout, method_name="get_json", prefer_ipv4=prefer_ipv4
        )
        if stdout:
            try:
                return json.loads(stdout)
            except json.JSONDecodeError:
                if logger.isEnabledFor(logging.DEBUG):
                    logger.debug(
                        "  ⚠️ get_json: JSON-Decode-Fehler",
                        extra={"component": "ytdlp"},
                    )
        return None

    @classmethod
    def get_audio_url(
        cls,
        url: str,
        format_str: str = "bestaudio/best",
        timeout: int = 15,
        use_cookies: bool = False,
        browser: Optional[str] = None,
        proxy: str = "",
        prefer_ipv4: bool = False,
    ) -> Optional[str]:
        """
        Extrahiert die direkte Audio-URL aus einem Video/Stream.
        Gibt die URL zurück oder None bei Fehlschlag.
        """
        if not cls._validate_format_str(format_str):
            logger.warning(
                f"Ungültiger Format-String: {format_str}, verwende Standard",
                extra={"component": "ytdlp"},
            )
            format_str = "bestaudio/best"

        if use_cookies and browser:
            if not cls._validate_browser(browser):
                logger.warning(
                    f"Ungültiger Browser-Name: {browser}, Cookies werden ignoriert",
                    extra={"component": "ytdlp"},
                )
                use_cookies = False

        if proxy and not cls._validate_proxy(proxy):
            logger.warning(
                f"Ungültige Proxy-URL: {proxy}, Proxy wird ignoriert",
                extra={"component": "ytdlp"},
            )
            proxy = ""

        cmd = [
            "yt-dlp",
            "-g",
            "-f",
            format_str,
            "--no-warnings",
            "--no-check-certificate",
            "--socket-timeout",
            str(timeout),
        ]
        if proxy:
            cmd.extend(["--proxy", proxy])
        if use_cookies and browser:
            cmd.extend(["--cookies-from-browser", browser])
        cmd.append(url)

        stdout = cls.run_command(
            cmd,
            timeout=timeout,
            method_name=f"get_audio_url_{format_str}",
            prefer_ipv4=prefer_ipv4,
        )
        if stdout:
            for line in stdout.splitlines():
                line = line.strip()
                if line.startswith(("http://", "https://")):
                    return line
        return None


# -----------------------------------------------------------------------------
# Konstanten (sollten idealerweise aus ConfigDefaults importiert werden)
# -----------------------------------------------------------------------------
class FFmpegManagerDefaults:
    """Standardwerte für den FFmpegManager (falls nicht in ConfigDefaults vorhanden)."""

    # Prozess‑Management
    DEFAULT_WAIT_AFTER_TERMINATE: float = 1.0
    DEFAULT_WAIT_AFTER_KILL: float = 0.5
    DEFAULT_MAX_IDLE_SECONDS: float = 30.0
    DEFAULT_PROCESS_TIMEOUT: float = 5.0
    DEFAULT_MAX_PROCESSES: int = 4

    # Zeit‑Einstellungen
    FIRST_DATA_TIMEOUT: float = 20.0
    HLS_INITIAL_WAIT: float = 1.5
    CLEANUP_INTERVAL: int = 60
    INITIAL_PROCESS_CHECK_DELAY: float = 1.0

    # Anzahl Wiederholungen bei URL‑Refresh
    MAX_REFRESH_ATTEMPTS: int = 3
    REFRESH_RETRY_DELAY_BASE: float = 2.0
    REFRESH_RETRY_DELAY_MAX: float = 10.0

    # Stderr‑Aggregation
    STALLED_RECONNECT_LOG_INTERVAL: float = 10.0

    # Prozess‑Terminierung (psutil & Fallback)
    PSUTIL_CHILD_TERMINATE_TIMEOUT: float = 2.5
    PSUTIL_CHILD_KILL_WAIT: float = 1.0
    PSUTIL_PARENT_TERMINATE_TIMEOUT: float = 6.0
    PSUTIL_PARENT_KILL_WAIT: float = 2.5
    SUBPROC_TERMINATE_TIMEOUT: float = 5.0
    SUBPROC_KILL_WAIT: float = 2.0


class FFmpegManager:
    """
    Verwaltung von FFmpeg‑Prozessen für Audio‑Streaming.

    Für problematische Livestreams (YouTube, Twitch, Kick, etc.) wird zwingend
    der Pipe‑Zweig (yt‑dlp + FFmpeg) verwendet, da nur yt‑dlp die korrekten
    Cookies und Header setzen kann.
    Thread‑sicher durch Locks und Semaphore.
    """

    # --- Timeout-Konstanten aus FFmpegManagerDefaults ---
    PSUTIL_CHILD_TERMINATE_TIMEOUT = (
        FFmpegManagerDefaults.PSUTIL_CHILD_TERMINATE_TIMEOUT
    )
    PSUTIL_CHILD_KILL_WAIT = FFmpegManagerDefaults.PSUTIL_CHILD_KILL_WAIT
    PSUTIL_PARENT_TERMINATE_TIMEOUT = (
        FFmpegManagerDefaults.PSUTIL_PARENT_TERMINATE_TIMEOUT
    )
    PSUTIL_PARENT_KILL_WAIT = FFmpegManagerDefaults.PSUTIL_PARENT_KILL_WAIT
    SUBPROC_TERMINATE_TIMEOUT = FFmpegManagerDefaults.SUBPROC_TERMINATE_TIMEOUT
    SUBPROC_KILL_WAIT = FFmpegManagerDefaults.SUBPROC_KILL_WAIT

    # -------------------------------------------------------------------------
    #  Klassenvariablen (Konstanten)
    # -------------------------------------------------------------------------
    WAIT_AFTER_TERMINATE: float = 1.0
    WAIT_AFTER_KILL: float = 0.5
    MAX_IDLE_SECONDS: float = 30.0
    PROCESS_TIMEOUT: float = 5.0
    MAX_PROCESSES: int = 4

    FIRST_DATA_TIMEOUT: float = 20.0
    HLS_INITIAL_WAIT: float = 1.5
    CLEANUP_INTERVAL: int = 60
    INITIAL_PROCESS_CHECK_DELAY: float = 1.0

    MAX_REFRESH_ATTEMPTS: int = 3
    REFRESH_RETRY_DELAY_BASE: float = 2.0
    REFRESH_RETRY_DELAY_MAX: float = 10.0

    STALLED_RECONNECT_LOG_INTERVAL: float = 10.0

    # Plattformen, bei denen der Pipe‑Zweig bevorzugt wird
    PIPE_PREFERRED_PLATFORMS = {
        "youtube",
        "twitch",
        "kick",
        "rumble",
        "tiktok",
        "facebook",
    }

    # --- Cache für YouTube-Headers (Optimierung) ---
    _YOUTUBE_HEADERS_STRING: Optional[str] = None

    # --- Blockgröße für Lesethread (wird dynamisch angepasst) ---
    READ_BLOCK_SIZE: int = 8192

    # -------------------------------------------------------------------------
    #  Interne Hilfsklassen
    # -------------------------------------------------------------------------
    class _LRUCache:
        """Einfacher LRU-Cache mit maximaler Größe."""

        def __init__(self, maxsize: int = 100):
            self.maxsize = maxsize
            self._cache = OrderedDict()
            self._lock = threading.RLock()

        def get(self, key: str) -> Optional[Any]:
            with self._lock:
                if key in self._cache:
                    self._cache.move_to_end(key)
                    return self._cache[key]
                return None

        def put(self, key: str, value: Any) -> None:
            with self._lock:
                if key in self._cache:
                    self._cache.move_to_end(key)
                self._cache[key] = value
                if len(self._cache) > self.maxsize:
                    self._cache.popitem(last=False)

        def clear(self) -> None:
            with self._lock:
                self._cache.clear()

    class _RateLimiter:
        """Begrenzt die Anzahl von Log-Meldungen pro Zeitraum."""

        def __init__(self, max_messages: int = 10, period: float = 60.0):
            self.max = max_messages
            self.period = period
            self._timestamps: List[float] = []
            self._lock = threading.RLock()

        def allow(self) -> bool:
            with self._lock:
                now = time.time()
                self._timestamps = [
                    t for t in self._timestamps if now - t < self.period
                ]
                if len(self._timestamps) < self.max:
                    self._timestamps.append(now)
                    return True
                return False

    class _ProcessInfo:
        __slots__ = (
            "process_id",
            "process",
            "yt_process",
            "output_queue",
            "start_time",
            "url",
            "stopping",
            "bytes_read",
            "platform",
            "is_live",
            "chunks_processed",
            "last_activity",
            "headers_used",
            "stats",
            "stderr_thread",
            "stop_stderr",
            "refresh_attempts",
            "current_read_future",
            "pipe_mode",
            "creation_time",
            "last_error",
            "error_count",
            "last_stderr_line",
            "_skip_semaphore_release",
            "yt_stderr_thread",
            "yt_stderr_stop",
            "_removing",
            "read_queue",
            "read_thread",
            "read_stop",
            "read_buffer",
        )

        def __init__(
            self,
            process_id: str,
            process: subprocess.Popen,
            output_queue: Optional[queue.Queue],
            url: str,
            platform: str,
            is_live: bool,
            headers_used: bool,
            yt_process: Optional[subprocess.Popen] = None,
            pipe_mode: bool = False,
        ) -> None:
            self.process_id: str = process_id
            self.process: subprocess.Popen = process
            self.yt_process: Optional[subprocess.Popen] = yt_process
            self.output_queue: Optional[queue.Queue] = output_queue
            self.start_time: float = time.time()
            self.creation_time: float = time.time()
            self.url: str = url
            self.stopping: bool = False
            self.bytes_read: int = 0
            self.platform: str = platform
            self.is_live: bool = is_live
            self.chunks_processed: int = 0
            self.last_activity: float = time.time()
            self.headers_used: bool = headers_used
            self.pipe_mode: bool = pipe_mode
            self.stats: Dict[str, Any] = {
                "total_reads": 0,
                "total_read_bytes": 0,
                "read_errors": 0,
                "last_read_duration_ms": 0.0,
                "last_read_time": 0.0,
                "pipe_errors": 0,
                "timeouts": 0,
                "reconnects": 0,
                "yt_process_died": False,
            }
            self.stderr_thread: Optional[threading.Thread] = None
            self.stop_stderr: threading.Event = threading.Event()
            self.refresh_attempts: int = 0
            self.current_read_future: Optional[Future] = None
            self.last_error: Optional[str] = None
            self.error_count: int = 0
            self.last_stderr_line: str = ""
            self._skip_semaphore_release: bool = False
            self.yt_stderr_thread: Optional[threading.Thread] = None
            self.yt_stderr_stop: Optional[threading.Event] = None
            self._removing = False
            self.read_queue: Optional[queue.Queue] = None
            self.read_thread: Optional[threading.Thread] = None
            self.read_stop: Optional[threading.Event] = None
            self.read_buffer: bytes = b""

    # -------------------------------------------------------------------------
    #  Konstruktor
    # -------------------------------------------------------------------------
    def __init__(
        self,
        config: Optional[Any] = None,
        stream_manager: Optional[Any] = None,
        settings: Optional[Any] = None,
        resource_manager: Optional[Any] = None,
        max_processes: int = MAX_PROCESSES,
        process_timeout: float = PROCESS_TIMEOUT,
        max_idle_seconds: float = MAX_IDLE_SECONDS,
        on_process_crash: Optional[Callable[[str, str], None]] = None,
    ) -> None:
        """
        Initialisiert den FFmpegManager.
        """
        self._processes: Dict[str, FFmpegManager._ProcessInfo] = {}
        self._lock = threading.RLock()
        self._shutting_down = False
        self._global_shutdown = False

        self.config = config if config is not None else Config()
        self.settings = settings if settings is not None else AdvancedSettings()

        self.stream_manager = stream_manager
        self.resource_manager = resource_manager
        self._on_process_crash = on_process_crash

        # Semaphore mit eigener Zählvariable
        self._process_semaphore = threading.Semaphore(max_processes)
        self._process_semaphore_max = max_processes
        self._active_slots = 0
        # self._slot_lock = threading.RLock()

        # Statistik
        self._stats = {
            "extraction_attempts": 0,
            "successful_extractions": 0,
            "failed_extractions": 0,
            "cache_hits": 0,
            "start_time": time.time(),
            "total_processes_started": 0,
            "total_pipe_processes": 0,
            "process_terminations_graceful": 0,
            "process_terminations_kill": 0,
            "process_terminations_psutil": 0,
            "process_terminations_failed": 0,
            "reconnect_attempts": 0,
            "reconnect_success": 0,
            "reconnect_failures": 0,
        }
        self._stats_lock = threading.RLock()

        # Cache für Live‑Erkennung (LRU)
        self._live_detection_cache = self._LRUCache(maxsize=100)
        self._pid_tracking: Dict[int, Dict[str, Any]] = {}

        # Periodische Bereinigung (mit kontrollierbarem Stop-Event)
        self._cleanup_stop_event = threading.Event()
        self._cleanup_thread = threading.Thread(
            target=self._cleanup_worker,
            daemon=True,  # Daemon, damit Shutdown nicht blockiert
            name="FFmpegManagerCleanup",
        )
        self._cleanup_thread.start()
        log_debug("ffmpeg", "Cleanup thread started (daemon)")

        # psutil initialisieren
        self._psutil = None
        try:
            import psutil

            self._psutil = psutil
        except ImportError:
            log_debug("ffmpeg", "psutil not available, using fallback termination")

        # Gleitender Durchschnitt der Lesezeiten (für dynamischen Timeout)
        self._read_times: Deque[float] = deque(maxlen=10)

        # atexit‑Handler für Notfall‑Cleanup
        self._disposed = False
        atexit.register(self._atexit_cleanup)

        # Dynamische Blockgröße basierend auf der Datenrate
        self._update_block_size()

        logger.info(
            f"✅ FFmpegManager initialized (Platform: {SYSTEM}, "
            f"max_processes={max_processes}, process_timeout={process_timeout}s)"
        )

    def _update_block_size(self) -> None:
        """Passt die Leseblockgröße an die erwartete Datenrate an."""
        # Ziel: ca. 0.1 Sekunden Audio pro Block
        if self.config and self.config.BYTES_PER_SECOND:
            self.READ_BLOCK_SIZE = max(4096, int(self.config.BYTES_PER_SECOND * 0.1))
            self.READ_BLOCK_SIZE = min(self.READ_BLOCK_SIZE, 32768)
        else:
            self.READ_BLOCK_SIZE = 8192

    def _atexit_cleanup(self) -> None:
        """Notfall‑Cleanup, falls dispose nicht aufgerufen wurde."""
        if not self._disposed:
            logger.info("⚠️ FFmpegManager: atexit‑Cleanup wird ausgeführt")
            self.dispose()
            self._disposed = True

    # -------------------------------------------------------------------------
    #  Öffentliche Methoden
    # -------------------------------------------------------------------------
    def start_stream(
        self,
        video_url: str,
        output_queue: Optional[queue.Queue],
        process_id: str,
        force_refresh_audio_url: bool = False,
        audio_url: Optional[str] = None,
        seek_seconds: Optional[float] = None,
        detected_language: Optional[str] = None,
    ) -> Optional[subprocess.Popen]:
        """
        Startet einen Audio‑Stream mit korrekter Slot‑Lebensdauer.

        Der Slot wird reserviert, bevor der Stream startet, und erst in _remove_process()
        freigegeben, wenn der Prozess erfolgreich registriert wurde. Bei Fehlschlag wird
        der Slot sofort wieder freigegeben.

        Args:
            video_url: Die ursprüngliche Video‑URL.
            output_queue: Queue für Audiodaten (wird derzeit nicht verwendet).
            process_id: Eindeutige ID für den Stream.
            force_refresh_audio_url: Erzwingt das Neuabrufen der Audio‑URL.
            audio_url: Bereits aufgelöste Audio‑URL (optional).
            seek_seconds: Startposition für lokale Dateien.
            detected_language: Erkannte Sprache für Audio‑Filter.

        Returns:
            subprocess.Popen des gestarteten FFmpeg‑Prozesses oder None bei Fehler.
        """
        # Sicherheitshalber Kürzung der URL für Logs
        url_display = video_url[:80] + "..." if video_url and len(video_url) > 80 else video_url
        log_debug(
            "ffmpeg",
            f"start_stream called: video_url={url_display}, process_id={process_id}"
        )
        logger.info(f"\n🎬 FFmpegManager: Starting stream for: {url_display}...")

        # ========== 1. Zustandsprüfungen (bevor Slot reserviert wird) ==========
        with self._lock:
            if self._shutting_down:
                logger.warning("FFmpegManager is shutting down – cannot start new stream")
                return None
            if self.is_active(process_id):
                logger.warning(f"⚠️ Stream {process_id} already active")
                return None

        # ========== 2. Slot reservieren ==========
        if not self._acquire_slot(purpose=f"start_stream:{process_id}"):
            msg = f"❌ Kein freier Slot für {process_id} – maximale Prozessanzahl erreicht"
            logger.warning(msg)
            log_debug("ffmpeg", f"start_stream: {msg}")
            return None

        slot_acquired = True  # Merker, dass der Slot reserviert ist

        try:
            # ========== 3. Internen Start versuchen ==========
            process = self._start_stream_internal(
                video_url,
                output_queue,
                process_id,
                force_refresh_audio_url,
                audio_url,
                seek_seconds,
                detected_language,
            )

            if process is not None:
                # Erfolg: Slot bleibt reserviert (wird später in _remove_process freigegeben)
                slot_acquired = False
                log_debug(
                    "ffmpeg",
                    f"start_stream: Prozess PID {process.pid} erfolgreich gestartet, Slot bleibt belegt",
                )
                return process
            else:
                # Start fehlgeschlagen: Slot sofort freigeben
                log_debug(
                    "ffmpeg",
                    "start_stream: _start_stream_internal gab None zurück – Slot wird freigegeben",
                )
                return None

        except Exception as e:
            logger.error(f"❌ Unerwarteter Fehler in start_stream: {e}", exc_info=True)
            log_debug("ffmpeg", f"start_stream: Exception {type(e).__name__}: {e}")
            return None

        finally:
            if slot_acquired:
                self._release_slot(purpose=f"start_stream_failed:{process_id}")
                log_debug(
                    "ffmpeg",
                    "start_stream: Slot freigegeben (Start fehlgeschlagen oder Exception)",
                )

    def _start_stream_internal(
        self,
        video_url: str,
        output_queue: Optional[queue.Queue],
        process_id: str,
        force_refresh_audio_url: bool,
        audio_url: Optional[str],
        seek_seconds: Optional[float],
        detected_language: Optional[str],
    ) -> Optional[subprocess.Popen]:
        """
        Interne Implementierung des Stream-Starts.
        WICHTIG: Der Slot wurde bereits von start_stream() reserviert.
        Diese Methode darf weder einen Slot reservieren noch freigeben.
        """
        registered = False
        process = None
        yt_process = None
        pipe_mode = False
        yt_stderr_thread = None
        yt_stderr_stop = None
        start_time = time.time()

        if DEBUG_LEVEL >= 3:
            log_debug(
                "ffmpeg",
                f"_start_stream_internal called for {process_id} at {start_time:.3f}",
            )

        try:
            # ========== 1. URL-Validierung ==========
            valid, msg = self._validate_url(video_url)
            if not valid:
                logger.error(f"❌ Ungültige Video-URL: {msg}")
                if DEBUG_LEVEL >= 3:
                    log_debug("ffmpeg", f"URL validation failed: {video_url} -> {msg}")
                return None
            if DEBUG_LEVEL >= 3:
                log_debug("ffmpeg", f"URL validation OK: {video_url[:100]}")

            # ========== 2. Live-Erkennung und Plattform ==========
            is_live, platform = self._detect_stream_type(video_url)
            is_youtube = (
                "youtube.com" in video_url.lower() or "youtu.be" in video_url.lower()
            )
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "ffmpeg",
                    f"detect_stream_type result: is_live={is_live}, platform={platform}, is_youtube={is_youtube}",
                )

            if is_youtube and not is_live:
                if DEBUG_LEVEL >= 3:
                    log_debug("ffmpeg", "Checking YouTube live status via metadata...")
                is_live = self._check_youtube_live_by_metadata(video_url)
                if is_live:
                    logger.info("  🎥 YouTube‑Livestream erkannt (via Metadata)")
                elif DEBUG_LEVEL >= 3:
                    log_debug(
                        "ffmpeg", f"Metadata check: {video_url[:50]} is_live=False"
                    )

            # Entscheidung: Pipe-Zweig für alle YouTube-Videos
            if is_youtube:
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "ffmpeg",
                        "YouTube-Video erkannt – verwende Pipe-Zweig für Stabilität",
                    )
                use_pipe = True
            else:
                use_pipe = is_live and platform.lower() in self.PIPE_PREFERRED_PLATFORMS
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "ffmpeg",
                        f"Non-YouTube: use_pipe={use_pipe} (is_live={is_live}, platform={platform})",
                    )

            if DEBUG_LEVEL >= 3:
                log_debug(
                    "ffmpeg",
                    f"use_pipe={use_pipe}, is_live={is_live}, platform={platform}",
                )

            # =================================================================
            # 1. PIPE-ZWEIG (für YouTube und Live)
            # =================================================================
            if use_pipe:
                logger.info(
                    f"  🎥 {platform}‑{'Livestream' if is_live else 'Video'}: Verwende yt‑dlp als Datenquelle (Pipe‑Zweig)"
                )
                if DEBUG_LEVEL >= 3:
                    log_debug("ffmpeg", "Starting pipe mode...")
                pipe_mode = True
                formats_to_try = [None, "webm", "matroska"]
                yt_process = None
                process = None
                pipe_success = False

                for fmt_idx, fmt in enumerate(formats_to_try):
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "ffmpeg",
                            f"Pipe format attempt {fmt_idx+1}/{len(formats_to_try)}: {fmt if fmt else 'auto'}",
                        )
                    format_start = time.time()

                    # Vorherigen yt-dlp stderr‑Thread beenden
                    if yt_stderr_thread and yt_stderr_thread.is_alive():
                        if DEBUG_LEVEL >= 3:
                            log_debug(
                                "ffmpeg",
                                f"Beende vorherigen yt-dlp stderr thread für {process_id} (Format {fmt_idx})",
                            )
                        yt_stderr_stop.set()
                        try:
                            if (
                                yt_process
                                and yt_process.stderr
                                and not yt_process.stderr.closed
                            ):
                                yt_process.stderr.close()
                                if DEBUG_LEVEL >= 3:
                                    log_debug(
                                        "ffmpeg", "  ↪ yt-dlp stderr-Pipe geschlossen"
                                    )
                        except Exception as e:
                            if DEBUG_LEVEL >= 3:
                                log_debug(
                                    "ffmpeg",
                                    f"  ⚠️ Fehler beim Schließen der yt-dlp stderr-Pipe: {e}",
                                )
                        yt_stderr_thread.join(timeout=1.0)
                        if yt_stderr_thread.is_alive():
                            logger.warning(
                                f"  ⚠️ yt-dlp stderr thread für {process_id} beendet sich nicht – setze als Daemon"
                            )
                        elif DEBUG_LEVEL >= 3:
                            log_debug(
                                "ffmpeg", "  ↪ yt-dlp stderr thread erfolgreich beendet"
                            )
                        yt_stderr_thread = None
                        yt_stderr_stop = None

                    # Alte yt-dlp/FFmpeg-Prozesse terminieren
                    if yt_process is not None:
                        if DEBUG_LEVEL >= 3:
                            log_debug(
                                "ffmpeg",
                                f"Terminating previous yt-dlp process (PID {yt_process.pid})",
                            )
                        self._terminate_process(yt_process)
                    if process is not None:
                        if DEBUG_LEVEL >= 3:
                            log_debug(
                                "ffmpeg",
                                f"Terminating previous FFmpeg process (PID {process.pid})",
                            )
                        self._terminate_process(process)

                    # yt-dlp Befehl aufbauen
                    yt_cmd = [
                        "yt-dlp",
                        "-f",
                        "bestaudio[ext=m4a]/bestaudio/best",
                        "--no-playlist",
                        "--verbose",
                        "--socket-timeout",
                        "30",
                        "--retries",
                        "5",
                        "--force-ipv4",
                        "--no-warnings",
                    ]
                    use_cookies = getattr(self.settings, "use_browser_cookies", True)
                    if use_cookies:
                        browser = getattr(self.settings, "browser_name", "firefox")
                        yt_cmd.extend(["--cookies-from-browser", browser])
                    if (
                        hasattr(self.settings, "proxy_enabled")
                        and self.settings.proxy_enabled
                    ):
                        proxy_url = getattr(self.settings, "proxy_url", "")
                        if proxy_url:
                            yt_cmd.extend(["--proxy", proxy_url])
                    yt_cmd.extend(["-o", "-", video_url])

                    if DEBUG_LEVEL >= 3:
                        log_debug("ffmpeg", f"yt-dlp command: {' '.join(yt_cmd)}")
                    if logger.isEnabledFor(logging.DEBUG):
                        logger.debug(f"yt‑dlp command: {' '.join(yt_cmd)}")

                    yt_process = subprocess.Popen(
                        yt_cmd,
                        stdout=subprocess.PIPE,
                        stderr=subprocess.PIPE,
                        stdin=subprocess.DEVNULL,
                        bufsize=10 * 1024 * 1024,
                        start_new_session=True,
                    )
                    logger.info(
                        f"  ✅ yt‑dlp started (PID: {yt_process.pid}) (Format: {fmt if fmt else 'auto'})"
                    )
                    if DEBUG_LEVEL >= 3:
                        log_debug("ffmpeg", f"yt-dlp started, PID={yt_process.pid}")

                    # yt-dlp stderr‑Thread starten
                    yt_stderr_stop = threading.Event()

                    def read_yt_stderr():
                        try:
                            while not yt_stderr_stop.is_set():
                                line = yt_process.stderr.readline()
                                if not line:
                                    break
                                line_str = line.decode("utf-8", errors="ignore").strip()
                                if line_str:
                                    logger.debug(f"[yt-dlp stderr] {line_str}")
                        except (ValueError, OSError):
                            pass
                        finally:
                            try:
                                if yt_process.stderr and not yt_process.stderr.closed:
                                    yt_process.stderr.close()
                            except Exception:
                                pass

                    yt_stderr_thread = threading.Thread(
                        target=read_yt_stderr, daemon=True
                    )
                    yt_stderr_thread.start()
                    if DEBUG_LEVEL >= 3:
                        log_debug("ffmpeg", "yt-dlp stderr thread started")

                    # Audio-Filter
                    profile = "realtime" if is_live else "transcription"
                    if self.settings and hasattr(self.settings, "audio_profile"):
                        profile = self.settings.audio_profile
                    audio_filter = self.config.get_audio_filter(
                        language=detected_language, profile=profile
                    )
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "ffmpeg",
                            f"Audio filter (profile={profile}): {audio_filter}",
                        )

                    # FFmpeg Befehl aufbauen
                    ff_cmd = [
                        "ffmpeg",
                        "-hide_banner",
                        "-loglevel",
                        "warning" if DEBUG_LEVEL < 3 else "info",
                    ]
                    if fmt is not None:
                        ff_cmd.extend(["-f", fmt])
                    ff_cmd.extend(
                        [
                            "-i",
                            "pipe:0",
                            "-vn",
                            "-f",
                            "s16le",
                            "-acodec",
                            "pcm_s16le",
                            "-ar",
                            str(self.config.SAMPLE_RATE),
                            "-ac",
                            str(self.config.CHANNELS),
                            "-af",
                            audio_filter,
                            "-fflags",
                            "+genpts+discardcorrupt",
                            "-avoid_negative_ts",
                            "make_zero",
                            "-max_interleave_delta",
                            "0",
                            "-threads",
                            "2",
                            "-bufsize",
                            self.config.FFMPEG_BUFSIZE,
                            "pipe:1",
                        ]
                    )

                    if DEBUG_LEVEL >= 3:
                        log_debug("ffmpeg", f"FFmpeg command: {' '.join(ff_cmd)}")
                    if logger.isEnabledFor(logging.DEBUG):
                        logger.debug(f"FFmpeg command: {' '.join(ff_cmd)}")

                    process = subprocess.Popen(
                        ff_cmd,
                        stdin=yt_process.stdout,
                        stdout=subprocess.PIPE,
                        stderr=subprocess.PIPE,
                        bufsize=10 * 1024 * 1024,
                        start_new_session=True,
                    )
                    logger.info(f"  ✅ FFmpeg started (PID: {process.pid})")
                    if DEBUG_LEVEL >= 3:
                        log_debug("ffmpeg", f"FFmpeg started, PID={process.pid}")

                    if self.resource_manager is not None:
                        self.resource_manager.register_process(process)
                        self.resource_manager.register_process(yt_process)

                    # Wartezeit für Prozessinitialisierung
                    time.sleep(self.INITIAL_PROCESS_CHECK_DELAY * 5)
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "ffmpeg",
                            f"Waited {self.INITIAL_PROCESS_CHECK_DELAY*5}s for process startup",
                        )

                    if process.poll() is None:
                        logger.info(
                            f"  ✅ Pipe mode successful with format {fmt if fmt else 'auto'}"
                        )
                        if DEBUG_LEVEL >= 3:
                            log_debug(
                                "ffmpeg",
                                f"Pipe mode successful after {time.time()-format_start:.2f}s",
                            )
                        pipe_success = True
                        break
                    else:
                        stderr_hint = self._read_stderr(process)
                        stderr_display = (
                            stderr_hint if DEBUG_LEVEL >= 3 else stderr_hint[:200]
                        )
                        logger.warning(
                            f"❌ FFmpeg died with format {fmt}, trying next... stderr: {stderr_display}"
                        )
                        if DEBUG_LEVEL >= 3:
                            log_debug(
                                "ffmpeg",
                                f"FFmpeg died (exit code {process.poll()}) with format {fmt}",
                            )
                        continue

                # Nach der Schleife – falls kein Format erfolgreich war
                if not pipe_success:
                    if yt_stderr_thread and yt_stderr_thread.is_alive():
                        if DEBUG_LEVEL >= 3:
                            log_debug(
                                "ffmpeg",
                                f"Kein Format erfolgreich – beende letzten yt-dlp stderr thread für {process_id}",
                            )
                        yt_stderr_stop.set()
                        try:
                            if (
                                yt_process
                                and yt_process.stderr
                                and not yt_process.stderr.closed
                            ):
                                yt_process.stderr.close()
                        except Exception as e:
                            if DEBUG_LEVEL >= 3:
                                log_debug(
                                    "ffmpeg",
                                    f"Fehler beim Schließen der yt-dlp stderr-Pipe: {e}",
                                )
                        yt_stderr_thread.join(timeout=1.0)
                        yt_stderr_thread = None
                        yt_stderr_stop = None
                    logger.error("❌ All pipe formats failed")
                    if DEBUG_LEVEL >= 3:
                        log_debug("ffmpeg", "All pipe formats failed")
                    return None

                # Erfolgreich – registrieren
                self._register_process(
                    process_id,
                    process,
                    output_queue,
                    video_url,
                    is_live,
                    yt_process,
                    pipe_mode=pipe_mode,
                )
                registered = True

                with self._lock:
                    pinfo = self._processes[process_id]
                    pinfo.yt_stderr_thread = yt_stderr_thread
                    pinfo.yt_stderr_stop = yt_stderr_stop

                with self._stats_lock:
                    self._stats["total_processes_started"] += 1
                    self._stats["total_pipe_processes"] += 1

                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "ffmpeg",
                        f"Pipe mode completed in {time.time()-start_time:.2f}s",
                    )
                return process

            # =================================================================
            # 2. NORMALE VERARBEITUNG (für Nicht-YouTube, Nicht-Live)
            # =================================================================
            if DEBUG_LEVEL >= 3:
                log_debug("ffmpeg", "Using normal mode (direct audio URL)")

            # Audio-URL ermitteln / validieren
            if audio_url is None or force_refresh_audio_url:
                logger.info("🎵 Resolving audio URL...")
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "ffmpeg",
                        "Resolving audio URL via stream_manager.extract_audio_url",
                    )
                audio_url = self._extract_audio_url(
                    video_url, force_refresh=is_live or force_refresh_audio_url
                )
                if not audio_url:
                    logger.error("❌ Audio URL resolution failed")
                    if DEBUG_LEVEL >= 3:
                        log_debug("ffmpeg", "Audio URL extraction returned None")
                    return None
                if DEBUG_LEVEL >= 3:
                    logger.info(f"✅ Resolved URL: {audio_url}")
                    log_debug("ffmpeg", f"Resolved URL: {audio_url}")
                else:
                    logger.info(f"✅ Resolved URL: {audio_url[:100]}...")
                    log_debug(
                        "ffmpeg", f"Resolved URL (truncated): {audio_url[:100]}..."
                    )
            else:
                # Prüfe, ob die übergebene audio_url gültig ist
                valid, msg = self._validate_url(audio_url)
                if not valid:
                    logger.error(f"❌ Ungültige Audio-URL: {msg}")
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "ffmpeg",
                            f"Invalid pre-resolved audio URL: {audio_url[:100]} -> {msg}",
                        )
                    return None
                if DEBUG_LEVEL >= 3:
                    logger.info(f"✅ Using pre-resolved audio URL: {audio_url}")
                    log_debug("ffmpeg", f"Using pre-resolved URL: {audio_url}")
                else:
                    logger.info(
                        f"✅ Using pre-resolved audio URL: {audio_url[:100]}..."
                    )
                    log_debug(
                        "ffmpeg",
                        f"Using pre-resolved URL (truncated): {audio_url[:100]}...",
                    )

            # FFmpeg-Befehl erstellen
            cmd = self._build_ffmpeg_command_optimized(
                audio_url,
                seek_seconds=seek_seconds,
                detected_language=detected_language,
            )
            if DEBUG_LEVEL >= 3:
                log_debug("ffmpeg", f"FFmpeg command: {' '.join(cmd)}")

            process_kwargs = {
                "stdout": subprocess.PIPE,
                "stderr": subprocess.PIPE,
                "stdin": subprocess.DEVNULL,
                "bufsize": 10 * 1024 * 1024,
            }
            if IS_WINDOWS:
                process_kwargs["creationflags"] = subprocess.CREATE_NO_WINDOW
                process_kwargs["encoding"] = "utf-8"
                process_kwargs["errors"] = "ignore"
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "ffmpeg", "Windows: added CREATE_NO_WINDOW flag, UTF-8 encoding"
                    )
            elif IS_MACOS or IS_LINUX:
                process_kwargs["start_new_session"] = True
                if DEBUG_LEVEL >= 3:
                    log_debug("ffmpeg", "Unix: start_new_session=True")

            logger.info("🚀 Starting FFmpeg process...")
            process = subprocess.Popen(cmd, **process_kwargs)
            logger.info(f"✅ FFmpeg process started (PID: {process.pid})")
            if DEBUG_LEVEL >= 3:
                log_debug("ffmpeg", f"FFmpeg started, PID={process.pid}")

            if self.resource_manager is not None:
                self.resource_manager.register_process(process)

            time.sleep(self.INITIAL_PROCESS_CHECK_DELAY)
            logger.debug("Initial startup delay completed, checking process status...")

            if process.poll() is not None:
                stderr_hint = self._read_stderr(process)
                stderr_display = stderr_hint if DEBUG_LEVEL >= 3 else stderr_hint[:200]
                logger.error(
                    f"❌ FFmpeg died immediately. Exit code: {process.poll()}, stderr: {stderr_display}"
                )
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "ffmpeg",
                        f"FFmpeg died immediately (exit {process.poll()}), stderr preview: {stderr_display}",
                    )

                # Fallback nur bei Live-Streams
                if is_live:
                    logger.info("🔄 Fallback: Versuche Pipe‑Modus...")
                    if DEBUG_LEVEL >= 3:
                        log_debug("ffmpeg", "Attempting fallback to pipe mode")
                    fallback_process = self._start_pipe(
                        video_url,
                        output_queue,
                        process_id,
                        seek_seconds,
                        detected_language,
                    )
                    if fallback_process is not None:
                        # ✅ Korrektur: Alten (nicht registrierten) Prozess direkt terminieren (ohne Slot-Freigabe)
                        if process is not None and process.poll() is None:
                            self._terminate_process(process)
                        # Neuen Prozess registrieren – der bereits reservierte Slot bleibt erhalten
                        self._register_process(
                            process_id,
                            fallback_process,
                            output_queue,
                            video_url,
                            True,
                            pipe_mode=True,
                        )
                        registered = True
                        with self._stats_lock:
                            self._stats["total_processes_started"] += 1
                        if DEBUG_LEVEL >= 3:
                            log_debug("ffmpeg", "Fallback pipe mode successful")
                        return fallback_process
                    else:
                        if DEBUG_LEVEL >= 3:
                            log_debug("ffmpeg", "Fallback pipe mode failed")
                return None
            else:
                logger.info(f"✅ FFmpeg is running (PID: {process.pid})")
                if DEBUG_LEVEL >= 3:
                    log_debug("ffmpeg", "FFmpeg running, poll() is None")

            # Zusätzliche Wartezeit für HLS-Streams
            if any(
                keyword in audio_url.lower()
                for keyword in ["hls", ".m3u8", "manifest.googlevideo.com"]
            ):
                if DEBUG_LEVEL >= 3:
                    log_debug("ffmpeg", "HLS stream detected, adding extra wait")
                time.sleep(self.HLS_INITIAL_WAIT)
                logger.debug("Additional wait for HLS stream")

            self._register_process(
                process_id, process, output_queue, audio_url, is_live, pipe_mode=False
            )
            registered = True
            with self._stats_lock:
                self._stats["total_processes_started"] += 1

            if DEBUG_LEVEL >= 3:
                log_debug(
                    "ffmpeg", f"Normal mode completed in {time.time()-start_time:.2f}s"
                )
            return process

        except Exception as e:
            logger.error(f"❌ Failed to start FFmpeg: {e}", exc_info=True)
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "ffmpeg",
                    f"Exception in _start_stream_internal: {type(e).__name__}: {e}",
                )
            return None

        finally:
            # Aufräumen, falls der Prozess nicht registriert wurde (d.h. Fehler)
            if not registered:
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "ffmpeg",
                        "Process not registered, performing cleanup in finally",
                    )
                # Wichtig: KEIN _release_slot() hier! Der Slot wird von start_stream() freigegeben.
                if process is not None and process.poll() is None:
                    try:
                        process.terminate()
                        if DEBUG_LEVEL >= 3:
                            log_debug("ffmpeg", f"Terminated process {process.pid}")
                        process.wait(timeout=2.0)
                    except Exception as e:
                        if DEBUG_LEVEL >= 3:
                            log_exception(
                                "ffmpeg",
                                "Error terminating process in finally",
                                e,
                                level="debug",
                            )
                        try:
                            process.kill()
                            if DEBUG_LEVEL >= 3:
                                log_debug("ffmpeg", f"Killed process {process.pid}")
                        except Exception as e2:
                            if DEBUG_LEVEL >= 3:
                                log_exception(
                                    "ffmpeg",
                                    "Error killing process in finally",
                                    e2,
                                    level="debug",
                                )
                if yt_process is not None and yt_process.poll() is None:
                    try:
                        yt_process.terminate()
                        if DEBUG_LEVEL >= 3:
                            log_debug(
                                "ffmpeg", f"Terminated yt-dlp process {yt_process.pid}"
                            )
                        yt_process.wait(timeout=2.0)
                    except Exception as e:
                        if DEBUG_LEVEL >= 3:
                            log_exception(
                                "ffmpeg",
                                "Error terminating yt_process in finally",
                                e,
                                level="debug",
                            )
                        try:
                            yt_process.kill()
                            if DEBUG_LEVEL >= 3:
                                log_debug(
                                    "ffmpeg", f"Killed yt-dlp process {yt_process.pid}"
                                )
                        except Exception as e2:
                            if DEBUG_LEVEL >= 3:
                                log_exception(
                                    "ffmpeg",
                                    "Error killing yt_process in finally",
                                    e2,
                                    level="debug",
                                )
                # yt_stderr_thread im finally beenden
                if yt_stderr_thread and yt_stderr_thread.is_alive():
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "ffmpeg",
                            f"Finally: beende yt-dlp stderr thread für {process_id}",
                        )
                    if yt_stderr_stop:
                        yt_stderr_stop.set()
                    try:
                        if (
                            yt_process
                            and yt_process.stderr
                            and not yt_process.stderr.closed
                        ):
                            yt_process.stderr.close()
                    except Exception:
                        pass
                    yt_stderr_thread.join(timeout=1.0)
                    yt_stderr_thread = None
                    yt_stderr_stop = None

    def read_audio_data(self, process_id: str, size: int) -> Optional[bytes]:
        """Liest Audiodaten aus dem stdout‑Stream eines laufenden FFmpeg‑Prozesses."""
        with self._lock:
            if process_id not in self._processes:
                log_debug(
                    "ffmpeg", f"read_audio_data: process_id {process_id} not found"
                )
                return None
            pinfo = self._processes[process_id]
            if pinfo.stopping:
                log_debug(
                    "ffmpeg",
                    f"read_audio_data: process {process_id} is stopping, skipping",
                )
                return None
            process = pinfo.process
            read_queue = pinfo.read_queue
            if read_queue is None:
                log_debug("ffmpeg", f"read_audio_data: no read_queue for {process_id}")
                return None

            # Prüfe, ob der Lesethread noch lebt
            if pinfo.read_thread and not pinfo.read_thread.is_alive():
                logger.warning(
                    f"⚠️ read_audio_data: read thread for {process_id} is dead"
                )
                self._remove_process(process_id)
                return None

        # Dynamischer Timeout – bei Stop sehr kurz, sonst normal
        if pinfo.stopping or self._global_shutdown:
            timeout = 0.1
            log_debug(
                "ffmpeg",
                f"read_audio_data: using short timeout {timeout:.1f}s (stopping)",
            )
        elif pinfo.is_live or ".m3u8" in pinfo.url.lower():
            if self._read_times:
                avg_read = sum(self._read_times) / len(self._read_times)
                timeout = max(30.0, avg_read * 2.0)
                timeout = min(timeout, 60.0)
            else:
                timeout = 30.0
            log_debug("ffmpeg", f"read_audio_data: live stream timeout={timeout:.1f}s")
        else:
            timeout = self.PROCESS_TIMEOUT
            log_debug("ffmpeg", f"read_audio_data: normal timeout={timeout:.1f}s")

        start_read = time.perf_counter()
        collected = []
        remaining = size

        # Verwende eventuell vorhandenen Puffer aus vorherigem Lesevorgang
        if pinfo.read_buffer:
            collected.append(pinfo.read_buffer)
            remaining -= len(pinfo.read_buffer)
            pinfo.read_buffer = b""

        while remaining > 0:
            try:
                data = read_queue.get(timeout=timeout)
            except queue.Empty:
                with self._lock:
                    pinfo.stats["timeouts"] += 1
                logger.warning(
                    f"⏰ Lese-Timeout für {process_id} nach {timeout:.1f}s "
                    f"(Chunks: {pinfo.chunks_processed}, "
                    f"letzte Aktivität: {time.time() - pinfo.last_activity:.1f}s her, "
                    f"Bytes: {pinfo.bytes_read})"
                )
                break
            if data is None:
                log_debug(
                    "ffmpeg",
                    f"read_audio_data: received None (sentinel) for {process_id}",
                )
                break
            if data == b"":
                log_debug(
                    "ffmpeg", f"read_audio_data: received empty data for {process_id}"
                )
                break

            if len(data) > remaining:
                pinfo.read_buffer = data[remaining:]
                data = data[:remaining]

            collected.append(data)
            remaining -= len(data)

        if not collected:
            if process.poll() is not None:
                logger.warning(
                    f"⚠️ Process {process_id} terminated (exit: {process.poll()})"
                )
                self._remove_process(process_id)
            return None

        audio_data = b"".join(collected)
        read_duration = time.perf_counter() - start_read
        if read_duration > 0.1:
            self._read_times.append(read_duration)

        with self._lock:
            pinfo.bytes_read += len(audio_data)
            pinfo.chunks_processed += 1
            pinfo.last_activity = time.time()
            pinfo.stats["total_reads"] += 1
            pinfo.stats["total_read_bytes"] += len(audio_data)
            pinfo.stats["last_read_duration_ms"] = read_duration * 1000
            pinfo.stats["last_read_time"] = time.time()

        if DEBUG_LEVEL >= 3:
            log_debug(
                "ffmpeg",
                f"Read {len(audio_data)} bytes from PID {process.pid} in {read_duration*1000:.2f}ms",
            )
        return audio_data

    def stop_stream(self, process_id: str) -> bool:
        """
        Stoppt einen laufenden Stream und gibt alle zugehörigen Ressourcen frei.

        Diese Methode setzt das Stop‑Flag, schließt Pipes, stoppt die Lese‑ und
        Stderr‑Threads und entfernt den Prozess aus der Registry. Sie ist
        thread‑sicher und vermeidet Race Conditions mit parallel laufenden
        `_remove_process`‑Aufrufen durch Prüfung des `_removing`‑Flags.

        Args:
            process_id: Eindeutige Kennung des zu stoppenden Streams.

        Returns:
            True, wenn der Stream gefunden und gestoppt wurde, sonst False.
        """
        with self._lock:
            if process_id not in self._processes:
                logger.debug(f"[FFmpegManager] stop_stream: {process_id} not found")
                return False
            pinfo = self._processes[process_id]

            # Vermeide doppelte Stopps, wenn der Prozess bereits entfernt wird
            if pinfo._removing:
                logger.debug(
                    f"stop_stream: process {process_id} already being removed, skipping"
                )
                return False

            pinfo.stopping = True
            log_debug("ffmpeg", f"stop_stream: {process_id} stopping set")

            # Sentinel in die Queue legen, um blockierenden get() zu beenden
            if pinfo.read_queue is not None:
                try:
                    pinfo.read_queue.put_nowait(None)
                    log_debug("ffmpeg", f"Sentinel in read_queue for {process_id}")
                except queue.Full:
                    log_debug(
                        "ffmpeg",
                        f"read_queue full for {process_id} – cannot insert sentinel",
                    )

            # Pipes früh schließen, bevor Threads gestoppt werden
            if pinfo.process:
                for pipe_name in ("stdout", "stderr", "stdin"):
                    pipe = getattr(pinfo.process, pipe_name, None)
                    if pipe and not pipe.closed:
                        try:
                            pipe.close()
                            log_debug(
                                "ffmpeg", f"Pipe {pipe_name} closed for {process_id}"
                            )
                        except Exception as e:
                            logger.warning(
                                f"Error closing pipe {pipe_name} for {process_id}: {e}"
                            )

            self._stop_read_thread(pinfo)
            self._stop_stderr_thread(pinfo)

            yt_thread = getattr(pinfo, "yt_stderr_thread", None)
            if yt_thread is not None:
                yt_stop = getattr(pinfo, "yt_stderr_stop", None)
                if yt_stop:
                    yt_stop.set()
                    log_debug("ffmpeg", f"yt_stop event set for {process_id}")
                try:
                    if (
                        pinfo.yt_process
                        and pinfo.yt_process.stderr
                        and not pinfo.yt_process.stderr.closed
                    ):
                        pinfo.yt_process.stderr.close()
                        log_debug("ffmpeg", f"Closed yt stderr for {process_id}")
                except Exception as e:
                    logger.warning(f"Error closing yt stderr for {process_id}: {e}")
                # Kein join – Thread ist Daemon
                pinfo.yt_stderr_thread = None
                pinfo.yt_stderr_stop = None
                log_debug("ffmpeg", f"yt_stderr thread cleared for {process_id}")

        return self._remove_process(process_id)

    def stop_all_streams(self) -> None:
        logger.info("🛑 Stopping all streams...")
        with self._lock:
            self._shutting_down = True
            process_ids = list(self._processes.keys())
        threads = []
        for pid in process_ids:
            t = threading.Thread(target=self._remove_process, args=(pid,), daemon=True)
            t.start()
            threads.append(t)
        for t in threads:
            t.join(timeout=2.0)
        with self._lock:
            self._shutting_down = False
        logger.info("✅ All streams stopped")

    def kill_all_streams(self) -> None:
        """Beendet alle Streams sofort mit SIGKILL (oder taskkill unter Windows)."""
        self._global_shutdown = True
        logger.info("🔥 kill_all_streams: Start")

        # Snapshot unter Lock erstellen
        with self._lock:
            processes_snapshot = list(self._processes.items())
            if not processes_snapshot:
                logger.info("🔥 kill_all_streams: Keine aktiven Prozesse")
                return

        logger.debug(f"kill_all_streams: {len(processes_snapshot)} Prozesse gefunden")

        for process_id, pinfo in processes_snapshot:
            # FFmpeg-Prozess
            proc = pinfo.process
            if proc and proc.poll() is None:
                pid = proc.pid
                logger.info(f"🔥 Sende SIGKILL an FFmpeg (PID {pid}) für {process_id}")
                try:
                    if IS_WINDOWS:
                        subprocess.run(
                            ["taskkill", "/F", "/T", "/PID", str(pid)],
                            capture_output=True,
                            timeout=1,
                            check=False,
                            creationflags=subprocess.CREATE_NO_WINDOW,
                        )
                    else:
                        os.kill(pid, py_signal.SIGKILL)
                except ProcessLookupError:
                    logger.debug(f"Prozess {pid} existiert nicht mehr")
                except Exception as e:
                    logger.warning(f"Fehler beim Killen von FFmpeg PID {pid}: {e}")

            # yt-dlp-Prozess
            yt_proc = pinfo.yt_process
            if yt_proc and yt_proc.poll() is None:
                pid = yt_proc.pid
                logger.info(f"🔥 Sende SIGKILL an yt-dlp (PID {pid}) für {process_id}")
                try:
                    if IS_WINDOWS:
                        subprocess.run(
                            ["taskkill", "/F", "/T", "/PID", str(pid)],
                            capture_output=True,
                            timeout=1,
                            check=False,
                            creationflags=subprocess.CREATE_NO_WINDOW,
                        )
                    else:
                        os.kill(pid, py_signal.SIGKILL)
                except ProcessLookupError:
                    logger.debug(f"Prozess {pid} existiert nicht mehr")
                except Exception as e:
                    logger.warning(f"Fehler beim Killen von yt-dlp PID {pid}: {e}")

        time.sleep(0.1)  # Kurze Pause für Prozess-Terminierung

        # Registry unter Lock leeren
        with self._lock:
            self._processes.clear()
            self._pid_tracking.clear()

        gc.collect()
        logger.info("🔥 kill_all_streams: Abgeschlossen")

    def cancel_all_reads(self) -> None:
        """Bricht alle aktuell laufenden Lesevorgänge ab (sofort)."""
        with self._lock:
            for pinfo in self._processes.values():
                if pinfo.current_read_future and not pinfo.current_read_future.done():
                    pinfo.current_read_future.cancel()
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "ffmpeg", f"Canceled read future for {pinfo.process_id}"
                        )
                if pinfo.read_stop:
                    pinfo.read_stop.set()

    def is_active(self, process_id: str) -> bool:
        with self._lock:
            if process_id not in self._processes:
                return False
            pinfo = self._processes[process_id]
            try:
                if pinfo.process.poll() is not None:
                    return False
                if time.time() - pinfo.last_activity > self.MAX_IDLE_SECONDS:
                    return False
                return True
            except AttributeError:
                logger.warning(f"⚠️ is_active: Attribut fehlt für {process_id}")
                return False
            except Exception as e:
                logger.error(f"❌ is_active: Unerwarteter Fehler für {process_id}: {e}")
                return False

    def update_process_activity(self, process_id: str) -> None:
        with self._lock:
            if process_id in self._processes:
                self._processes[process_id].last_activity = time.time()

    def get_stats(self) -> Dict[str, Any]:
        with self._lock:
            with self._stats_lock:
                stats = self._stats.copy()
                stats["uptime_seconds"] = time.time() - stats["start_time"]
                if stats["extraction_attempts"] > 0:
                    stats["success_rate"] = (
                        stats["successful_extractions"] / stats["extraction_attempts"]
                    ) * 100
                    stats["failure_rate"] = (
                        stats["failed_extractions"] / stats["extraction_attempts"]
                    ) * 100
                else:
                    stats["success_rate"] = stats["failure_rate"] = 0

            stats["active_processes"] = len(
                [p for p in self._processes.values() if p.process.poll() is None]
            )
            stats["total_processes"] = len(self._processes)
            stats["live_detection_cache_size"] = len(self._live_detection_cache._cache)
            stats["semaphore_value"] = self._active_slots

            process_reads = 0
            process_bytes = 0
            process_errors = 0
            process_timeouts = 0
            process_reconnects = 0
            for pinfo in self._processes.values():
                s = pinfo.stats
                process_reads += s["total_reads"]
                process_bytes += s["total_read_bytes"]
                process_errors += s["read_errors"]
                process_timeouts += s.get("timeouts", 0)
                process_reconnects += s.get("reconnects", 0)
            stats["process_total_reads"] = process_reads
            stats["process_total_bytes"] = process_bytes
            stats["process_read_errors"] = process_errors
            stats["process_timeouts"] = process_timeouts
            stats["process_reconnects"] = process_reconnects
            return stats

    def get_process_info(self, process_id: str) -> Optional[Dict[str, Any]]:
        with self._lock:
            if process_id not in self._processes:
                return None
            pinfo = self._processes[process_id]
            return {
                "process_id": pinfo.process_id,
                "pid": pinfo.process.pid if pinfo.process else None,
                "yt_pid": pinfo.yt_process.pid if pinfo.yt_process else None,
                "url": pinfo.url,
                "platform": pinfo.platform,
                "is_live": pinfo.is_live,
                "pipe_mode": pinfo.pipe_mode,
                "start_time": pinfo.start_time,
                "last_activity": pinfo.last_activity,
                "bytes_read": pinfo.bytes_read,
                "chunks_processed": pinfo.chunks_processed,
                "stats": pinfo.stats.copy(),
                "is_alive": pinfo.process.poll() is None,
                "stopping": pinfo.stopping,
                "has_pending_read": pinfo.current_read_future is not None,
                "last_error": pinfo.last_error,
                "error_count": pinfo.error_count,
                "last_stderr_line": pinfo.last_stderr_line,
            }

    def get_semaphore_value(self) -> int:
        """Gibt die Anzahl aktuell belegter Slots zurück (thread‑sicher)."""
        with self._lock:
            return self._active_slots

    def get_active_process_count(self) -> int:
        """Gibt die Anzahl der noch aktiven (laufenden) Prozesse zurück."""
        with self._lock:
            return sum(
                1 for pinfo in self._processes.values() if pinfo.process.poll() is None
            )

    @contextmanager
    def slot_context(self, purpose: str = ""):
        """
        Kontextmanager für automatische Slot‑Freigabe.
        Beispiel:
            with self.slot_context("start_stream_123"):
                # Slot ist belegt, geschützte Operationen durchführen
                ...
        Wirft RuntimeError, wenn kein Slot erworben werden konnte.
        """
        if not self._acquire_slot(purpose):
            raise RuntimeError(f"Could not acquire slot for '{purpose}'")
        try:
            yield
        finally:
            self._release_slot(purpose)

    def dispose(self) -> None:
        """
        Schließt alle Ressourcen und beendet den Cleanup-Thread sauber.
        Bei DEBUG_LEVEL >= 3 werden detaillierte Statusmeldungen ausgegeben.
        """
        logger.info("🧹 Shutting down FFmpeg Manager...")
        self._global_shutdown = True

        # ===== 1. Cleanup-Thread stoppen =====
        if self._cleanup_thread and self._cleanup_thread.is_alive():
            log_debug("ffmpeg", "Stopping cleanup thread...")
            self._cleanup_stop_event.set()
            # Kurz warten, damit der Thread das Event bemerkt und sich beendet
            time.sleep(0.1)
            # Nicht auf den Thread warten – er ist ein Daemon und wird beim Prozessende beendet
            log_debug("ffmpeg", "Cleanup thread will exit on its own (daemon)")
        else:
            log_debug("ffmpeg", "No cleanup thread active")

        # ===== 2. Alle laufenden Streams beenden =====
        log_debug("ffmpeg", "Killing all active streams...")
        try:
            self.kill_all_streams()
        except Exception as e:
            logger.error(f"Error while killing streams: {e}", exc_info=True)
        log_debug("ffmpeg", "All streams killed")

        # ===== 3. Caches und Registry leeren =====
        log_debug("ffmpeg", "Clearing caches...")
        try:
            self._live_detection_cache.clear()
            self._pid_tracking.clear()
            self._processes.clear()
            log_debug("ffmpeg", "Caches cleared")
        except Exception as e:
            logger.warning(f"Error while clearing caches: {e}")

        # ===== 4. Finale Bereinigung =====
        self._disposed = True
        gc.collect()
        log_debug("ffmpeg", "Garbage collection triggered")
        logger.info("✅ FFmpeg Manager disposed")

    # -------------------------------------------------------------------------
    #  Private Hilfsmethoden
    # -------------------------------------------------------------------------
    def _acquire_slot(self, purpose: str = "") -> bool:
        """
        Versucht, einen Slot zu belegen.
        Args:
            purpose: Optionale Beschreibung für Debug‑Logs (z. B. process_id).
        Returns:
            True bei Erfolg, False wenn kein Slot frei ist.
        """
        acquired = self._process_semaphore.acquire(blocking=False)
        if not acquired:
            logger.debug(f"❌ Slot nicht verfügbar (purpose={purpose})")
            return False

        with self._lock:
            self._active_slots += 1
            current = self._active_slots
            max_slots = self._process_semaphore_max

        logger.debug(
            f"✅ Slot belegt (purpose={purpose}) – "
            f"active_slots={current}/{max_slots}"
        )
        if DEBUG_LEVEL >= 3:
            # Detaillierte Stack‑Trace bei hohem Debug‑Level
            import traceback
            stack = traceback.extract_stack()[-3:-1]
            caller = " -> ".join(f"{f.name}:{f.lineno}" for f in stack)
            log_debug("slot", f"  Acquired by: {caller}")

        return True

    def _release_slot(self, purpose: str = "") -> None:
        """
        Gibt einen zuvor belegten Slot frei.
        Args:
            purpose: Optionale Beschreibung für Debug‑Logs.
        """
        with self._lock:
            if self._active_slots > 0:
                self._active_slots -= 1
                current = self._active_slots
            else:
                logger.error(
                    f"❌ CRITICAL: _release_slot called but _active_slots is already 0! "
                    f"(purpose={purpose})"
                )
                current = 0

        self._process_semaphore.release()
        max_slots = self._process_semaphore_max
        logger.debug(
            f"🔓 Slot freigegeben (purpose={purpose}) – "
            f"active_slots={current}/{max_slots}"
        )
        if DEBUG_LEVEL >= 3 and current == 0:
            log_debug("slot", "  All slots are now free.")

    @contextmanager
    def _slot_context(self):
        """Kontextmanager für Slot-Beleigung. Gibt RuntimeError bei fehlendem Slot."""
        if not self._acquire_slot():
            raise RuntimeError("No free slot")
        try:
            yield
        finally:
            self._release_slot()

    def _validate_url(self, url: str) -> Tuple[bool, str]:
        if self.stream_manager is not None and hasattr(
            self.stream_manager, "validate_url"
        ):
            return self.stream_manager.validate_url(url)
        if not url or not url.strip():
            return False, "Empty URL"
        if url.startswith(("http://", "https://", "file://", "dvb://", "dvb-s://")):
            return True, "ok"
        return False, "Invalid URL scheme"

    def _extract_audio_url(
        self, video_url: str, force_refresh: bool, timeout: float = 30.0
    ) -> Optional[str]:
        """Extrahiert die Audio-URL aus einer Video-URL über den StreamManager."""
        if self.stream_manager is None:
            logger.error(
                "StreamManager nicht verfügbar – kann Audio‑URL nicht extrahieren"
            )
            return None

        log_debug(
            "ffmpeg",
            f"  ⏳ Extrahiere neue Audio‑URL (Timeout {timeout}s, force_refresh={force_refresh})...",
        )
        result = [None]
        error = [None]

        def extract():
            try:
                with self._stats_lock:
                    self._stats["extraction_attempts"] += 1
                url = self.stream_manager.extract_audio_url(
                    video_url, force_refresh=force_refresh
                )
                if url:
                    with self._stats_lock:
                        self._stats["successful_extractions"] += 1
                    result[0] = url
                else:
                    with self._stats_lock:
                        self._stats["failed_extractions"] += 1
            except Exception as e:
                error[0] = e
                logger.error(f"Fehler bei der Audio‑URL‑Extraktion: {e}", exc_info=True)

        thread = threading.Thread(target=extract, daemon=True)
        thread.start()
        thread.join(timeout)

        if thread.is_alive():
            logger.error(
                f"⏰ Extraktion der Audio‑URL nach {timeout}s abgebrochen (Thread hängt)"
            )
            return None

        if error[0]:
            return None
        return result[0]

    def _start_pipe(
        self,
        video_url: str,
        output_queue: Optional[queue.Queue],
        process_id: str,
        seek_seconds: Optional[float],
        detected_language: Optional[str],
    ) -> Optional[subprocess.Popen]:
        """
        Startet den Pipe‑Zweig (yt‑dlp + FFmpeg) als Fallback (optimiert).
        Verwendet den in den Einstellungen konfigurierten Browser für Cookies.
        """
        logger.info("  🎥 Pipe‑Fallback: Verwende yt‑dlp als Datenquelle")

        # Browser aus den Einstellungen lesen
        try:
            if hasattr(self, "settings") and self.settings is not None:
                browser = getattr(self.settings, "cookies_browser", "firefox")
            else:
                settings = AppSettings.load_from_file()
                browser = getattr(settings, "cookies_browser", "firefox")
        except Exception:
            browser = "firefox"

        # Format-String priorisiert reine Audio-Formate
        format_str = "bestaudio[ext=m4a]/bestaudio[ext=webm]/bestaudio/worstaudio"

        yt_cmd = [
            "yt-dlp",
            "-f", format_str,
            "--no-playlist",
            "--verbose",
            "--no-warnings",
        ]
        use_cookies = getattr(self.settings, "use_browser_cookies", True)
        if use_cookies:
            yt_cmd.extend(["--cookies-from-browser", browser])
        if hasattr(self.settings, "proxy_enabled") and self.settings.proxy_enabled:
            proxy_url = getattr(self.settings, "proxy_url", "")
            if proxy_url:
                yt_cmd.extend(["--proxy", proxy_url])
        yt_cmd.extend(["-o", "-", video_url])

        if logger.isEnabledFor(logging.DEBUG):
            logger.debug(f"yt‑dlp command: {' '.join(yt_cmd)}")

        yt_process = subprocess.Popen(
            yt_cmd,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            stdin=subprocess.DEVNULL,
            bufsize=10 * 1024 * 1024,
            start_new_session=True,
        )
        logger.info(f"  ✅ yt‑dlp started (PID: {yt_process.pid})")

        # Kurze Wartezeit, um sofortigen Prozess-Tod zu erkennen
        time.sleep(0.5)
        if yt_process.poll() is not None:
            stderr_hint = self._read_stderr(yt_process)
            logger.error(
                f"❌ yt-dlp starb sofort (Exit {yt_process.poll()}). "
                f"Stderr: {stderr_hint[:200]}"
            )
            return None

        profile = "realtime"
        if self.settings and hasattr(self.settings, "audio_profile"):
            profile = self.settings.audio_profile
        audio_filter = self.config.get_audio_filter(
            language=detected_language, profile=profile
        )

        ff_cmd = [
            "ffmpeg",
            "-hide_banner",
            "-loglevel",
            "warning",
            "-i",
            "pipe:0",
            "-vn",
            "-f",
            "s16le",
            "-acodec",
            "pcm_s16le",
            "-ar",
            str(self.config.SAMPLE_RATE),
            "-ac",
            str(self.config.CHANNELS),
            "-af",
            audio_filter,
            "-fflags",
            "+genpts+discardcorrupt",
            "-avoid_negative_ts",
            "make_zero",
            "-max_interleave_delta",
            "0",
            "-threads",
            "2",
            "-bufsize",
            self.config.FFMPEG_BUFSIZE,
            "pipe:1",
        ]

        if logger.isEnabledFor(logging.DEBUG):
            logger.debug(f"FFmpeg command: {' '.join(ff_cmd)}")

        process = subprocess.Popen(
            ff_cmd,
            stdin=yt_process.stdout,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            bufsize=10 * 1024 * 1024,
            start_new_session=True,
        )
        logger.info(f"  ✅ FFmpeg started (PID: {process.pid})")

        if self.resource_manager is not None:
            self.resource_manager.register_process(process)
            self.resource_manager.register_process(yt_process)

        # Wartezeit für FFmpeg-Pipe (optimiert)
        max_wait = 10.0
        interval = 1.0
        waited = 0.0
        process_ready = False
        if DEBUG_LEVEL >= 3:
            log_debug("pipe", f"Waiting up to {max_wait}s for FFmpeg pipe to become ready...")
        while waited < max_wait:
            if process.poll() is not None:
                if DEBUG_LEVEL >= 3:
                    log_debug("pipe", f"FFmpeg died early after {waited:.1f}s (exit {process.poll()})")
                break
            if waited >= 2.0 and process.poll() is None:
                if DEBUG_LEVEL >= 3:
                    log_debug("pipe", f"FFmpeg still alive after {waited:.1f}s, assuming ready")
                process_ready = True
                break
            time.sleep(interval)
            waited += interval
        else:
            if process.poll() is None:
                process_ready = True
                if DEBUG_LEVEL >= 3:
                    log_debug("pipe", f"FFmpeg still alive after {max_wait}s timeout, assuming ready")
            else:
                process_ready = False
                if DEBUG_LEVEL >= 3:
                    log_debug("pipe", f"FFmpeg dead after {max_wait}s timeout (exit {process.poll()})")

        if not process_ready or process.poll() is not None:
            stderr_hint = self._read_stderr(process)
            yt_stderr = ""
            if yt_process.poll() is not None:
                yt_stderr = self._read_stderr(yt_process)
            logger.error(
                f"❌ FFmpeg in pipe did not become ready after {max_wait}s. "
                f"Exit code: {process.poll() if process.poll() is not None else 'N/A'}, "
                f"FFmpeg stderr: {stderr_hint[:200]}, yt‑dlp stderr: {yt_stderr[:200]}"
            )
            try:
                process.terminate()
                yt_process.terminate()
            except Exception:
                pass
            return None

        logger.info(f"  ✅ Pipe mode ready after {waited:.1f}s")
        return process

    def _check_youtube_live_by_metadata(self, url: str) -> bool:
        cache_key = f"live_meta_{hashlib.md5(url.encode()).hexdigest()[:16]}"
        cached = self._live_detection_cache.get(cache_key)
        if cached is not None:
            if time.time() - cached["timestamp"] < 300:
                log_debug(
                    "ffmpeg",
                    f"Metadata check (cached): {url[:50]} is_live={cached['is_live']}",
                )
                return cached["is_live"]

        try:
            import json

            cmd = [
                "yt-dlp",
                "--dump-json",
                "--no-warnings",
                "--no-check-certificate",
                "--socket-timeout",
                "5",
                url,
            ]
            proc = subprocess.run(cmd, capture_output=True, text=True, timeout=10)
            if proc.returncode == 0 and proc.stdout:
                data = json.loads(proc.stdout)
                is_live = data.get("is_live", False)
                self._live_detection_cache.put(
                    cache_key,
                    {"is_live": is_live, "timestamp": time.time(), "url": url[:50]},
                )
                log_debug("ffmpeg", f"Metadata check: {url[:50]} is_live={is_live}")
                return is_live
        except Exception as e:
            log_debug("ffmpeg", f"Metadata check failed: {e}")
        return False

    def _build_ffmpeg_command_optimized(
        self,
        url: str,
        seek_seconds: Optional[float] = None,
        detected_language: Optional[str] = None,
    ) -> List[str]:
        """
        Erstellt eine optimierte FFmpeg-Befehlszeile für den angegebenen Stream.

        Args:
            url: Die Audio-URL (kann auch die Video-URL sein, wenn keine separate Audio-URL existiert).
            seek_seconds: Startposition in Sekunden (nur bei Nicht-Live-Inhalten).
            detected_language: Erkannte Sprache für sprachspezifische Filter.

        Returns:
            Liste der Befehlsargumente für subprocess.Popen.
        """
        log_debug("ffmpeg", f"_build_ffmpeg_command_optimized: url={url[:100]}...")
        is_live, platform = self._detect_stream_type(url)
        stream_type = "LIVE" if is_live else "VIDEO"
        logger.info(f"\n🎬 Building FFmpeg command for {platform} ({stream_type})")
        if DEBUG_LEVEL >= 3:
            logger.info(f"  📍 URL: {url}")
        else:
            logger.info(f"  📍 URL: {url[:80]}...")

        cmd = ["ffmpeg", "-hide_banner", "-loglevel", "warning"]

        # YouTube-spezifische Header und User-Agent
        if "youtube.com" in url.lower() or "youtu.be" in url.lower():
            logger.info("  🎯 Adding YouTube-specific headers")
            cmd.extend(
                [
                    "-user_agent",
                    "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36",
                    "-referer",
                    "https://www.youtube.com/",
                ]
            )
            headers_string = self._get_youtube_headers_string(self.config)
            cmd.extend(["-headers", headers_string])
            log_debug("ffmpeg", "  ↪ YouTube headers added")

        # Live-Stream vs. On-Demand
        if is_live:
            logger.info("  📡 LIVE: Using optimized HLS/Live parameters")
            cmd.extend(
                [
                    "-reconnect",
                    "1",
                    "-reconnect_streamed",
                    "1",
                    "-reconnect_delay_max",
                    "10",
                    "-reconnect_on_network_error",
                    "1",
                    "-timeout",
                    "10000000",
                    "-rw_timeout",
                    "30000000",
                    "-multiple_requests",
                    "1",
                    "-seekable",
                    "0",
                    "-fflags",
                    "+discardcorrupt+fastseek+genpts",
                    "-analyzeduration",
                    "10M",
                    "-probesize",
                    "10M",
                ]
            )
            if "youtube.com" not in url.lower() and "youtu.be" not in url.lower():
                cmd.extend(
                    [
                        "-live_start_index",
                        "0",
                        "-hls_time",
                        "0",
                        "-hls_playlist_type",
                        "event",
                        "-hls_flags",
                        "discard_segments",
                        "-max_reload",
                        "0",
                    ]
                )
            if seek_seconds is not None:
                logger.warning(
                    f"⚠️ seek_seconds={seek_seconds} wird bei Live-Stream ignoriert"
                )
        else:
            logger.info("  🎬 VIDEO: Fast access for non-live content")
            cmd.extend(
                [
                    "-rw_timeout",
                    "10000000",
                    "-accurate_seek",
                    "-fflags",
                    "+genpts+discardcorrupt+fastseek",
                ]
            )
            if seek_seconds is not None and seek_seconds > 0:
                logger.info(f"  ⏩ Seeking to {seek_seconds}s")
                cmd.extend(["-ss", str(seek_seconds)])

        # Eingabe-URL
        cmd.extend(["-i", url])

        # Audio-Filter basierend auf Profil und Sprache
        profile = "realtime" if is_live else "transcription"
        if self.settings and hasattr(self.settings, "audio_profile"):
            profile = self.settings.audio_profile
        audio_filter = self.config.get_audio_filter(
            language=detected_language, profile=profile
        )
        logger.info(f"  🎚️ Using audio filter (profile={profile}): {audio_filter}")

        # Ausgabeformat und Encoder
        cmd.extend(
            [
                "-vn",
                "-f",
                "s16le",
                "-acodec",
                "pcm_s16le",
                "-ar",
                str(self.config.SAMPLE_RATE),
                "-ac",
                str(self.config.CHANNELS),
                "-af",
                audio_filter,
                "-fflags",
                "+genpts+discardcorrupt",
                "-avoid_negative_ts",
                "make_zero",
                "-max_interleave_delta",
                "0",
                "-threads",
                "2",
                "-bufsize",
                self.config.FFMPEG_BUFSIZE,
                "pipe:1",
            ]
        )

        if logger.isEnabledFor(logging.DEBUG):
            # Bei DEBUG_LEVEL >= 3 die gesamte Befehlszeile ausgeben
            if DEBUG_LEVEL >= 3:
                logger.debug(f"FFmpeg command: {' '.join(cmd)}")
            else:
                # Gekürzte Ausgabe, damit Log nicht überflutet wird
                logger.debug(
                    f"FFmpeg command: {' '.join(cmd[:5])} ... {' '.join(cmd[-5:])}"
                )

        # Zusätzliche Debug-Informationen
        log_debug(
            "ffmpeg",
            f"  ↪ Stream type: {'live' if is_live else 'vod'}, platform={platform}",
        )
        if detected_language:
            log_debug("ffmpeg", f"  ↪ Detected language: {detected_language}")
        if seek_seconds:
            log_debug("ffmpeg", f"  ↪ Seek position: {seek_seconds}s")

        return cmd

    @classmethod
    def _get_youtube_headers_string(cls, config: Config) -> str:
        if cls._YOUTUBE_HEADERS_STRING is None:
            headers_dict = config.get_youtube_headers(is_manifest=False)
            headers_list = [f"{k}: {v}" for k, v in headers_dict.items()]
            cls._YOUTUBE_HEADERS_STRING = "\r\n".join(headers_list)
        return cls._YOUTUBE_HEADERS_STRING

    def _detect_stream_type(self, url: str) -> Tuple[bool, str]:
        cache_key = hashlib.md5(url.encode()).hexdigest()[:16]
        cached = self._live_detection_cache.get(cache_key)
        if cached is not None:
            if time.time() - cached["timestamp"] < 300:
                return cached["is_live"], cached["platform"]

        is_live = False
        platform = "unknown"
        try:
            url_lower = url.lower()
            if "youtube.com" in url_lower or "youtu.be" in url_lower:
                platform = "YouTube"
                is_live = any(
                    indicator in url_lower
                    for indicator in [
                        "/live",
                        "live=1",
                        "/stream",
                        "livestream",
                        "live/",
                        "&live",
                        "?live",
                        "/watch_live",
                    ]
                )
                if logger.isEnabledFor(logging.DEBUG):
                    logger.debug(
                        f"YouTube detection: {url_lower[:100]}, is_live={is_live}"
                    )
            elif "twitch.tv" in url_lower:
                platform = "Twitch"
                is_live = True
            elif "tiktok.com" in url_lower:
                platform = "TikTok"
                is_live = "live" in url_lower
            elif "facebook.com" in url_lower or "fb.watch" in url_lower:
                platform = "Facebook"
                is_live = "live" in url_lower or "watch/live" in url_lower
            elif "kick.com" in url_lower:
                platform = "Kick"
                is_live = True
            elif "rumble.com" in url_lower:
                platform = "Rumble"
                is_live = "live" in url_lower
            elif "dailymotion.com" in url_lower:
                platform = "Dailymotion"
                is_live = "live" in url_lower
            elif "vimeo.com" in url_lower:
                platform = "Vimeo"
                is_live = "live" in url_lower
            elif "twitter.com" in url_lower or "x.com" in url_lower:
                platform = "Twitter/X"
                is_live = "live" in url_lower
            elif url_lower.startswith("file://"):
                platform = "Local File"
                is_live = False
            elif ".m3u8" in url_lower:
                platform = "HLS Stream"
                is_live = True
            elif ".mpd" in url_lower:
                platform = "DASH Stream"
                is_live = True
            else:
                platform = "HTTP Stream"

            self._live_detection_cache.put(
                cache_key,
                {
                    "is_live": is_live,
                    "platform": platform,
                    "timestamp": time.time(),
                    "url": url[:50],
                },
            )
            log_debug(
                "ffmpeg",
                f"detect_stream_type: url={url[:50]}, is_live={is_live}, platform={platform}",
            )
            return is_live, platform

        except Exception as e:
            logger.warning(f"⚠️ Stream type detection error: {e}")
            return False, "unknown"

    def _register_process(
        self,
        process_id: str,
        process: subprocess.Popen,
        output_queue: Optional[queue.Queue],
        url: str,
        is_live: bool,
        yt_process: Optional[subprocess.Popen] = None,
        pipe_mode: bool = False,
    ) -> None:
        """
        Registriert einen neuen FFmpeg-Prozess im Manager.
        Vorherige Einträge mit derselben process_id werden sauber bereinigt.
        """
        # 1. Existierenden Prozess mit derselben ID bereinigen
        with self._lock:
            if process_id in self._processes:
                old_pinfo = self._processes[process_id]
                logger.warning(
                    f"⚠️ Überschreibe bestehende Prozess-ID {process_id} (PID {old_pinfo.process.pid}) – "
                    f"führe Bereinigung durch."
                )
                old_pinfo._skip_semaphore_release = True
                self._remove_process(process_id, force=False)

        # 2. Prozess‑Lebensprüfung (nur Warnung, keine Unterbrechung)
        if process.poll() is not None:
            logger.warning(
                f"⚠️ Prozess {process.pid} (ID {process_id}) scheint bereits beendet zu sein "
                f"(Exit-Code {process.poll()}). Registrierung trotzdem fortgesetzt."
            )
        if yt_process and yt_process.poll() is not None:
            logger.warning(
                f"⚠️ yt‑dlp-Prozess {yt_process.pid} (ID {process_id}) scheint bereits beendet zu sein "
                f"(Exit-Code {yt_process.poll()})."
            )

        # 3. Plattform‑ und Header‑Erkennung erweitern
        url_lower = url.lower()
        platform = "Unknown"
        headers_used = False

        if "youtube.com" in url_lower or "youtu.be" in url_lower:
            platform = "YouTube"
            headers_used = True
        elif "twitch.tv" in url_lower:
            platform = "Twitch"
            headers_used = True
        elif "tiktok.com" in url_lower:
            platform = "TikTok"
            headers_used = True
        elif "facebook.com" in url_lower or "fb.watch" in url_lower:
            platform = "Facebook"
            headers_used = True
        elif "kick.com" in url_lower:
            platform = "Kick"
            headers_used = True
        elif "rumble.com" in url_lower:
            platform = "Rumble"
            headers_used = True
        elif "dailymotion.com" in url_lower:
            platform = "Dailymotion"
        elif "vimeo.com" in url_lower:
            platform = "Vimeo"
        elif "twitter.com" in url_lower or "x.com" in url_lower:
            platform = "Twitter/X"
        elif url_lower.startswith("file://"):
            platform = "Local File"
        elif ".m3u8" in url_lower:
            platform = "HLS Stream"
        elif ".mpd" in url_lower:
            platform = "DASH Stream"
        elif url_lower.startswith(("http://", "https://")):
            platform = "HTTP Stream"

        # 4. PID‑Tracking vorbereiten
        pid_entries = [(process.pid, process_id)]
        if yt_process:
            pid_entries.append((yt_process.pid, f"{process_id}_yt"))

        with self._lock:
            for pid, pid_key in pid_entries:
                if pid is None:
                    continue
                if pid in self._pid_tracking:
                    logger.warning(
                        f"⚠️ PID {pid} bereits in _pid_tracking (Prozess-ID "
                        f"{self._pid_tracking[pid]['process_id']}) – überschreibe."
                    )
                    del self._pid_tracking[pid]

            # 5. _ProcessInfo‑Objekt erstellen
            pinfo = self._ProcessInfo(
                process_id=process_id,
                process=process,
                output_queue=output_queue,
                url=url,
                platform=platform,
                is_live=is_live,
                headers_used=headers_used,
                yt_process=yt_process,
                pipe_mode=pipe_mode,
            )
            self._processes[process_id] = pinfo

            # 6. PID‑Tracking befüllen
            url_short = url[:100] + ("..." if len(url) > 100 else "")
            self._pid_tracking[process.pid] = {
                "process_id": process_id,
                "start_time": pinfo.start_time,
                "url": url_short,
                "platform": platform,
                "is_live": is_live,
                "pipe_mode": pipe_mode,
            }
            if yt_process and yt_process.pid is not None:
                self._pid_tracking[yt_process.pid] = {
                    "process_id": f"{process_id}_yt",
                    "start_time": pinfo.start_time,
                    "url": url_short,
                    "platform": platform,
                    "is_live": is_live,
                    "pipe_mode": pipe_mode,
                }

            # 7. Lesethread starten
            self._start_read_thread(pinfo)

            # 8. Stderr‑Thread starten
            try:
                self._start_stderr_thread(pinfo)
                if pinfo.stderr_thread is None:
                    logger.warning(
                        f"⚠️ stderr-Thread für {process_id} (PID {process.pid}) wurde nicht gestartet."
                    )
            except Exception as e:
                logger.error(
                    f"❌ Fehler beim Starten des stderr-Threads für {process_id} (PID {process.pid}): {e}",
                    exc_info=True,
                )

            # 9. Abschließendes Logging
            logger.info(
                f"📊 Process registered: {process_id} (PID: {process.pid}) "
                f"[pipe_mode={pipe_mode}, platform={platform}, headers={headers_used}]"
            )
            if DEBUG_LEVEL >= 3:
                log_debug("ffmpeg", f"  ↪ Full URL: {url}")
                log_debug(
                    "ffmpeg",
                    f"  ↪ Process args: {process.args if hasattr(process, 'args') else 'N/A'}",
                )

    def _start_read_thread(self, pinfo: "_ProcessInfo") -> None:
        """Startet einen dedizierten Thread, der vom Prozess liest und in eine Queue schreibt."""
        pinfo.read_queue = queue.Queue(maxsize=10)
        pinfo.read_stop = threading.Event()

        def reader():
            logger.debug(
                f"[FFmpegManager] Reader thread started for {pinfo.process_id}"
            )
            try:
                while not pinfo.read_stop.is_set() and pinfo.process.poll() is None:
                    try:
                        data = pinfo.process.stdout.read(self.READ_BLOCK_SIZE)
                        if pinfo.read_queue is not None:
                            pinfo.read_queue.put(data)
                        else:
                            logger.debug(
                                f"[FFmpegManager] Reader thread {pinfo.process_id}: read_queue already None, discarding data"
                            )
                            break
                        if not data:
                            break
                    except (BrokenPipeError, BlockingIOError):
                        if pinfo.read_queue is not None:
                            pinfo.read_queue.put(b"")
                        break
                    except Exception as e:
                        logger.debug(
                            f"[FFmpegManager] Reader thread error for {pinfo.process_id}: {e}"
                        )
                        if pinfo.read_queue is not None:
                            pinfo.read_queue.put(None)
                        break
            finally:
                if pinfo.read_queue is not None:
                    pinfo.read_queue.put(None)  # Signal für Ende
                logger.debug(
                    f"[FFmpegManager] Reader thread finished for {pinfo.process_id}"
                )

        # Thread als Daemon starten – wichtig für sauberen Shutdown
        pinfo.read_thread = threading.Thread(
            target=reader, daemon=True, name=f"FFmpegRead-{pinfo.process_id}"
        )
        pinfo.read_thread.start()
        logger.debug(
            f"[FFmpegManager] Reader thread started for {pinfo.process_id} (daemon)"
        )

    def _stop_read_thread(self, pinfo: "_ProcessInfo") -> None:
        """
        Stoppt den Lesethread (setzt Event, schließt Pipe) und wartet auf Thread-Ende.
        Da der Thread als Daemon läuft, ist das Warten optional – wir versuchen es dennoch.
        """
        logger.debug(f"[FFmpegManager] _stop_read_thread: {pinfo.process_id}")

        # 1. Pipe schließen, um blockierenden read() zu beenden
        if pinfo.process and pinfo.process.stdout and not pinfo.process.stdout.closed:
            try:
                pinfo.process.stdout.close()
                logger.debug(
                    f"[FFmpegManager] Closed stdout for {pinfo.process_id} in stop_read_thread"
                )
            except Exception as e:
                logger.debug(
                    f"[FFmpegManager] Error closing stdout for {pinfo.process_id}: {e}"
                )

        # 2. Stop-Event setzen (optional, da Thread die Pipe-Schließung bemerkt)
        if pinfo.read_stop:
            pinfo.read_stop.set()
            logger.debug(f"[FFmpegManager] read_stop event set for {pinfo.process_id}")

        # Kurze Pause, damit der Thread die Pipe-Schließung bemerkt
        time.sleep(0.05)

        # 3. Warten auf den Thread (max. 2 Sekunden) – nur wenn er noch lebt
        if pinfo.read_thread and pinfo.read_thread.is_alive():
            logger.debug(
                f"[FFmpegManager] Joining read_thread for {pinfo.process_id}..."
            )
            pinfo.read_thread.join(timeout=3.0)
            if pinfo.read_thread.is_alive():
                # Thread ist bereits Daemon, also kein Problem – nur Log
                logger.debug(
                    f"[FFmpegManager] read_thread for {pinfo.process_id} still alive after timeout (daemon, will exit with process)"
                )
            else:
                logger.debug(
                    f"[FFmpegManager] read_thread joined for {pinfo.process_id}"
                )

        # 4. Referenzen löschen
        pinfo.read_thread = None
        pinfo.read_queue = None
        pinfo.read_stop = None
        pinfo.read_buffer = b""

        logger.debug(f"[FFmpegManager] _stop_read_thread done for {pinfo.process_id}")

    def _start_stderr_thread(self, pinfo: "_ProcessInfo") -> None:
        rate_limiter = self._RateLimiter(max_messages=10, period=60.0)

        def stderr_worker() -> None:
            process = pinfo.process
            stop = pinfo.stop_stderr
            if DEBUG_LEVEL < 3:
                ignore_patterns = [
                    "Connection reset by peer",
                    "partial file",
                    "Error in the pull function",
                    "packet corrupt",
                    "demuxing error",
                    "Input/output error",
                    "End of file",
                ]
            else:
                ignore_patterns = []

            reconnect_counter = 0
            last_reconnect_time = 0.0
            last_line = ""

            while not stop.is_set():
                if process.poll() is not None:
                    break
                try:
                    line = process.stderr.readline()
                    if not line:
                        time.sleep(0.1)
                        continue
                    line = line.decode("utf-8", errors="ignore").strip()
                    if not line:
                        continue

                    pinfo.last_stderr_line = line

                    is_ignored = any(pat in line for pat in ignore_patterns)

                    if "Will reconnect" in line and "error=End of file" in line:
                        now = time.time()
                        if (
                            now - last_reconnect_time
                            < self.STALLED_RECONNECT_LOG_INTERVAL
                        ):
                            reconnect_counter += 1
                            last_line = line
                            continue
                        else:
                            if reconnect_counter > 0:
                                if rate_limiter.allow():
                                    logger.debug(
                                        f"FFmpeg stderr ({pinfo.process_id}): "
                                        f"{reconnect_counter+1} reconnect messages suppressed, last: {last_line}"
                                    )
                            reconnect_counter = 0
                            last_reconnect_time = now
                            if rate_limiter.allow():
                                logger.debug(
                                    f"FFmpeg stderr ({pinfo.process_id}): {line}"
                                )
                            last_line = line
                        continue
                    else:
                        if reconnect_counter > 0:
                            if rate_limiter.allow():
                                logger.debug(
                                    f"FFmpeg stderr ({pinfo.process_id}): "
                                    f"{reconnect_counter+1} reconnect messages suppressed, last: {last_line}"
                                )
                            reconnect_counter = 0
                            last_reconnect_time = 0.0
                        if DEBUG_LEVEL >= 3:
                            if rate_limiter.allow():
                                logger.debug(
                                    f"FFmpeg stderr ({pinfo.process_id}): {line}"
                                )
                        elif not is_ignored and rate_limiter.allow():
                            logger.debug(f"FFmpeg stderr ({pinfo.process_id}): {line}")

                    if "Error" in line or "error" in line:
                        pinfo.error_count += 1
                        pinfo.last_error = line

                except (OSError, ValueError):
                    break
                except Exception as e:
                    logger.debug(f"stderr worker error: {e}")
                    break

            if reconnect_counter > 0:
                if rate_limiter.allow():
                    logger.debug(
                        f"FFmpeg stderr ({pinfo.process_id}): "
                        f"{reconnect_counter+1} reconnect messages suppressed, last: {last_line}"
                    )
            logger.debug(f"stderr thread stopped for {pinfo.process_id}")

        thread = threading.Thread(
            target=stderr_worker, daemon=True, name=f"FFmpegStderr-{pinfo.process_id}"
        )
        thread.start()
        pinfo.stderr_thread = thread

    def _stop_stderr_thread(self, pinfo: "_ProcessInfo") -> None:
        """Stoppt den Stderr-Thread (setzt Event, schließt Pipe) und wartet auf Thread-Ende."""
        thread = pinfo.stderr_thread
        if thread is None:
            logger.debug(
                f"[FFmpegManager] _stop_stderr_thread: {pinfo.process_id} - no thread"
            )
            return

        logger.debug(
            f"[FFmpegManager] _stop_stderr_thread: {pinfo.process_id}, thread={thread}"
        )

        try:
            if thread.is_alive():
                pinfo.stop_stderr.set()
                logger.debug(
                    f"[FFmpegManager] stop_stderr event set for {pinfo.process_id}"
                )

                if (
                    pinfo.process
                    and pinfo.process.stderr
                    and not pinfo.process.stderr.closed
                ):
                    try:
                        pinfo.process.stderr.close()
                        logger.debug(
                            f"[FFmpegManager] Closed stderr for {pinfo.process_id}"
                        )
                    except Exception as e:
                        logger.debug(
                            f"[FFmpegManager] Error closing stderr for {pinfo.process_id}: {e}"
                        )

                logger.debug(
                    f"[FFmpegManager] Joining stderr_thread for {pinfo.process_id}..."
                )
                thread.join(timeout=1.0)
                if thread.is_alive():
                    logger.warning(
                        f"[FFmpegManager] stderr_thread for {pinfo.process_id} did not terminate within timeout"
                    )
                else:
                    logger.debug(
                        f"[FFmpegManager] stderr_thread joined for {pinfo.process_id}"
                    )
            else:
                logger.debug(
                    f"[FFmpegManager] stderr_thread for {pinfo.process_id} already dead"
                )
        except Exception as e:
            logger.warning(
                f"[FFmpegManager] _stop_stderr_thread error for {pinfo.process_id}: {e}"
            )
        finally:
            pinfo.stderr_thread = None
            logger.debug(
                f"[FFmpegManager] _stop_stderr_thread done for {pinfo.process_id}"
            )

    def _read_stderr(self, process: subprocess.Popen) -> str:
        try:
            if process.stderr:
                if DEBUG_LEVEL >= 3:
                    data = process.stderr.read().decode("utf-8", errors="ignore")
                    if data:
                        log_debug("ffmpeg", f"FFmpeg stderr (full):\n{data}")
                    return data
                else:
                    data = process.stderr.read(300).decode("utf-8", errors="ignore")
                    if data:
                        log_debug("ffmpeg", f"FFmpeg stderr (first 300 chars): {data}")
                    return data
        except Exception:
            pass
        return ""

    def _terminate_process(self, proc: subprocess.Popen) -> bool:
        """Beendet einen Prozess und alle seine Kindprozesse (robust)."""

        def stats_callback(mode: str) -> None:
            with self._stats_lock:
                if mode in ("psutil", "psutil_kill"):
                    self._stats["process_terminations_psutil"] += 1
                elif mode == "terminate":
                    self._stats["process_terminations_graceful"] += 1
                elif mode == "kill":
                    self._stats["process_terminations_kill"] += 1
                elif mode == "failed":
                    self._stats["process_terminations_failed"] += 1

        return PlatformUtils.terminate_process(
            proc,
            child_terminate_timeout=self.PSUTIL_CHILD_TERMINATE_TIMEOUT,
            child_kill_wait=self.PSUTIL_CHILD_KILL_WAIT,
            parent_terminate_timeout=self.PSUTIL_PARENT_TERMINATE_TIMEOUT,
            parent_kill_wait=self.PSUTIL_PARENT_KILL_WAIT,
            fallback_terminate_timeout=self.SUBPROC_TERMINATE_TIMEOUT,
            fallback_kill_wait=self.SUBPROC_KILL_WAIT,
            stats_callback=stats_callback,
        )

    def _remove_process(self, process_id: str, force: bool = False) -> bool:
        """
        Entfernt einen Prozess aus der Verwaltung und beendet ihn.
        Thread-sicher, mit optionaler erzwungener Terminierung.

        Args:
            process_id: Eindeutige Kennung des Prozesses.
            force: Wenn True, wird der Prozess sofort gekillt (kein normales Terminieren).

        Returns:
            True, wenn der Prozess erfolgreich entfernt wurde, sonst False.
        """
        logger.debug(f"  _remove_process called for {process_id} (force={force})")

        # Merker, ob der Slot am Ende freigegeben werden muss
        skip_release = False

        try:
            # 1. Prozess-Info holen und als "entfernend" markieren, um doppelte Aufrufe zu verhindern
            with self._lock:
                if process_id not in self._processes:
                    logger.debug(
                        f"  _remove_process: process {process_id} not found, returning False"
                    )
                    return False
                pinfo = self._processes[process_id]
                if pinfo._removing:
                    logger.debug(
                        f"  Process {process_id} is already being removed, skipping."
                    )
                    return False
                pinfo._removing = True
                skip_release = getattr(pinfo, "_skip_semaphore_release", False)
                logger.debug(
                    f"  _remove_process: marked as removing, skip_release={skip_release}"
                )

            # 2. Threads stoppen (Lesen, Stderr, yt-dlp)
            logger.debug(f"  _remove_process: stopping threads for {process_id}")
            self._stop_read_thread(pinfo)
            self._stop_stderr_thread(pinfo)

            # yt-dlp stderr-Thread bereinigen (mit join)
            yt_thread = getattr(pinfo, "yt_stderr_thread", None)
            if yt_thread is not None:
                logger.debug(
                    f"  _remove_process: cleaning yt_stderr_thread for {process_id}"
                )
                yt_stop = getattr(pinfo, "yt_stderr_stop", None)
                if yt_stop:
                    yt_stop.set()
                    if DEBUG_LEVEL >= 3:
                        log_debug("ffmpeg", f"yt_stop event set for {process_id}")
                if (
                    pinfo.yt_process
                    and pinfo.yt_process.stderr
                    and not pinfo.yt_process.stderr.closed
                ):
                    try:
                        pinfo.yt_process.stderr.close()
                        if DEBUG_LEVEL >= 3:
                            log_debug(
                                "ffmpeg", f"closed yt_process stderr for {process_id}"
                            )
                    except Exception as e:
                        if DEBUG_LEVEL >= 3:
                            log_debug("ffmpeg", f"error closing yt_process stderr: {e}")

                if yt_thread.is_alive():
                    if DEBUG_LEVEL >= 3:
                        log_debug("ffmpeg", f"joining yt_stderr_thread for {process_id}")
                    yt_thread.join(timeout=2.0)
                    if yt_thread.is_alive():
                        logger.warning(
                            f"  _remove_process: yt_stderr_thread for {process_id} did not terminate within timeout"
                        )
                    else:
                        if DEBUG_LEVEL >= 3:
                            log_debug("ffmpeg", "yt_stderr_thread joined")
                else:
                    if DEBUG_LEVEL >= 3:
                        log_debug("ffmpeg", "yt_stderr_thread already dead")

                pinfo.yt_stderr_thread = None
                pinfo.yt_stderr_stop = None
                if DEBUG_LEVEL >= 3:
                    log_debug("ffmpeg", f"yt_stderr_thread cleared for {process_id}")

            # 3. Stderr-Hinweis für Fehlerbehandlung lesen (nur bei Bedarf)
            stderr_hint = ""
            if not force:
                try:
                    if pinfo.process.stderr and not pinfo.process.stderr.closed:
                        if DEBUG_LEVEL >= 3:
                            stderr_hint = pinfo.process.stderr.read().decode(
                                "utf-8", errors="ignore"
                            )
                            logger.debug(
                                f"  _remove_process: read stderr hint ({len(stderr_hint)} chars)"
                            )
                        else:
                            stderr_hint = pinfo.process.stderr.read(200).decode(
                                "utf-8", errors="ignore"
                            )
                            if DEBUG_LEVEL >= 3:
                                logger.debug(
                                    "  _remove_process: read stderr hint (truncated)"
                                )
                except Exception as e:
                    if DEBUG_LEVEL >= 3:
                        log_exception(
                            "ffmpeg",
                            "Error reading stderr in _remove_process",
                            e,
                            level="debug",
                        )
                    else:
                        logger.debug(f"  _remove_process: error reading stderr: {e}")

            # 4. Aus der Registry entfernen (vor dem Terminieren, um weitere Zugriffe zu verhindern)
            with self._lock:
                if process_id not in self._processes:
                    logger.debug(
                        f"  _remove_process: process {process_id} disappeared before lock, returning False"
                    )
                    return False
                process = pinfo.process
                yt_process = pinfo.yt_process
                del self._processes[process_id]
                if pinfo.process.pid in self._pid_tracking:
                    del self._pid_tracking[pinfo.process.pid]
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "ffmpeg", f"removed PID {pinfo.process.pid} from tracking"
                        )
                if pinfo.yt_process and pinfo.yt_process.pid in self._pid_tracking:
                    del self._pid_tracking[pinfo.yt_process.pid]
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "ffmpeg", f"removed yt PID {pinfo.yt_process.pid} from tracking"
                        )
                logger.debug(
                    f"  _remove_process: removed from registry, process PID={process.pid if process else None}, yt PID={yt_process.pid if yt_process else None}"
                )

            # 5. Prozesse terminieren
            success = True
            try:
                if force:
                    logger.debug("  _remove_process: force mode, killing processes")
                    if yt_process and yt_process.poll() is None:
                        logger.debug(
                            f"  Force‑killing yt_process {process_id} (PID {yt_process.pid})"
                        )
                        yt_process.kill()
                        if DEBUG_LEVEL >= 3:
                            log_debug(
                                "ffmpeg", f"yt_process kill sent, poll={yt_process.poll()}"
                            )
                    if process and process.poll() is None:
                        logger.debug(
                            f"  Force‑killing process {process_id} (PID {process.pid})"
                        )
                        process.kill()
                        if DEBUG_LEVEL >= 3:
                            log_debug("ffmpeg", f"process kill sent, poll={process.poll()}")
                else:
                    logger.debug("  _remove_process: normal mode, terminating processes")
                    if yt_process and yt_process.poll() is None:
                        logger.debug(
                            f"  Terminating yt_process {process_id} (PID {yt_process.pid})"
                        )
                        self._terminate_process(yt_process)
                        if DEBUG_LEVEL >= 3:
                            log_debug("ffmpeg", "yt_process termination done")
                    if process and process.poll() is None:
                        logger.debug(
                            f"  Terminating process {process_id} (PID {process.pid})"
                        )
                        success = self._terminate_process(process)
                        if DEBUG_LEVEL >= 3:
                            log_debug("ffmpeg", f"process termination success={success}")

                # Pipes schließen
                for pipe_name in ("stdout", "stderr", "stdin"):
                    pipe = getattr(process, pipe_name, None)
                    if pipe and not pipe.closed:
                        try:
                            pipe.close()
                            if DEBUG_LEVEL >= 3:
                                log_debug(
                                    "ffmpeg", f"closed {pipe_name} pipe for {process_id}"
                                )
                        except Exception as e:
                            if DEBUG_LEVEL >= 3:
                                log_exception(
                                    "ffmpeg",
                                    f"Error closing {pipe_name} pipe",
                                    e,
                                    level="debug",
                                )
                            else:
                                logger.debug(
                                    f"  _remove_process: error closing {pipe_name} pipe: {e}"
                                )

                # Crash-Callback aufrufen (nur wenn vorhanden und nicht erzwungen)
                if self._on_process_crash is not None and not success and not force:
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "ffmpeg",
                            f"process crash detected, calling callback for {process_id}",
                        )
                    try:
                        self._on_process_crash(process_id, stderr_hint)
                    except Exception as e:
                        log_exception("ffmpeg", "Crash callback error", e, level="error")
                        if DEBUG_LEVEL >= 3:
                            log_debug("ffmpeg", f"crash callback error: {e}")

            except Exception as e:
                logger.exception(
                    f"  _remove_process: unexpected error during process termination: {e}"
                )
                success = False

            finally:
                # Semaphore freigeben, falls nicht übersprungen
                if not skip_release:
                    self._release_slot()
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "ffmpeg", f"Semaphore released, now value={self._active_slots}"
                        )
                    else:
                        logger.debug(
                            f"  _remove_process: semaphore released, active slots now {self._active_slots}"
                        )
                else:
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "ffmpeg",
                            f"Semaphore release skipped for {process_id} (refresh in progress)",
                        )
                    else:
                        logger.debug("  _remove_process: semaphore release skipped")

            logger.debug(f"  _remove_process completed for {process_id}, success={success}")
            return success

        except Exception as e:
            # Falls eine Exception vor dem Setzen von skip_release auftritt,
            # muss der Slot dennoch freigegeben werden.
            logger.exception(f"  _remove_process: outer exception caught: {e}")
            if not skip_release:
                self._release_slot()
                logger.debug("  _remove_process: emergency slot release after outer exception")
            return False

    def cleanup_stale_processes(self) -> None:
        stale_pids = []
        with self._lock:
            for pid, pinfo in list(self._processes.items()):
                if pinfo.process is not None and pinfo.process.poll() is not None:
                    stale_pids.append(pid)

        for pid in stale_pids:
            logger.info(f"🧹 Cleaning stale process: {pid}")
            removed = self._remove_process(pid)
            if removed:
                logger.info(f"✅ Stale process {pid} removed")

    def _cleanup_worker(self) -> None:
        """
        Periodische Bereinigung von toten Prozessen.
        Wartet auf das Stop-Event oder das Intervall.
        """
        log_debug("ffmpeg", "Cleanup worker thread started")
        while not self._cleanup_stop_event.is_set():
            # Warte auf Stop-Event oder Intervall
            if self._cleanup_stop_event.wait(self.CLEANUP_INTERVAL):
                log_debug("ffmpeg", "Cleanup worker: stop event received, exiting")
                break
            if self._global_shutdown:
                log_debug("ffmpeg", "Cleanup worker: global shutdown, exiting")
                break
            log_debug("ffmpeg", "Cleanup worker: performing periodic cleanup")
            try:
                self.cleanup_stale_processes()
                # _read_times zurücksetzen, wenn alle Prozesse lange inaktiv waren
                now = time.time()
                with self._lock:
                    max_activity = max(
                        (p.last_activity for p in self._processes.values()), default=0
                    )
                if max_activity > 0 and now - max_activity > 600:
                    self._read_times.clear()
                    log_debug("ffmpeg", "Cleared _read_times due to inactivity")
            except Exception as e:
                logger.warning(f"Fehler in cleanup worker: {e}", exc_info=True)
        log_debug("ffmpeg", "Cleanup worker thread terminated")

    def _read_audio_data_with_timeout(
        self, process_id: str, size: int, timeout: float
    ) -> Optional[bytes]:
        """
        Liest Audiodaten mit einem kurzen Timeout (für Tests).
        Nutzt den optionalen timeout-Parameter von read_audio_data, falls vorhanden,
        sonst temporäre Änderung von PROCESS_TIMEOUT (threadsafe durch Lock).
        """
        with self._lock:
            if process_id not in self._processes:
                return None
            # Prüfen, ob read_audio_data einen timeout-Parameter unterstützt
            import inspect

            sig = inspect.signature(self.read_audio_data)
            if "timeout" in sig.parameters:
                return self.read_audio_data(process_id, size, timeout=timeout)
            else:
                # Fallback: temporäre Änderung (nicht threadsafe, aber für diesen kurzen Test akzeptabel)
                original = self.PROCESS_TIMEOUT
                try:
                    self.PROCESS_TIMEOUT = timeout
                    return self.read_audio_data(process_id, size)
                finally:
                    self.PROCESS_TIMEOUT = original

    def refresh_and_restart(
        self,
        process_id: str,
        video_url: str,
        detected_language: Optional[str] = None,
        max_attempts: Optional[int] = None,
    ) -> Optional[subprocess.Popen]:
        """
        Versucht, einen Stream zu erneuern (neue Audio‑URL, neuer FFmpeg‑Prozess).
        Behebt das Semaphore‑Leak, gibt den Slot des alten Prozesses vor dem Neustart frei,
        und enthält ausführliches Debug‑Logging, asynchronen Test, Jitter, Gesamt‑Timeout,
        Zustandsmaschine, Event‑Bus‑Meldungen und Caching.

        Die Diagnose der letzten Refresh‑Operation wird in `self._refresh_diagnoses[process_id]`
        gespeichert (Dict mit Feldern: success, attempts_used, failure_reason, new_pid,
        used_cache, fallback_used, state_history, total_duration_ms).

        Args:
            process_id: Eindeutige Kennung des zu ersetzenden Prozesses.
            video_url: Ursprüngliche Video‑URL.
            detected_language: Optional erkannte Sprache.
            max_attempts: Maximale Anzahl Wiederholungsversuche.

        Returns:
            Neuer subprocess.Popen bei Erfolg, sonst None.
        """

        class RefreshState(Enum):
            INIT = 0
            STOPPING = 1
            EXTRACTING = 2
            STARTING = 3
            TESTING = 4
            SUCCESS = 5
            FAILED = 6

        if max_attempts is None:
            max_attempts = self.MAX_REFRESH_ATTEMPTS

        TOTAL_REFRESH_TIMEOUT = getattr(self, "REFRESH_TOTAL_TIMEOUT", 90.0)
        start_time = time.time()

        logger.info(
            f"🔄 Attempting to refresh and restart FFmpeg for {process_id} (max_attempts={max_attempts})"
        )
        if DEBUG_LEVEL >= 3:
            log_debug(
                "ffmpeg",
                f"refresh_and_restart called with process_id={process_id}, video_url={video_url[:80]}...",
            )

        with self._stats_lock:
            self._stats["reconnect_attempts"] += 1

        # Diagnose pro Prozess-ID speichern (thread-sicher)
        if not hasattr(self, "_refresh_diagnoses"):
            self._refresh_diagnoses = {}
        diagnosis = {
            "success": False,
            "attempts_used": 0,
            "failure_reason": "",
            "new_pid": None,
            "used_cache": False,
            "fallback_used": False,
            "state_history": [],
            "total_duration_ms": 0.0,
        }

        # ========== 1. Slot des alten Prozesses freigeben ==========
        with self._lock:
            if process_id not in self._processes:
                logger.warning(f"Process {process_id} not found, cannot refresh")
                diagnosis["failure_reason"] = "process_not_found"
                self._refresh_diagnoses[process_id] = diagnosis
                return None
            pinfo = self._processes[process_id]
            if not pinfo._skip_semaphore_release:
                self._release_slot()
                pinfo._skip_semaphore_release = True
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "ffmpeg",
                        f"Released slot for old process {process_id}, active slots now {self._active_slots}",
                    )

        if hasattr(self, "event_bus") and self.event_bus:
            self.event_bus.emit(
                "refresh_started",
                {"process_id": process_id, "max_attempts": max_attempts},
            )

        # ========== 2. Cache für Audio-URL (dauerhaft) ==========
        url_cache = getattr(self, "_audio_url_cache", None)
        if url_cache is None:
            from collections import OrderedDict

            url_cache = OrderedDict()
            url_cache.maxsize = 5
            self._audio_url_cache = url_cache

        executor = None
        new_process = None
        current_state = RefreshState.INIT

        try:
            for attempt in range(1, max_attempts + 1):
                if time.time() - start_time > TOTAL_REFRESH_TIMEOUT:
                    logger.error(
                        f"⏰ Total refresh timeout exceeded after {TOTAL_REFRESH_TIMEOUT}s for {process_id}"
                    )
                    diagnosis["failure_reason"] = "total_timeout"
                    current_state = RefreshState.FAILED
                    break

                current_state = RefreshState.STOPPING
                diagnosis["state_history"].append(f"attempt_{attempt}_stopping")
                if DEBUG_LEVEL >= 1:
                    logger.info(
                        f"  🔁 Refresh attempt {attempt}/{max_attempts} for {process_id}"
                    )

                if self.is_active(process_id):
                    self.stop_stream(process_id)
                    time.sleep(0.2)

                is_live, platform = self._detect_stream_type(video_url)
                is_youtube = (
                    "youtube.com" in video_url.lower()
                    or "youtu.be" in video_url.lower()
                )
                if is_youtube and not is_live:
                    is_live = self._check_youtube_live_by_metadata(video_url)
                use_pipe = (is_youtube and is_live) or (
                    is_live and platform in self.PIPE_PREFERRED_PLATFORMS
                )

                audio_url = None
                force_refresh = is_live
                used_cache = False

                current_state = RefreshState.EXTRACTING
                diagnosis["state_history"].append(f"attempt_{attempt}_extracting")
                if not use_pipe:
                    cache_key = f"{video_url}_refresh"
                    cached_url = (
                        url_cache.get(cache_key)
                        if hasattr(url_cache, "get")
                        else url_cache.get(cache_key)
                    )
                    if cached_url and not force_refresh:
                        audio_url = cached_url
                        used_cache = True
                        if DEBUG_LEVEL >= 3:
                            log_debug(
                                "ffmpeg",
                                f"Using cached audio URL: {audio_url[:100]}...",
                            )
                    else:
                        new_url = self._extract_audio_url(
                            video_url, force_refresh=is_live, timeout=30.0
                        )
                        if not new_url:
                            base_wait = min(
                                self.REFRESH_RETRY_DELAY_MAX,
                                self.REFRESH_RETRY_DELAY_BASE * (2 ** (attempt - 1)),
                            )
                            jitter = random.uniform(0, base_wait * 0.3)
                            wait = base_wait + jitter
                            logger.warning(
                                f"  ❌ Refresh attempt {attempt} failed (no new URL). Retry in {wait:.1f}s"
                            )
                            time.sleep(wait)
                            continue
                        audio_url = new_url
                        url_cache[cache_key] = audio_url
                        # Cache-Größe begrenzen
                        if len(url_cache) > url_cache.maxsize:
                            url_cache.popitem(last=False)
                        if DEBUG_LEVEL >= 3:
                            log_debug(
                                "ffmpeg",
                                f"New audio URL obtained: {audio_url[:100]}...",
                            )
                else:
                    if DEBUG_LEVEL >= 3:
                        log_debug("ffmpeg", f"Attempt {attempt}: using pipe mode")

                current_state = RefreshState.STARTING
                diagnosis["state_history"].append(f"attempt_{attempt}_starting")
                try:
                    new_process = self.start_stream(
                        video_url=video_url,
                        output_queue=None,
                        process_id=process_id,
                        force_refresh_audio_url=force_refresh,
                        audio_url=audio_url,
                        seek_seconds=None,
                        detected_language=detected_language,
                    )
                except Exception as e:
                    logger.error(f"  ❌ Exception in start_stream: {e}", exc_info=True)
                    diagnosis["failure_reason"] = f"start_stream_exception: {e}"
                    new_process = None

                if new_process is not None:
                    logger.info(
                        f"  ✅ New FFmpeg process started (PID: {new_process.pid})"
                    )
                    current_state = RefreshState.TESTING
                    diagnosis["state_history"].append(f"attempt_{attempt}_testing")

                    # Executor nur bei Bedarf erstellen
                    if executor is None:
                        executor = ThreadPoolExecutor(
                            max_workers=1, thread_name_prefix="RefreshTest"
                        )

                    # Verwende die Hilfsmethode mit kurzem Timeout (0.5 Sekunden Lesezeit)
                    future = executor.submit(
                        self._read_audio_data_with_timeout, process_id, 1024, 0.5
                    )
                    data_received = False
                    try:
                        test_data = future.result(
                            timeout=2.0
                        )  # 2 Sekunden auf Ergebnis warten
                        if test_data is not None and len(test_data) > 0:
                            data_received = True
                            logger.info(
                                "  ✅ Data received asynchronously. Refresh successful."
                            )
                        else:
                            if DEBUG_LEVEL >= 3:
                                log_debug("ffmpeg", "Async test: no data received")
                    except FutureTimeout:
                        logger.warning("  ⚠️ Async test timed out after 2 seconds")
                        future.cancel()
                    except Exception as e:
                        logger.warning(f"  ⚠️ Async test exception: {e}")

                    if data_received:
                        with self._stats_lock:
                            self._stats["reconnect_success"] += 1
                        with self._lock:
                            if process_id in self._processes:
                                self._processes[process_id]._skip_semaphore_release = (
                                    False
                                )
                        diagnosis["success"] = True
                        diagnosis["attempts_used"] = attempt
                        diagnosis["new_pid"] = new_process.pid
                        diagnosis["used_cache"] = used_cache
                        diagnosis["fallback_used"] = use_pipe
                        current_state = RefreshState.SUCCESS
                        if hasattr(self, "event_bus") and self.event_bus:
                            self.event_bus.emit(
                                "refresh_success",
                                {"process_id": process_id, "attempts": attempt},
                            )
                        break
                    else:
                        logger.warning(
                            "  ⚠️ New process started but no data received, retrying..."
                        )
                        self.stop_stream(process_id)
                        # Backoff vor nächstem Versuch
                        base_wait = min(
                            self.REFRESH_RETRY_DELAY_MAX,
                            self.REFRESH_RETRY_DELAY_BASE * (2 ** (attempt - 1)),
                        )
                        jitter = random.uniform(0, base_wait * 0.3)
                        wait = base_wait + jitter
                        time.sleep(wait)
                        continue
                else:
                    base_wait = min(
                        self.REFRESH_RETRY_DELAY_MAX,
                        self.REFRESH_RETRY_DELAY_BASE * (2 ** (attempt - 1)),
                    )
                    jitter = random.uniform(0, base_wait * 0.3)
                    wait = base_wait + jitter
                    logger.warning(
                        f"  ❌ Refresh attempt {attempt} failed (start_stream returned None). Retry in {wait:.1f}s"
                    )
                    time.sleep(wait)

            if current_state != RefreshState.SUCCESS:
                with self._stats_lock:
                    self._stats["reconnect_failures"] += 1
                logger.error(
                    f"❌ Failed to refresh and restart after {max_attempts} attempts for {process_id}"
                )
                diagnosis["failure_reason"] = (
                    diagnosis["failure_reason"] or "max_attempts_exceeded"
                )
                diagnosis["attempts_used"] = max_attempts
                if hasattr(self, "event_bus") and self.event_bus:
                    self.event_bus.emit(
                        "refresh_failed",
                        {
                            "process_id": process_id,
                            "reason": diagnosis["failure_reason"],
                        },
                    )

        finally:
            if executor:
                executor.shutdown(wait=False)  # kein timeout-Parameter, sofort zurück
            # Flag zurücksetzen, falls Prozess noch existiert
            with self._lock:
                if process_id in self._processes:
                    self._processes[process_id]._skip_semaphore_release = False

        diagnosis["total_duration_ms"] = (time.time() - start_time) * 1000.0
        diagnosis["state_history"] = diagnosis["state_history"][-20:]
        self._refresh_diagnoses[process_id] = diagnosis

        if DEBUG_LEVEL >= 3 and diagnosis["state_history"]:
            log_debug("ffmpeg", f"Refresh diagnosis for {process_id}: {diagnosis}")

        return new_process if diagnosis["success"] else None


# =============================================================================
# APPSETTINGS & ADVANCEDSETTINGS
# =============================================================================
@dataclass
class AppSettings:
    """
    Anwendungseinstellungen für Dragon Whisperer.

    Diese Klasse speichert benutzerspezifische Einstellungen wie die zuletzt
    verwendete URL, das Standardmodell, die Sprache (als ISO‑Code), das Layout, etc.
    Die Daten werden im plattformspezifischen Konfigurationsverzeichnis
    als JSON‑Datei gespeichert.

    Attributes:
        last_url: Zuletzt verwendete URL (leerer String, falls nicht vorhanden).
        default_model: Standard-Whisper-Modell (z.B. 'large-v3').
        default_language: Standard-Quellsprache als ISO-Code (z.B. 'de', 'auto').
        layout_mode: GUI-Layout ('vertical' oder 'horizontal').
        recent_urls: Liste der zuletzt verwendeten URLs (max. 10).
        enable_plugins: Ob Plugins aktiviert sind.
        export_format: Standard-Exportformat ('txt', 'srt', 'vtt', 'json', 'docx').
        auto_save_on_completion: Automatisches Speichern nach Abschluss.
        theme: GUI-Theme ('dark', 'light', 'pastel', 'system', 'highcontrast').
        use_browser_cookies: Browser-Cookies für YouTube/Twitch nutzen.
        cookies_notice_shown: Ob der Cookie-Hinweis bereits angezeigt wurde.
        cookies_browser: Name des Browsers für Cookie-Extraktion (z.B. 'firefox', 'chrome').
    """

    last_url: str = ""
    default_model: str = "large-v3"
    default_language: str = "auto"          # <-- Jetzt ISO‑Code!
    layout_mode: str = "horizontal"
    recent_urls: List[str] = field(default_factory=list)
    enable_plugins: bool = True
    export_format: str = "srt"
    auto_save_on_completion: bool = False
    theme: str = "dark"
    use_browser_cookies: bool = True
    cookies_notice_shown: bool = False
    cookies_browser: str = "firefox"

    # -------------------------------------------------------------------------
    # Hilfsmethoden für Sprachcodes ↔ Namen
    # -------------------------------------------------------------------------
    def get_language_name(self) -> str:
        """
        Gibt den lesbaren Namen der aktuellen Standardsprache zurück.
        Wird für die Anzeige in der GUI verwendet.
        """
        code = self.default_language
        if code in SUPPORTED_LANGUAGES:
            return SUPPORTED_LANGUAGES[code]
        # Fallback, falls Code unbekannt (sollte nicht vorkommen)
        logger.warning(f"Unbekannter Sprachcode '{code}', verwende 'Deutsch'")
        return "Deutsch"

    def set_language_by_name(self, name: str) -> None:
        """
        Setzt die Standardsprache anhand des lesbaren Namens.
        Wenn der Name nicht gefunden wird, bleibt der alte Code erhalten.
        """
        for code, lang_name in SUPPORTED_LANGUAGES.items():
            if lang_name == name:
                self.default_language = code
                logger.debug(f"Sprache gesetzt: {name} -> Code '{code}'")
                return
        logger.warning(f"Sprachname '{name}' nicht gefunden – Sprache bleibt unverändert.")

    # -------------------------------------------------------------------------
    # Persistenz
    # -------------------------------------------------------------------------
    @classmethod
    def load_from_file(cls, filename: str = "dragon_settings.json") -> "AppSettings":
        """
        Lädt die Einstellungen aus einer JSON-Datei.
        Konvertiert automatisch alte Sprach‑Namen in ISO‑Codes.
        """
        try:
            config_dir = PlatformUtils.get_platform_config_dir()
            file_path = config_dir / filename
            if not file_path.exists():
                return cls()
            with open(file_path, "r", encoding="utf-8") as f:
                data = json.load(f)

            # Nur Felder übernehmen, die in der Dataclass existieren
            valid_fields = {f.name for f in fields(cls) if f.init}
            filtered = {k: v for k, v in data.items() if k in valid_fields}

            # Typkorrekturen
            if "recent_urls" in filtered and not isinstance(filtered["recent_urls"], list):
                filtered["recent_urls"] = []
            if "default_model" in filtered:
                model = filtered["default_model"]
                if model not in Config.WHISPER_MODELS and model != "large-v3":
                    filtered["default_model"] = "large-v3"

            # ========== Sprach‑Konvertierung (Name → Code) ==========
            if "default_language" in filtered:
                lang_value = filtered["default_language"]
                # Prüfen, ob es bereits ein gültiger Code ist
                if lang_value in SUPPORTED_LANGUAGES:
                    # Schon Code – nichts tun
                    pass
                else:
                    # Es könnte ein Name sein – versuche Mapping
                    found = False
                    for code, name in SUPPORTED_LANGUAGES.items():
                        if name == lang_value:
                            filtered["default_language"] = code
                            found = True
                            logger.info(f"🔄 Sprache '{lang_value}' in Code '{code}' konvertiert")
                            break
                    if not found:
                        # Weder Code noch Name – auf Standard setzen
                        logger.warning(
                            f"⚠️ Unbekannte Sprache '{lang_value}' – setze auf 'auto'"
                        )
                        filtered["default_language"] = "auto"
            # =========================================================

            # Leere recent_urls-Einträge filtern
            if "recent_urls" in filtered and isinstance(filtered["recent_urls"], list):
                filtered["recent_urls"] = [
                    u for u in filtered["recent_urls"] if u and u.strip()
                ]

            return cls(**filtered)

        except (json.JSONDecodeError, OSError, PermissionError) as e:
            logger.warning(f"⚠️ Konnte Einstellungen nicht laden: {e}")
            return cls()
        except Exception as e:
            logger.error(f"❌ Unerwarteter Fehler beim Laden der Einstellungen: {e}")
            return cls()

    def save_to_file(self, filename: str = "dragon_settings.json") -> bool:
        """
        Speichert die Einstellungen in einer JSON-Datei (atomarer Schreibvorgang).
        Die Sprache wird als ISO‑Code gespeichert.
        """
        try:
            config_dir = PlatformUtils.get_platform_config_dir()
            config_dir.mkdir(parents=True, exist_ok=True)
            file_path = config_dir / filename
            temp_path = file_path.with_suffix(".tmp")

            # Daten für JSON vorbereiten
            data = {
                "last_url": self.last_url,
                "default_model": self.default_model,
                "default_language": self.default_language,   # <-- Code wird gespeichert
                "layout_mode": self.layout_mode,
                "recent_urls": self.recent_urls[:10],
                "enable_plugins": self.enable_plugins,
                "export_format": self.export_format,
                "auto_save_on_completion": self.auto_save_on_completion,
                "theme": self.theme,
                "use_browser_cookies": self.use_browser_cookies,
                "cookies_notice_shown": self.cookies_notice_shown,
                "cookies_browser": self.cookies_browser,
            }

            # Atomarer Schreibvorgang
            with open(temp_path, "w", encoding="utf-8") as f:
                json.dump(data, f, indent=2, ensure_ascii=False)

            try:
                os.replace(temp_path, file_path)
            except AttributeError:
                temp_path.replace(file_path)
            except FileNotFoundError:
                config_dir.mkdir(parents=True, exist_ok=True)
                os.replace(temp_path, file_path)

            logger.debug(f"💾 Einstellungen gespeichert: {file_path}")
            return True
        except (OSError, PermissionError) as e:
            logger.warning(f"⚠️ Konnte Einstellungen nicht speichern: {e}")
            return False
        except Exception as e:
            logger.error(f"❌ Fehler beim Speichern der Einstellungen: {e}")
            return False

    # -------------------------------------------------------------------------
    # Weitere Methoden
    # -------------------------------------------------------------------------
    def add_recent_url(self, url: str) -> None:
        """Fügt eine URL zur Liste der zuletzt verwendeten URLs hinzu."""
        if not url:
            return
        if url in self.recent_urls:
            self.recent_urls.remove(url)
        self.recent_urls.insert(0, url)
        self.recent_urls = self.recent_urls[:10]
        self.save_to_file()

    def update_last_url(self, url: str) -> None:
        """Aktualisiert die zuletzt verwendete URL."""
        if url != self.last_url:
            self.last_url = url
            self.save_to_file()

    def clean_recent_urls(self) -> int:
        """Entfernt ungültige oder leere Einträge aus der Liste der letzten URLs."""
        old_len = len(self.recent_urls)
        cleaned = [u for u in self.recent_urls if u and u.strip()]
        removed = old_len - len(cleaned)
        if removed > 0:
            self.recent_urls = cleaned
            self.save_to_file()
        return removed

    def validate(self) -> List[str]:
        """Validiert die aktuellen Einstellungen."""
        issues = []
        if self.default_model not in Config.WHISPER_MODELS and self.default_model != "large-v3":
            issues.append(f"Ungültiges Modell: {self.default_model}")
        # Sprache muss ein gültiger Code oder "auto" sein
        if self.default_language not in SUPPORTED_LANGUAGES and self.default_language != "auto":
            issues.append(f"Ungültiger Sprachcode: {self.default_language}")
        if self.layout_mode not in ("vertical", "horizontal"):
            issues.append(f"Ungültiges Layout: {self.layout_mode}")
        if self.export_format not in ("txt", "srt", "vtt", "json", "docx"):
            issues.append(f"Ungültiges Exportformat: {self.export_format}")
        if self.theme not in ("dark", "light", "pastel", "system", "highcontrast"):
            issues.append(f"Ungültiges Theme: {self.theme}")
        return issues

    def repair(self) -> List[str]:
        """Stellt die Konsistenz der Einstellungen wieder her."""
        repairs = []
        default = AppSettings()

        if self.default_model not in Config.WHISPER_MODELS and self.default_model != "large-v3":
            old = self.default_model
            self.default_model = default.default_model
            repairs.append(f"Modell {old} -> {self.default_model}")

        if self.default_language not in SUPPORTED_LANGUAGES and self.default_language != "auto":
            old = self.default_language
            self.default_language = default.default_language
            repairs.append(f"Sprachcode {old} -> {self.default_language}")

        if self.layout_mode not in ("vertical", "horizontal"):
            old = self.layout_mode
            self.layout_mode = default.layout_mode
            repairs.append(f"Layout {old} -> {self.layout_mode}")

        if self.export_format not in ("txt", "srt", "vtt", "json", "docx"):
            old = self.export_format
            self.export_format = default.export_format
            repairs.append(f"Exportformat {old} -> {self.export_format}")

        if self.theme not in ("dark", "light", "pastel", "system", "highcontrast"):
            old = self.theme
            self.theme = default.theme
            repairs.append(f"Theme {old} -> {self.theme}")

        if repairs:
            logger.info(f"✅ AppSettings repariert: {', '.join(repairs)}")
            self.save_to_file()
        return repairs

    def __repr__(self) -> str:
        return (
            f"AppSettings(model={self.default_model}, "
            f"lang={self.default_language}, layout={self.layout_mode}, "
            f"theme={self.theme}, cookies={self.use_browser_cookies}, "
            f"cookies_browser={self.cookies_browser})"
        )

    @staticmethod
    def get_cookies_browser() -> str:
        """Liest den konfigurierten Browser aus den globalen Einstellungen."""
        try:
            settings = AppSettings.load_from_file()
            return settings.cookies_browser
        except Exception:
            return "firefox"


class StreamInfoExtractor:
    def __init__(self) -> None:
        self.current_info = StreamInfo(
            title="Unknown Stream",
            uploader="Unknown",
            duration="Live",
            view_count=0,
            platform="Unknown",
        )
        self._lock = threading.RLock()
        self._debug = DEBUG_LEVEL >= 1
        self.use_browser_cookies = True

    def extract_stream_info(self, url: str) -> StreamInfo:
        if self._debug:
            logger.debug(
                f"🔍 StreamInfoExtractor.extract_stream_info für: {url[:80]}..."
            )
        url = PlatformUtils.sanitize_url(url)
        if url.startswith("file://"):
            return self._handle_local_file(url)
        if "youtube.com" in url.lower() or "youtu.be" in url.lower():
            if self.use_browser_cookies:
                info = self._extract_youtube_info_with_cookies(url)
                if info:
                    self.current_info = info
                    return info
            info = self._run_ytdlp_json(url, platform="youtube")
            if info:
                self.current_info = info
                return info
        if "twitch.tv" in url.lower():
            if self.use_browser_cookies:
                info = self._extract_twitch_info_with_cookies(url)
                if info:
                    self.current_info = info
                    return info
            info = self._run_ytdlp_json(url, platform="twitch")
            if info:
                self.current_info = info
                return info
        info = self._run_ytdlp_json(url)
        if info:
            self.current_info = info
            return info
        info = self._fallback_from_url(url)
        self.current_info = info
        return info

    def _handle_local_file(self, url: str) -> StreamInfo:
        ok, real_path = PlatformUtils.validate_file_path(url)
        if not ok:
            return StreamInfo(
                title="Invalid file",
                uploader="Error",
                duration="",
                view_count=0,
                platform="invalid",
            )
        file_path = real_path
        return StreamInfo(
            title=os.path.basename(file_path),
            uploader="Local File",
            duration="File",
            view_count=0,
            platform="local",
        )

    def _run_ytdlp_json(
        self, url: str, platform: str = "generic"
    ) -> Optional[StreamInfo]:
        timeout = 15 if platform in ("youtube", "twitch") else 10
        try:
            data = YtDlpHelper.get_json(url, timeout=timeout)
            if not data:
                return None
            extractor = data.get("extractor", "").lower()
            platform_map = {
                "youtube": "youtube",
                "twitch": "twitch",
                "tiktok": "tiktok",
                "facebook": "facebook",
                "kick": "kick",
                "rumble": "rumble",
                "dailymotion": "dailymotion",
                "vimeo": "vimeo",
                "twitter": "twitter",
                "x": "twitter",
            }
            detected_platform = "unknown"
            for key, value in platform_map.items():
                if key in extractor:
                    detected_platform = value
                    break
            description = data.get("description", "")
            if len(description) > 200:
                description = description[:200] + "..."
            return StreamInfo(
                title=data.get("title", "Unknown Title"),
                uploader=data.get(
                    "uploader", data.get("channel", data.get("creator", "Unknown"))
                ),
                duration=data.get("duration_string", "Live"),
                view_count=data.get("view_count", 0),
                platform=detected_platform,
                description=description,
                duration_seconds=data.get("duration"),
            )
        except Exception as e:
            if self._debug:
                logger.debug(f"⚠️ yt-dlp JSON fehlgeschlagen für {url[:50]}: {e}")
        return None

    def _fallback_from_url(self, url: str) -> StreamInfo:
        if self._debug:
            logger.debug("🔄 StreamInfoExtractor: Fallback – extrahiere Titel aus URL")
        try:
            parsed = urllib.parse.urlparse(url)
            domain = parsed.netloc.replace("www.", "")
            path_segments = [s for s in parsed.path.split("/") if s]
            if "twitch.tv" in domain:
                channel = (
                    path_segments[0] if path_segments else domain.replace(".tv", "")
                )
                title = f"{channel} (Twitch)"
                uploader = channel
                platform = "twitch"
            elif "youtube.com" in domain or "youtu.be" in domain:
                channel = (
                    path_segments[0]
                    if path_segments
                    and path_segments[0] not in ("watch", "playlist", "shorts")
                    else "YouTube"
                )
                title = f"YouTube Stream - {channel}"
                uploader = channel
                platform = "youtube"
            else:
                if path_segments:
                    last = path_segments[-1]
                    title = f"{domain} - {last}"
                else:
                    title = domain
                uploader = domain
                platform = "unknown"
            return StreamInfo(
                title=title,
                uploader=uploader,
                duration="Live" if "live" in url.lower() else "Unknown",
                view_count=0,
                platform=platform,
            )
        except Exception as e:
            if self._debug:
                logger.debug(
                    f"❌ StreamInfoExtractor: URL-Fallback fehlgeschlagen: {e}"
                )
        return StreamInfo(
            title="Unknown Stream",
            uploader="Unknown",
            duration="Live",
            view_count=0,
            platform="unknown",
        )

    def _extract_youtube_info_with_cookies(self, url: str) -> Optional[StreamInfo]:
        """
        Extrahiert YouTube-Stream-Informationen mit Cookies aus dem konfigurierten Browser.
        Verwendet nur den in den Einstellungen festgelegten Browser (keine Schleife über alle).
        """
        logger.info("  🎯 YouTube detected, trying optimized cookie methods for channel name...")
        if IS_LINUX:
            self._ensure_chrome_symlinks()

        # Browser aus den Einstellungen lesen
        try:
            settings = AppSettings.load_from_file()
            browser = getattr(settings, "cookies_browser", "firefox")
        except Exception:
            browser = "firefox"

        # Einzelner Versuch mit dem konfigurierten Browser
        logger.info(f"    🧪 Versuche mit {browser.capitalize()} Cookies...")
        cmd = [
            "yt-dlp",
            "--cookies-from-browser", browser,
            "--dump-json",
            "--no-warnings",
            "--no-check-certificate",
            "--playlist-items", "1",
            "--",
            url,
        ]
        stdout = YtDlpHelper.run_command(cmd, timeout=12, method_name=f"{browser.capitalize()} Cookies")
        if stdout:
            output = stdout
            json_start = output.find("{")
            json_end = output.rfind("}") + 1
            if json_start >= 0 and json_end > json_start:
                try:
                    json_str = output[json_start:json_end]
                    info = json.loads(json_str)
                    uploader = info.get("uploader", "Unknown")
                    channel = info.get("channel", uploader)
                    creator = info.get("creator", uploader)
                    final_uploader = uploader
                    if channel != "Unknown" and channel != uploader:
                        final_uploader = channel
                    elif creator != "Unknown" and creator != uploader:
                        final_uploader = creator
                    if final_uploader == "Unknown":
                        final_uploader = info.get("uploader_id", "YouTube")
                    logger.info(f"      ✅ Success with {browser.capitalize()} Cookies")
                    logger.info(f"        Title: {info.get('title', 'YouTube Stream')[:60]}...")
                    logger.info(f"        Channel: {final_uploader}")
                    return StreamInfo(
                        title=info.get("title", "YouTube Stream"),
                        uploader=final_uploader,
                        duration=info.get("duration_string", "Live"),
                        view_count=info.get("view_count", 0),
                        platform="youtube",
                        description=(
                            info.get("description", "")[:200] + "..."
                            if len(info.get("description", "")) > 200
                            else info.get("description", "")
                        ),
                        duration_seconds=info.get("duration"),
                    )
                except json.JSONDecodeError:
                    pass

            # Fallback: Titel aus der reinen Textausgabe extrahieren
            lines = output.split("\n")
            for line in lines:
                if line.strip() and not line.startswith("{") and len(line.strip()) > 10:
                    possible_title = line.strip()
                    if len(possible_title) > 20 and len(possible_title) < 200:
                        logger.info("      ✅ Extracted title from output")
                        return StreamInfo(
                            title=possible_title,
                            uploader="YouTube",
                            duration="Live",
                            view_count=0,
                            platform="youtube",
                            description="",
                        )

        # Fallback: direkte Titel-Extraktion ohne Cookies
        logger.info("    🔄 Ultimate fallback: Direct title extraction...")
        return self._direct_youtube_fallback(url)

    def _build_youtube_methods(self, url: str) -> List[Tuple[List[str], str]]:
        """
        Baut die Liste der Extraktionsmethoden für YouTube auf.
        Verwendet nur den in den Einstellungen konfigurierten Browser für Cookies,
        gefolgt von Fallback-Methoden ohne Cookies.
        """
        methods = []

        # 1. Methode mit Cookies aus dem konfigurierten Browser (falls aktiviert)
        if self.use_browser_cookies:
            # Browser aus den globalen Einstellungen lesen
            try:
                settings = AppSettings.load_from_file()
                browser = getattr(settings, "cookies_browser", "firefox")
            except Exception:
                browser = "firefox"

            methods.append((
                [
                    "yt-dlp",
                    "--cookies-from-browser", browser,
                    "--dump-json",
                    "--no-warnings",
                    "--no-check-certificate",
                    "--playlist-items", "1",
                    "--",
                    url,
                ],
                f"{browser.capitalize()} Cookies",
            ))

        # 2. Fallback-Methoden ohne Cookies (wenn keine Cookies verwendet werden oder die erste fehlschlägt)
        fallback_methods = [
            (
                [
                    "yt-dlp",
                    "--dump-json",
                    "--no-warnings",
                    "--no-check-certificate",
                    "--playlist-items", "1",
                    "--quiet",
                    "--",
                    url,
                ],
                "No Cookies (Quiet)",
            ),
            (
                [
                    "yt-dlp",
                    "--dump-json",
                    "--no-warnings",
                    "--no-check-certificate",
                    "--playlist-items", "1",
                    "--",
                    url,
                ],
                "Simple JSON",
            ),
            (
                [
                    "yt-dlp",
                    "--get-title",
                    "--get-description",
                    "--get-duration",
                    "--no-warnings",
                    "--no-check-certificate",
                    "--quiet",
                    "--",
                    url,
                ],
                "Direct Info",
            ),
        ]
        methods.extend(fallback_methods)

        return methods

    def _get_browser_list(self) -> List[Tuple[str, str]]:
        if IS_LINUX:
            return [
                ("firefox", "Firefox"),
                ("chromium", "Chromium"),
                ("brave", "Brave"),
                ("chrome", "Chrome"),
                ("vivaldi", "Vivaldi"),
                ("opera", "Opera"),
                ("edge", "Edge"),
            ]
        elif IS_WINDOWS:
            return [
                ("chrome", "Chrome"),
                ("firefox", "Firefox"),
                ("edge", "Edge"),
                ("brave", "Brave"),
                ("opera", "Opera"),
            ]
        else:
            return [
                ("safari", "Safari"),
                ("chrome", "Chrome"),
                ("firefox", "Firefox"),
                ("brave", "Brave"),
                ("edge", "Edge"),
            ]

    def _ensure_chrome_symlinks(self) -> None:
        """
        Erstellt Symlinks für Chrome‑Kompatibilität unter Linux.
        Fehler beim Symlink‑Erstellen werden abgefangen und geloggt.
        """
        try:
            chrome_config_dir = Path.home() / ".config" / "google-chrome"
            chromium_config_dir = Path.home() / ".config" / "chromium"
            if chromium_config_dir.exists() and not chrome_config_dir.exists():
                chrome_config_dir.mkdir(parents=True, exist_ok=True)
                chromium_files = [
                    "Local State",
                    "Default/Cookies",
                    "Default/Login Data",
                ]
                for file_path in chromium_files:
                    chromium_file = chromium_config_dir / file_path
                    chrome_file = chrome_config_dir / file_path
                    if chromium_file.exists() and not chrome_file.exists():
                        chrome_file.parent.mkdir(parents=True, exist_ok=True)
                        try:
                            os.symlink(str(chromium_file), str(chrome_file))
                        except OSError as e:
                            logger.debug(
                                f"Symlink-Erstellung fehlgeschlagen (keine Admin‑Rechte?): {e}"
                            )
                logger.info("    🔗 Created Chrome compatibility symlinks for yt-dlp")
        except Exception as e:
            logger.warning(f"    ⚠️ Chrome symlink setup failed: {e}")

    def _direct_youtube_fallback(self, url: str) -> Optional[StreamInfo]:
        try:
            cmd_title = [
                "yt-dlp",
                "--get-title",
                "--no-warnings",
                "--no-check-certificate",
                "--quiet",
                "--",
                url,
            ]
            cmd_uploader = [
                "yt-dlp",
                "--get-filename",
                "-o",
                "%(uploader)s",
                "--no-warnings",
                "--no-check-certificate",
                "--quiet",
                "--",
                url,
            ]
            with ThreadPoolExecutor(max_workers=2) as executor:
                title_future = executor.submit(
                    YtDlpHelper.run_command, cmd_title, 8, "direct_title"
                )
                uploader_future = executor.submit(
                    YtDlpHelper.run_command, cmd_uploader, 8, "direct_uploader"
                )
                title_result = title_future.result(timeout=10)
                uploader_result = uploader_future.result(timeout=10)
            title = "YouTube Stream"
            uploader = "YouTube"
            if title_result and title_result.strip():
                title = title_result.strip().split("\n")[0]
            if uploader_result and uploader_result.strip():
                uploader = uploader_result.strip().split("\n")[0]
            logger.info("      ✅ Success with direct extraction")
            return StreamInfo(
                title=title[:100] if len(title) > 100 else title,
                uploader=uploader,
                duration="Live",
                view_count=0,
                platform="youtube",
                description="",
            )
        except Exception as e:
            logger.info(f"      ⚠️ Direct extraction failed: {e}")
            return None

    def _extract_twitch_info_with_cookies(self, url: str) -> Optional[StreamInfo]:
        logger.info("  🎯 Twitch detected, trying cookie methods for channel name...")
        methods = self._build_twitch_methods(url)
        logger.info(f"    📋 Using {len(methods)} extraction methods for Twitch")
        max_attempts = min(4, len(methods))
        attempts = 0
        for cmd, method_name in methods:
            if attempts >= max_attempts:
                break
            attempts += 1
            try:
                logger.info(f"    🧪 Attempt {attempts}/{max_attempts}: {method_name}")
                timeout = 12 if "Cookies" in method_name else 8
                stdout = YtDlpHelper.run_command(
                    cmd, timeout=timeout, method_name=method_name
                )
                if not stdout:
                    continue
                output = stdout
                try:
                    json_start = output.find("{")
                    json_end = output.rfind("}") + 1
                    if json_start >= 0 and json_end > json_start:
                        json_str = output[json_start:json_end]
                        info = json.loads(json_str)
                        uploader = info.get(
                            "uploader",
                            info.get("channel", info.get("creator", "Unknown")),
                        )
                        title = info.get("title", "Twitch Stream")
                        duration = info.get("duration_string", "Live")
                        view_count = info.get("view_count", 0)
                        description = info.get("description", "")
                        if len(description) > 200:
                            description = description[:200] + "..."
                        logger.info(f"      ✅ Success with {method_name}")
                        logger.info(f"        Title: {title[:60]}...")
                        logger.info(f"        Channel: {uploader}")
                        return StreamInfo(
                            title=title,
                            uploader=uploader,
                            duration=duration,
                            view_count=view_count,
                            platform="twitch",
                            description=description,
                            duration_seconds=info.get("duration"),
                        )
                except json.JSONDecodeError:
                    lines = output.split("\n")
                    title = None
                    uploader = None
                    for line in lines:
                        if line.strip() and not line.startswith("{"):
                            if title is None:
                                title = line.strip()
                            elif uploader is None:
                                uploader = line.strip()
                                break
                    if title and len(title) > 10:
                        logger.info("      ✅ Extracted title from output")
                        return StreamInfo(
                            title=title[:100] if len(title) > 100 else title,
                            uploader=uploader or "Twitch",
                            duration="Live",
                            view_count=0,
                            platform="twitch",
                            description="",
                        )
            except Exception as e:
                logger.info(f"      ⚠️ Method error: {str(e)[:50]}")
                continue
        return self._twitch_url_fallback(url)

    def _build_twitch_methods(self, url: str) -> List[Tuple[List[str], str]]:
        methods = []
        if self.use_browser_cookies:
            for browser_cmd, browser_name in self._get_browser_list():
                methods.append(
                    (
                        [
                            "yt-dlp",
                            "--cookies-from-browser",
                            browser_cmd,
                            "--dump-json",
                            "--format",
                            "best",
                            "--no-warnings",
                            "--no-check-certificate",
                            "--socket-timeout",
                            "15",
                            "--",
                            url,
                        ],
                        f"{browser_name} Cookies",
                    )
                )
        fallback_methods = [
            (
                [
                    "yt-dlp",
                    "--dump-json",
                    "--no-warnings",
                    "--no-check-certificate",
                    "--socket-timeout",
                    "10",
                    "--",
                    url,
                ],
                "Simple JSON",
            ),
            (
                [
                    "yt-dlp",
                    "--get-title",
                    "--get-description",
                    "--get-duration",
                    "--no-warnings",
                    "--no-check-certificate",
                    "--quiet",
                    "--",
                    url,
                ],
                "Direct Info",
            ),
        ]
        methods.extend(fallback_methods)
        return methods

    def _twitch_url_fallback(self, url: str) -> Optional[StreamInfo]:
        try:
            parsed = urllib.parse.urlparse(url)
            path = parsed.path.strip("/")
            channel = (
                path.split("/")[0]
                if path
                else parsed.netloc.replace("www.", "").replace(".tv", "")
            )
            if channel:
                return StreamInfo(
                    title=f"{channel} (Twitch Live)",
                    uploader=channel,
                    duration="Live",
                    view_count=0,
                    platform="twitch",
                    description="",
                )
        except Exception:
            pass
        return None


class ExportManager:
    def __init__(self) -> None:
        self.supported_formats = ["txt", "srt", "vtt", "json", "docx"]
        self._docx_available: bool = False
        self._docx = None
        try:
            import docx

            self._docx = docx
            self._docx_available = True
        except ImportError:
            self._docx_available = False

    def export_subtitles(
        self,
        transcript_data: List[TranscriptionResult],
        translation_data: Optional[List[TranslationResult]] = None,
        format: str = "srt",
        filename: Optional[str] = None,
        encoding: str = "utf-8-sig",
    ) -> Union[bool, str]:
        try:
            if format.lower() not in ("txt", "json"):
                timed = [
                    t
                    for t in transcript_data
                    if hasattr(t, "start")
                    and t.start is not None
                    and hasattr(t, "end")
                    and t.end is not None
                ]
                if not timed:
                    raise ProcessingError(
                        "Keine Segmente mit Zeitstempeln vorhanden – benötigt für Untertitel."
                    )
                transcript_data = timed
            if format.lower() == "srt":
                content = self._generate_srt_content(transcript_data, translation_data)
            elif format.lower() == "vtt":
                content = self._generate_vtt_content(transcript_data, translation_data)
            elif format.lower() == "txt":
                content = self._generate_txt_content(transcript_data, translation_data)
            elif format.lower() == "json":
                if filename:
                    return self.export_json(
                        transcript_data, translation_data or [], filename
                    )
                else:
                    import json

                    data = self._build_json_data(transcript_data, translation_data)
                    return json.dumps(data, indent=2, ensure_ascii=False)
            elif format.lower() == "docx":
                if filename:
                    return self.export_docx(transcript_data, filename)
                else:
                    raise ProcessingError(
                        "Für DOCX-Export wird ein Dateiname benötigt."
                    )
            else:
                raise ProcessingError(f"Nicht unterstütztes Format: {format}")
            if filename:
                out_path = Path(filename)
                out_path.parent.mkdir(parents=True, exist_ok=True)
                with open(out_path, "w", encoding=encoding) as f:
                    f.write(content)
                return True
            else:
                return content
        except Exception as e:
            logger.error(f"Fehler beim Export: {e}")
            raise ProcessingError(f"Export fehlgeschlagen: {e}") from e

    def export_json(
        self,
        transcript_data: List[TranscriptionResult],
        translation_data: List[TranslationResult],
        filename: str,
        encoding: str = "utf-8",
    ) -> bool:
        try:
            data = self._build_json_data(transcript_data, translation_data)
            out_path = Path(filename)
            out_path.parent.mkdir(parents=True, exist_ok=True)
            with open(out_path, "w", encoding=encoding) as f:
                json.dump(data, f, indent=2, ensure_ascii=False)
            return True
        except Exception as e:
            raise ProcessingError(f"JSON-Export fehlgeschlagen: {e}") from e

    def export_docx(
        self,
        transcript_data: List[TranscriptionResult],
        filename: str,
    ) -> bool:
        """
        Exportiert die Transkription als DOCX‑Datei (oder als TXT‑Fallback).

        Args:
            transcript_data: Liste der Transkriptionssegmente.
            filename: Zieldateiname (inkl. Pfad).

        Returns:
            True bei Erfolg.

        Raises:
            ProcessingError: Bei Fehlern während des Exports.
        """
        if not transcript_data:
            raise ProcessingError("Keine Transkriptionsdaten zum Exportieren")

        # Versuche DOCX‑Export mit python-docx
        if self._docx_available:
            try:
                doc = self._docx.Document()
                doc.add_heading("Transkription", level=1)

                for i, seg in enumerate(transcript_data, 1):
                    p = doc.add_paragraph()
                    # Zeitstempel hinzufügen, falls vorhanden
                    if hasattr(seg, "start") and seg.start is not None:
                        start_str = self._format_timestamp_srt(seg.start)
                        p.add_run(f"[{start_str}] ").bold = True
                    p.add_run(seg.text)
                    # Leerzeile zwischen den Segmenten (außer nach dem letzten)
                    if i < len(transcript_data):
                        doc.add_paragraph()

                out_path = Path(filename)
                out_path.parent.mkdir(parents=True, exist_ok=True)
                doc.save(str(out_path))
                return True

            except Exception as e:
                logger.warning(
                    f"python-docx Export fehlgeschlagen, verwende Fallback: {e}"
                )

        # Fallback: Export als einfache Textdatei
        try:
            content = self._generate_txt_content(transcript_data, None)
            out_path = Path(filename)
            out_path.parent.mkdir(parents=True, exist_ok=True)
            with open(out_path, "w", encoding="utf-8") as f:
                f.write(content)
            return True
        except Exception as e:
            raise ProcessingError(f"DOCX-Fallback fehlgeschlagen: {e}") from e

    def _generate_srt_content(
        self,
        transcript_data: List[TranscriptionResult],
        translation_data: Optional[List[TranslationResult]] = None,
    ) -> str:
        lines = []
        for i, segment in enumerate(transcript_data):
            start = self._format_timestamp_srt(segment.start or 0.0)
            end = self._format_timestamp_srt(segment.end or 0.0)
            text = segment.text
            if translation_data and i < len(translation_data):
                text = f"{text}\n{translation_data[i].translated}"
            lines.append(f"{i+1}\n{start} --> {end}\n{text}\n")
        return "\n".join(lines)

    def _generate_vtt_content(
        self,
        transcript_data: List[TranscriptionResult],
        translation_data: Optional[List[TranslationResult]] = None,
    ) -> str:
        lines = ["WEBVTT\n"]
        for i, segment in enumerate(transcript_data):
            start = self._format_timestamp_vtt(segment.start or 0.0)
            end = self._format_timestamp_vtt(segment.end or 0.0)
            text = segment.text
            if translation_data and i < len(translation_data):
                text = f"{text}\n{translation_data[i].translated}"
            lines.append(f"{start} --> {end}\n{text}\n")
        return "\n".join(lines)

    def _generate_txt_content(
        self,
        transcript_data: List[TranscriptionResult],
        translation_data: Optional[List[TranslationResult]] = None,
    ) -> str:
        lines = []
        for i, segment in enumerate(transcript_data):
            if hasattr(segment, "start") and segment.start is not None:
                timestamp = self._format_timestamp_srt(segment.start)
                prefix = f"[{timestamp}] "
            else:
                prefix = ""
            text = segment.text
            if translation_data and i < len(translation_data):
                text = f"{text}  |  {translation_data[i].translated}"
            lines.append(f"{prefix}{text}")
        return "\n".join(lines)

    def _build_json_data(
        self,
        transcript_data: List[TranscriptionResult],
        translation_data: List[TranslationResult],
    ) -> Dict[str, Any]:
        return {
            "metadata": {
                "export_date": datetime.now().isoformat(),
                "total_segments": len(transcript_data),
                "version": "4.1.3",
            },
            "transcripts": [
                {
                    "text": seg.text,
                    "confidence": seg.confidence,
                    "language": seg.language,
                    "timestamp": seg.timestamp,
                    "start": getattr(seg, "start", None),
                    "end": getattr(seg, "end", None),
                }
                for seg in transcript_data
            ],
            "translations": (
                [
                    {
                        "original": trans.original,
                        "translated": trans.translated,
                        "source_lang": trans.source_lang,
                        "target_lang": trans.target_lang,
                        "timestamp": trans.timestamp,
                        "start": getattr(trans, "start", None),
                        "end": getattr(trans, "end", None),
                    }
                    for trans in translation_data
                ]
                if translation_data
                else []
            ),
        }

    @staticmethod
    def _format_timestamp_srt(seconds: float) -> str:
        hours = int(seconds // 3600)
        minutes = int((seconds % 3600) // 60)
        secs = seconds % 60
        milliseconds = int((secs - int(secs)) * 1000)
        return f"{hours:02d}:{minutes:02d}:{int(secs):02d},{milliseconds:03d}"

    @staticmethod
    def _format_timestamp_vtt(seconds: float) -> str:
        hours = int(seconds // 3600)
        minutes = int((seconds % 3600) // 60)
        secs = seconds % 60
        milliseconds = int((secs - int(secs)) * 1000)
        return f"{hours:02d}:{minutes:02d}:{int(secs):02d}.{milliseconds:03d}"


class ResourceManager:
    """
    Zentrale Verwaltung von Systemressourcen (Prozesse, Threads, temporäre Dateien).

    Diese Klasse sammelt alle vom Programm erstellten Ressourcen und stellt sicher,
    dass sie beim Programmende oder bei einem Fehler sauber freigegeben werden.
    Sie ist thread-sicher und kann über den Kontextmanager `with` verwendet werden.

    Features:
        - Registrierung von subprocess.Popen-Prozessen
        - Registrierung von threading.Thread-Objekten
        - Registrierung temporärer Dateipfade
        - Automatische Terminierung von Prozessen mit Kindprozessen (via psutil)
        - Automatisches Joinen von Threads
        - Löschen temporärer Dateien
        - GPU-Cache-Bereinigung (via torch)
        - atexit-Handler für Notfall-Cleanup
        - Zeitbegrenzung für Cleanup, um Programmende nicht zu blockieren
    """

    __slots__ = (
        "processes",
        "threads",
        "temp_files",
        "cleanup_done",
        "_lock",
        "_shutdown_event",
        "_atexit_registered",
        "_psutil",
    )

    def __init__(self) -> None:
        """Initialisiert den ResourceManager."""
        self.processes: List[subprocess.Popen] = []
        self.threads: List[threading.Thread] = []
        self.temp_files: List[str] = []
        self.cleanup_done = False
        self._lock = threading.RLock()
        self._shutdown_event = threading.Event()
        self._atexit_registered = False
        self._psutil = None
        try:
            import psutil

            self._psutil = psutil
        except ImportError:
            pass

        # atexit-Handler nur einmal registrieren (für Notfall-Cleanup)
        if not self._atexit_registered:
            self._atexit_registered = True
            atexit.register(self._atexit_cleanup)

    def _atexit_cleanup(self) -> None:
        """Notfall-Cleanup bei Programmende, falls normale Cleanup nicht erfolgte."""
        if not self.cleanup_done:
            logger.info("⚠️ ResourceManager: atexit-Cleanup wird ausgeführt")
            self.cleanup(timeout=3.0)

    # -------------------------------------------------------------------------
    # Registrierung & Deregistrierung
    # -------------------------------------------------------------------------
    def register_process(self, process: subprocess.Popen) -> None:
        """
        Registriert einen Subprozess für die spätere Bereinigung.

        Args:
            process: Der zu registrierende subprocess.Popen.
        """
        with self._lock:
            if process and process not in self.processes:
                self.processes.append(process)

    def unregister_process(self, process: subprocess.Popen) -> bool:
        """
        Entfernt einen Prozess aus der Verwaltung (z.B. nach erfolgreicher Terminierung).

        Args:
            process: Der zu entfernende Prozess.

        Returns:
            True, wenn der Prozess registriert war und entfernt wurde, sonst False.
        """
        with self._lock:
            if process in self.processes:
                self.processes.remove(process)
                return True
        return False

    def register_thread(self, thread: threading.Thread) -> None:
        """
        Registriert einen Thread für die spätere Bereinigung.

        Nur lebende Threads werden registriert.

        Args:
            thread: Der zu registrierende Thread.
        """
        with self._lock:
            if thread and thread not in self.threads and thread.is_alive():
                self.threads.append(thread)

    def unregister_thread(self, thread: threading.Thread) -> bool:
        """
        Entfernt einen Thread aus der Verwaltung.

        Args:
            thread: Der zu entfernende Thread.

        Returns:
            True, wenn der Thread registriert war und entfernt wurde, sonst False.
        """
        with self._lock:
            if thread in self.threads:
                self.threads.remove(thread)
                return True
        return False

    def register_temp_file(self, file_path: str) -> None:
        """
        Registriert eine temporäre Datei zum Löschen bei der Bereinigung.

        Args:
            file_path: Pfad zur temporären Datei.
        """
        with self._lock:
            if file_path and file_path not in self.temp_files:
                self.temp_files.append(file_path)

    def unregister_temp_file(self, file_path: str) -> bool:
        """
        Entfernt eine temporäre Datei aus der Verwaltung.

        Args:
            file_path: Pfad zur temporären Datei.

        Returns:
            True, wenn die Datei registriert war und entfernt wurde, sonst False.
        """
        with self._lock:
            if file_path in self.temp_files:
                self.temp_files.remove(file_path)
                return True
        return False

    def is_shutting_down(self) -> bool:
        """Gibt zurück, ob der Shutdown eingeleitet wurde."""
        return self._shutdown_event.is_set()

    # -------------------------------------------------------------------------
    # Hauptbereinigung
    # -------------------------------------------------------------------------
    def cleanup(self, timeout: float = 5.0) -> bool:
        """
        Führt die Bereinigung aller registrierten Ressourcen durch.

        Diese Methode ist nur einmal pro Instanz wirksam. Sie setzt ein internes
        Shutdown-Event, beendet Prozesse, joined Threads und löscht temporäre Dateien.
        Die Operation ist zeitbegrenzt, um das Programmende nicht unnötig zu verzögern.

        Args:
            timeout: Maximale Zeit in Sekunden für die gesamte Bereinigung.

        Returns:
            True, wenn die Bereinigung abgeschlossen wurde (ggf. mit Timeout),
            False, wenn sie bereits zuvor ausgeführt wurde.
        """
        if self.cleanup_done:
            return False

        logger.debug("🧹 ResourceManager: Starte Bereinigung...")
        self._shutdown_event.set()
        start_time = time.time()
        remaining_timeout = timeout

        # 1. Prozesse beenden
        with self._lock:
            processes_to_terminate = self.processes[:]
        for proc in processes_to_terminate:
            if time.time() - start_time > timeout:
                logger.warning("⚠️ Cleanup timeout – breche Prozessbereinigung ab")
                break
            try:
                self._terminate_process(proc)
            except Exception as e:
                logger.warning(f"⚠️ Fehler beim Beenden von Prozess {proc.pid}: {e}")
            finally:
                with self._lock:
                    if proc in self.processes:
                        self.processes.remove(proc)

        # 2. Threads beenden
        remaining_timeout = timeout - (time.time() - start_time)
        with self._lock:
            threads_to_join = self.threads[:]
        for thread in threads_to_join:
            if time.time() - start_time > timeout:
                logger.warning("⚠️ Cleanup timeout – breche Thread-Join ab")
                break
            if not thread.is_alive():
                with self._lock:
                    if thread in self.threads:
                        self.threads.remove(thread)
                continue
            thread_timeout = max(0.1, remaining_timeout)
            try:
                thread.join(timeout=thread_timeout)
            except Exception as e:
                logger.warning(f"⚠️ Fehler beim Join von Thread {thread.name}: {e}")
            finally:
                with self._lock:
                    if thread in self.threads:
                        self.threads.remove(thread)
            remaining_timeout = max(0.1, timeout - (time.time() - start_time))

        # 3. Temporäre Dateien löschen
        remaining_timeout = timeout - (time.time() - start_time)
        with self._lock:
            temp_files_to_delete = self.temp_files[:]
        for temp_file in temp_files_to_delete:
            if time.time() - start_time > timeout:
                logger.warning(
                    "⚠️ Cleanup timeout – breche Löschen temporärer Dateien ab"
                )
                break
            try:
                if os.path.exists(temp_file):
                    os.unlink(temp_file)
                    logger.debug(f"🗑️ Temporäre Datei gelöscht: {temp_file}")
            except (OSError, PermissionError) as e:
                logger.warning(
                    f"⚠️ Konnte temporäre Datei {temp_file} nicht löschen: {e}"
                )
            finally:
                with self._lock:
                    if temp_file in self.temp_files:
                        self.temp_files.remove(temp_file)

        # 4. GPU-Cache leeren (optional)
        try:
            import torch

            if torch.cuda.is_available():
                torch.cuda.empty_cache()
                logger.debug("🧹 GPU-Cache geleert")
        except ImportError:
            pass

        # 5. Garbage Collection
        gc.collect()
        self.cleanup_done = True
        logger.info("✅ ResourceManager: Alle Ressourcen bereinigt")
        return True

    def dispose(self) -> None:
        """Öffentliche Methode zum Entsorgen der Ressourcen (Alias für cleanup)."""
        self.cleanup()

    # -------------------------------------------------------------------------
    # Interne Terminierungslogik
    # -------------------------------------------------------------------------
    def _terminate_process(self, proc: subprocess.Popen) -> None:
        """Beendet einen Prozess und alle seine Kindprozesse."""
        PlatformUtils.terminate_process(
            proc,
            child_terminate_timeout=2.0,
            child_kill_wait=1.0,
            parent_terminate_timeout=2.0,
            parent_kill_wait=1.0,
            fallback_terminate_timeout=2.0,
            fallback_kill_wait=1.0,
            stats_callback=None,
        )


class LanguageDetector:
    """
    Sprachdetektion für Audio-/Videodateien mittels Whisper.

    Diese Klasse extrahiert eine kurze Audioprobe aus der Mediendatei und führt
    eine Transkription mit Whisper durch, um die Sprache zu erkennen. Sie ist
    robust gegenüber verschiedenen Audioformaten, kann die Probe intelligent
    wählen und liefert detaillierte Ergebnisse.

    Features:
        - Automatische Extraktion der Audioprobe mit ffmpeg
        - Intelligente Wahl der Probendauer basierend auf Dateilänge
        - Robuste Verarbeitung von WAV‑Dateien mit korrektem Header-Parsing
        - Deaktiviert VAD während der Sprachdetektion für bessere Ergebnisse
        - Fallback bei leeren Ergebnissen: Zweiter Versuch mit verstärktem Audio
        - Detaillierte Fehlerbehandlung mit aussagekräftigen Meldungen
        - Cache für häufige Dateien (optional)
        - Thread-sicher und mit Timeout-Schutz

    Attributes:
        transcription_engine (TranscriptionEngine): Die zu verwendende Transkriptionsengine.
        _debug (bool): Debug-Modus aktiviert.
        _cache (Optional[TTLCache]): Cache für Spracherkennungsergebnisse.
        _lock (threading.RLock): Lock für Thread-Sicherheit.
        _ffmpeg_timeout (int): Timeout für ffmpeg/ffprobe-Aufrufe in Sekunden.
    """

    def __init__(
        self,
        transcription_engine: TranscriptionEngine,
        enable_cache: bool = True,
        cache_ttl: float = 3600,
    ) -> None:
        """
        Initialisiert den LanguageDetector.

        Args:
            transcription_engine: Die Transkriptionsengine (z.B. Whisper).
            enable_cache: Ob Ergebnisse zwischengespeichert werden sollen.
            cache_ttl: Lebensdauer der Cache-Einträge in Sekunden.
        """
        self.transcription_engine = transcription_engine
        self._debug = logger.isEnabledFor(logging.DEBUG)
        self._lock = threading.RLock()
        self._cache: Optional[TTLCache] = (
            TTLCache(maxsize=50, ttl=cache_ttl) if enable_cache else None
        )
        self._ffmpeg_timeout = 30  # Sekunden für ffmpeg/ffprobe-Aufrufe

        # Lazy‑geladene Module (werden bei Bedarf geladen)
        self._np = None  # numpy (für Audio‑Verstärkung)
        self._scipy_signal = None  # scipy.signal (für Hochpassfilter, falls benötigt)

    # -------------------------------------------------------------------------
    # Öffentliche Methoden
    # -------------------------------------------------------------------------
    def detect_video_language(
        self, file_path: str, force: bool = False, sample_duration: Optional[int] = None
    ) -> Dict[str, Any]:
        """
        Ermittelt die Sprache einer lokalen Audio-/Videodatei.

        Bei leerem Ergebnis wird ein zweiter Versuch mit verstärktem Audio
        (Gain-Faktor 2.0) durchgeführt, um leise oder wenig kontrastreiche
        Passagen besser zu erkennen.

        Args:
            file_path: Pfad zur Datei (kann auch mit file:// beginnen).
            force: Cache ignorieren und neu analysieren.
            sample_duration: Dauer der Audioprobe in Sekunden (überschreibt automatische Schätzung).

        Returns:
            Dictionary mit folgenden Feldern:
                - detected_language (str): ISO-Sprachcode (z.B. 'de', 'en')
                - language_name (str): Sprachbezeichnung (z.B. 'Deutsch')
                - confidence (float): Konfidenzwert (0.0-1.0)
                - sample_text (str): Beispieltext (gekürzt)
                - duration_analyzed (float): Analysierte Dauer in Sekunden
                - file_duration (float): Gesamtdauer der Datei (falls bekannt)
                - enhanced_used (bool): Ob der verstärkte Fallback verwendet wurde
                Im Fehlerfall enthält das Dictionary ein Feld 'error' mit der Fehlermeldung.

        Raises:
            ValueError: Wenn die Datei nicht existiert oder nicht lesbar ist.
        """
        # Pfad bereinigen (file:// entfernen)
        if file_path.startswith("file://"):
            file_path = file_path[7:]

        if not os.path.exists(file_path):
            raise ValueError(f"Datei nicht gefunden: {file_path}")

        if not os.access(file_path, os.R_OK):
            raise ValueError(f"Keine Leserechte für Datei: {file_path}")

        # Cache prüfen
        cache_key = hashlib.sha256(file_path.encode()).hexdigest()
        if self._cache and not force:
            cached = self._cache.get(cache_key)
            if cached is not None:
                if self._debug:
                    logger.debug(
                        f"Sprachdetektion aus Cache für {os.path.basename(file_path)}"
                    )
                return cached

        # Datei-Metadaten ermitteln
        file_duration = self._get_media_duration(file_path)
        file_size_mb = os.path.getsize(file_path) / (1024 * 1024)

        # Probendauer intelligent wählen
        if sample_duration is None:
            if file_duration is not None:
                # Bei kurzen Dateien: gesamte Datei oder die Hälfte, max. 60 Sekunden
                if file_duration <= 120:
                    sample_duration = file_duration
                else:
                    sample_duration = min(60, max(30, file_duration // 2))
            else:
                # Bei unbekannter Dauer: 60 Sekunden, bei großen Dateien weniger
                if file_size_mb > 500:
                    sample_duration = 30
                else:
                    sample_duration = 60

        if self._debug:
            logger.debug(
                f"Sprachdetektion: Datei={os.path.basename(file_path)}, "
                f"Dauer={file_duration if file_duration else 'unbekannt'}s, "
                f"Probe={sample_duration}s, Größe={file_size_mb:.1f}MB"
            )

        # Audioprobe extrahieren
        audio_sample = self._extract_audio_sample(file_path, duration=sample_duration)
        if not audio_sample:
            return {"error": "Konnte keine Audioprobe extrahieren (ffmpeg-Fehler)"}

        # Temporäre Einstellungen für Sprachdetektion: VAD deaktivieren, Sprache automatisch
        old_vad = self.transcription_engine.settings.vad_filter
        old_language = self.transcription_engine.forced_language

        try:
            self.transcription_engine.settings.vad_filter = False
            self.transcription_engine.forced_language = None
            result = self.transcription_engine.transcribe_audio(
                audio_sample, include_timestamps=False
            )
        except Exception as e:
            logger.exception(f"Fehler bei Sprachdetektion-Transkription: {e}")
            return {"error": f"Transkription fehlgeschlagen: {str(e)}"}
        finally:
            # Alte Einstellungen wiederherstellen
            self.transcription_engine.settings.vad_filter = old_vad
            self.transcription_engine.forced_language = old_language

        # Prüfen, ob ein Ergebnis vorliegt
        if not result or not result.text or not result.text.strip():
            # Fallback: Verstärkung des Audios (Gain-Faktor 2.0) und zweiter Versuch
            if self._debug:
                logger.debug(
                    "Sprachdetektion: Kein Text erkannt, versuche verstärktes Audio..."
                )
            amplified = self._amplify_audio(audio_sample, gain=2.0)
            if amplified:
                try:
                    self.transcription_engine.settings.vad_filter = False
                    self.transcription_engine.forced_language = None
                    result2 = self.transcription_engine.transcribe_audio(
                        amplified, include_timestamps=False
                    )
                except Exception as e:
                    logger.exception(f"Fehler bei verstärkter Sprachdetektion: {e}")
                    return {
                        "error": "Kein gesprochener Text in der Audioprobe erkannt (auch nach Verstärkung)"
                    }
                finally:
                    self.transcription_engine.settings.vad_filter = old_vad
                    self.transcription_engine.forced_language = old_language

                if result2 and result2.text and result2.text.strip():
                    result = result2
                    enhanced_used = True
                else:
                    return {"error": "Kein gesprochener Text in der Audioprobe erkannt"}
            else:
                return {"error": "Kein gesprochener Text in der Audioprobe erkannt"}
        else:
            enhanced_used = False

        # Ergebnisse aufbereiten
        language_code = getattr(result, "language", "unknown")
        language_name = SUPPORTED_LANGUAGES.get(language_code, "Unbekannt")
        confidence = getattr(result, "confidence", 0.8)
        sample_text = result.text.strip()

        # Text für Anzeige kürzen
        if len(sample_text) > 100:
            sample_text = sample_text[:100] + "..."

        detection_result = {
            "detected_language": language_code,
            "language_name": language_name,
            "confidence": confidence,
            "sample_text": sample_text,
            "duration_analyzed": sample_duration,
            "file_duration": file_duration,
            "enhanced_used": enhanced_used,
        }

        # Cache speichern
        if self._cache:
            self._cache.put(cache_key, detection_result)

        return detection_result

    def clear_cache(self) -> None:
        """Leert den internen Cache."""
        if self._cache:
            self._cache.clear()
            if self._debug:
                logger.debug("Sprachdetektions-Cache geleert")

    def get_cache_stats(self) -> Dict[str, Any]:
        """Gibt Statistiken zum Cache zurück."""
        if self._cache:
            return self._cache.get_stats()
        return {"enabled": False}

    # -------------------------------------------------------------------------
    # Private Hilfsmethoden
    # -------------------------------------------------------------------------
    def _get_media_duration(self, file_path: str) -> Optional[float]:
        """
        Ermittelt die Dauer einer Mediendatei mit ffprobe.

        Args:
            file_path: Pfad zur Datei.

        Returns:
            Dauer in Sekunden oder None bei Fehler.
        """
        if not shutil.which("ffprobe"):
            if self._debug:
                logger.debug("ffprobe nicht gefunden – kann Dateidauer nicht ermitteln")
            return None

        cmd = [
            "ffprobe",
            "-v",
            "error",
            "-show_entries",
            "format=duration",
            "-of",
            "default=noprint_wrappers=1:nokey=1",
            file_path,
        ]

        try:
            result = subprocess.run(
                cmd,
                capture_output=True,
                text=True,
                timeout=self._ffmpeg_timeout,
                check=False,
            )
            if result.returncode == 0 and result.stdout.strip():
                return float(result.stdout.strip())
        except (
            subprocess.TimeoutExpired,
            subprocess.CalledProcessError,
            ValueError,
        ) as e:
            if self._debug:
                logger.debug(f"ffprobe error: {e}")
        except Exception as e:
            logger.warning(f"Unerwarteter Fehler in _get_media_duration: {e}")
        return None

    def _extract_audio_sample(
        self, file_path: str, duration: int = 30
    ) -> Optional[bytes]:
        """
        Extrahiert eine kurze Audioprobe im Rohformat (16-bit PCM, 16 kHz, mono).

        Für WAV‑Dateien wird das Standardmodul `wave` verwendet, um den Header
        korrekt zu parsen und die Daten auszulesen. Bei Nicht‑Kompatibilität oder
        Fehlern wird automatisch auf ffmpeg umgeschaltet. Für alle anderen Formate
        wird ffmpeg genutzt.

        Args:
            file_path: Pfad zur Mediendatei.
            duration: Dauer der Probe in Sekunden.

        Returns:
            Byte-Daten der Audioprobe oder None bei Fehler.
        """
        config = self.transcription_engine.settings.config

        # --- Optimierung: WAV-Dateien mit passendem Format direkt via wave lesen ---
        if file_path.lower().endswith(".wav"):
            try:
                data = self._extract_wav_sample(file_path, duration, config)
                if data is not None:
                    return data
            except Exception as e:
                if self._debug:
                    logger.debug(f"Direktes Einlesen der WAV-Datei fehlgeschlagen: {e}")
                # Fallback auf ffmpeg – wird nach dem if‑Block ausgeführt

        # --- Standard: ffmpeg verwenden (auch für nicht‑kompatible WAVs) ---
        cmd = [
            "ffmpeg",
            "-i",
            file_path,
            "-t",
            str(duration),
            "-vn",  # Video deaktivieren
            "-f",
            config.AUDIO_FORMAT,
            "-ar",
            str(config.SAMPLE_RATE),
            "-ac",
            str(config.CHANNELS),
            "-loglevel",
            "error",
            "-",
        ]

        try:
            result = subprocess.run(
                cmd,
                capture_output=True,
                timeout=self._ffmpeg_timeout,
                check=False,
            )

            if result.returncode != 0:
                stderr = result.stderr.decode("utf-8", errors="ignore").strip()
                if not stderr:
                    stderr = f"ffmpeg exit code {result.returncode}"
                logger.warning(
                    f"ffmpeg-Fehler beim Extrahieren der Audioprobe: {stderr}"
                )
                return None

            if not result.stdout:
                logger.warning("ffmpeg lieferte keine Audiodaten")
                return None

            # Prüfen, ob genügend Daten vorhanden sind (mindestens 0.1 Sekunden)
            min_expected_bytes = int(0.1 * config.BYTES_PER_SECOND)
            if len(result.stdout) < min_expected_bytes:
                logger.warning(
                    f"Audioprobe ist sehr kurz: {len(result.stdout)} Bytes "
                    f"(erwartet > {min_expected_bytes})"
                )
                return None

            return result.stdout

        except subprocess.TimeoutExpired:
            logger.warning(
                f"Timeout beim Extrahieren der Audioprobe (>{self._ffmpeg_timeout}s)"
            )
            return None
        except Exception as e:
            logger.warning(f"Fehler beim Extrahieren der Audioprobe: {e}")
            return None

    def _extract_wav_sample(
        self, file_path: str, duration: int, config: Config
    ) -> Optional[bytes]:
        """
        Extrahiert eine Audioprobe aus einer WAV‑Datei mit dem `wave`-Modul.

        Args:
            file_path: Pfad zur WAV-Datei.
            duration: Dauer der Probe in Sekunden.
            config: Konfigurationsobjekt mit erwarteten Audio-Parametern.

        Returns:
            Byte-Daten der Audioprobe im 16-bit PCM, mono, SAMPLE_RATE oder None bei Fehler.
        """
        import wave

        try:
            with wave.open(file_path, "rb") as wav:
                # Header-Informationen
                nchannels = wav.getnchannels()
                sampwidth = wav.getsampwidth()
                framerate = wav.getframerate()
                nframes = wav.getnframes()

                # Prüfen, ob das Format konvertiert werden muss
                # Erwartetes Format: 16-bit, Mono, SAMPLE_RATE
                needs_conversion = (
                    sampwidth != 2 or nchannels != 1 or framerate != config.SAMPLE_RATE
                )

                if needs_conversion:
                    # Fallback auf ffmpeg, wenn das Format nicht passt
                    if self._debug:
                        logger.debug(
                            f"WAV-Format ({nchannels}ch, {sampwidth*8}bit, {framerate}Hz) nicht kompatibel – verwende ffmpeg"
                        )
                    return None

                # Anzahl zu lesender Frames berechnen
                frames_to_read = min(nframes, int(framerate * duration))

                # Frames auslesen
                data = wav.readframes(frames_to_read)

                # Daten liegen als Bytes im nativen Format vor (hier 16-bit PCM)
                return data

        except Exception as e:
            if self._debug:
                logger.debug(f"Fehler beim direkten Einlesen der WAV-Datei: {e}")
            return None

    def _amplify_audio(self, audio_bytes: bytes, gain: float = 2.0) -> bytes:
        """
        Verstärkt die Amplitude des Audiosignals (Gain-Faktor) und gibt die verstärkten
        Bytes zurück. Verwendet numpy, falls verfügbar, ansonsten struct mit expliziter
        little-endian Konvertierung.

        Args:
            audio_bytes: PCM-16 Audiodaten (16-bit signed little-endian).
            gain: Verstärkungsfaktor (1.0 = keine Änderung).

        Returns:
            Verstärkte Audiodaten oder bei Fehler die originalen Audiodaten.
        """
        if not audio_bytes or gain == 1.0:
            return audio_bytes

        np = self._np  # Eigene numpy-Instanz aus AudioEnhancer
        try:
            if np is not None:
                # Mit numpy: in float konvertieren, verstärken, clippen, zurück
                audio = np.frombuffer(audio_bytes, dtype=np.int16).astype(np.float32)
                audio *= gain
                np.clip(audio, -32767, 32767, out=audio)
                return audio.astype(np.int16).tobytes()
            else:
                # Fallback mit struct
                num_samples = len(audio_bytes) // 2
                fmt = f"<{num_samples}h"
                samples = struct.unpack(fmt, audio_bytes)
                amplified = [int(max(-32768, min(32767, s * gain))) for s in samples]
                return struct.pack(fmt, *amplified)
        except Exception as e:
            if self._debug or DEBUG_LEVEL >= 1:
                logger.debug(f"Fehler bei Audio-Verstärkung: {e}")
            # Bei Fehler originale Daten zurückgeben, um den Betrieb nicht zu unterbrechen
            return audio_bytes


class OllamaSummarizer:
    """
    Zusammenfassung von Texten mit Ollama (lokal laufendes LLM).

    Diese Klasse kommuniziert mit einem Ollama-Server, sendet Prompts und empfängt
    Antworten im Streaming-Modus. Sie unterstützt das Abrufen verfügbarer Modelle,
    das Prüfen der Server-Erreichbarkeit und das asynchrone Zusammenfassen von
    Texten mit Abbruchmöglichkeit.

    Features:
        - Automatische Erkennung der installierten Modelle
        - Streaming-Antworten mit Callbacks für Teil- und Fehler-Ergebnisse
        - Abbruch einer laufenden Anfrage über ein Cancel-Event
        - Caching der verfügbaren Modelle (TTL-gesteuert)
        - Thread‑sicherer Zugriff über interne Locks
        - Unterstützung für benutzerdefinierte System-Prompts
        - Sauberes Thread‑Management und Ressourcenfreigabe

    Attributes:
        parent (Any): Referenz auf das aufrufende Objekt (für Callbacks).
        model (str): Name des zu verwendenden Ollama-Modells.
        host (str): Basis-URL des Ollama-Servers (z.B. 'http://localhost:11434').
        timeout (int): Timeout in Sekunden für die API-Anfrage.
        cache_ttl (int): Lebensdauer des Modell-Caches in Sekunden.
        system_prompt (Optional[str]): Optionaler System-Prompt für das Modell.
        cache_manager (Optional[CacheManager]): Optionaler Cache-Manager (derzeit nicht genutzt).
        available (bool): True, wenn requests installiert ist.
        _session (Optional[requests.Session]): Session für wiederholte API-Aufrufe.
        _requests: Das requests-Modul (lazy geladen).
        _lock (threading.RLock): Lock für thread-sicheren Zugriff.
        _models_cache (List[str]): Cache der verfügbaren Modelle.
        _models_cache_time (float): Zeitstempel des Caches.
        _stop_event (threading.Event): Internes Stop-Event (für stop-Methode).
        last_result (Optional[str]): Letzte vollständige Antwort (für spätere Verwendung).
        _active_threads (List[threading.Thread]): Liste aller aktiven summarize-Threads.
        _threads_lock (threading.RLock): Lock für Thread‑Liste.
    """

    def __init__(
        self,
        parent: Any,
        model: str = "qwen2.5:7b",
        host: str = "http://localhost:11434",
        timeout: int = 120,
        cache_ttl: int = 300,
        system_prompt: Optional[str] = None,
        cache_manager: Optional[CacheManager] = None,
    ) -> None:
        """
        Initialisiert den OllamaSummarizer.

        Args:
            parent: Referenz auf das aufrufende Objekt (für Callbacks).
            model: Name des zu verwendenden Ollama-Modells (z.B. 'llama3.1:8b').
            host: Basis-URL des Ollama-Servers (ohne abschließenden Slash).
            timeout: Timeout in Sekunden für die API-Anfrage.
            cache_ttl: Lebensdauer des Modell-Caches in Sekunden.
            system_prompt: Optionaler System-Prompt (wird dem Modell mitgegeben).
            cache_manager: Optionaler Cache-Manager (derzeit nicht genutzt).
        """
        self.parent = parent
        self.model = model
        self.host = host.rstrip("/")
        self.timeout = timeout
        self.cache_ttl = cache_ttl
        self.system_prompt = system_prompt
        self.cache_manager = cache_manager

        self.available = OLLAMA_AVAILABLE
        self._session = None
        self._requests = FastLazyLoader.load("requests") if self.available else None
        self._lock = threading.RLock()

        self._models_cache: List[str] = []
        self._models_cache_time = 0.0
        self._stop_event = threading.Event()

        self.last_result: Optional[str] = None

        # Thread‑Management
        self._active_threads: List[threading.Thread] = []
        self._threads_lock = threading.RLock()

    # -------------------------------------------------------------------------
    # Private Hilfsmethoden
    # -------------------------------------------------------------------------
    def _get_session(self) -> Optional[requests.Session]:
        """
        Liefert die interne Requests-Session (lazy initialisiert).

        Returns:
            Die Session oder None, wenn requests nicht verfügbar ist.
        """
        if not self.available:
            return None
        with self._lock:
            if self._session is None:
                self._session = self._requests.Session()
                self._session.headers.update(
                    {"Content-Type": "application/json", "Accept": "application/json"}
                )
        return self._session

    # -------------------------------------------------------------------------
    # Öffentliche Methoden
    # -------------------------------------------------------------------------
    def get_available_models(self) -> List[str]:
        """
        Ruft die Liste der auf dem Server verfügbaren Modelle ab (mit Caching).

        Returns:
            Liste der Modellnamen (z.B. ['llama3.1:8b', 'qwen2.5:7b', ...]).
            Bei Fehlern oder wenn der Server nicht erreichbar ist, wird eine leere Liste zurückgegeben.
        """
        if not self.available:
            return []

        now = time.time()
        with self._lock:
            if now - self._models_cache_time < self.cache_ttl and self._models_cache:
                return self._models_cache.copy()

        try:
            session = self._get_session()
            if session is None:
                return []
            r = session.get(f"{self.host}/api/tags", timeout=5)
            if r.status_code == 200:
                data = r.json()
                models = [m["name"] for m in data.get("models", [])]
                with self._lock:
                    self._models_cache = models
                    self._models_cache_time = now
                return models.copy()
            else:
                logger.warning(f"Ollama model list error: {r.status_code}")
        except self._requests.exceptions.RequestException as e:
            if DEBUG_LEVEL >= 3:
                log_exception(
                    "ollama", "Ollama request error getting models", e, level="warning"
                )
            else:
                logger.warning(f"Ollama model list error: {e}")
        except Exception as e:
            if DEBUG_LEVEL >= 3:
                log_exception(
                    "ollama", "Unexpected error getting models", e, level="warning"
                )
            else:
                logger.warning(f"Unexpected error getting models: {e}")
        return []

    def is_model_available(self, model: Optional[str] = None) -> bool:
        """
        Prüft, ob ein bestimmtes Modell auf dem Server verfügbar ist.

        Args:
            model: Modellname (wenn None, wird das aktuell gesetzte Modell verwendet).

        Returns:
            True, wenn das Modell verfügbar ist oder keine Liste verfügbar ist (Fallback).
        """
        check_model = model or self.model
        available = self.get_available_models()
        if not available:
            # Wenn wir keine Liste bekommen, nehmen wir an, dass das Modell vorhanden ist
            return True
        return check_model in available

    def is_server_reachable(self) -> bool:
        """
        Prüft, ob der Ollama-Server erreichbar ist.

        Returns:
            True, wenn der Server antwortet, sonst False.
        """
        if not self.available:
            return False
        try:
            session = self._get_session()
            if session is None:
                return False
            r = session.get(f"{self.host}/api/tags", timeout=2)
            return r.status_code == 200
        except Exception:
            return False

    def summarize(
        self,
        text: str,
        prompt: str,
        temperature: float,
        callback: Callable[[str], None],
        error_callback: Callable[[str], None],
        complete_callback: Optional[Callable[[], None]] = None,
        cancel_event: Optional[threading.Event] = None,
    ) -> None:
        """
        Startet eine asynchrone Zusammenfassung mit Streaming-Antwort.

        Die Methode erstellt einen neuen Thread, der die Anfrage an Ollama sendet.
        Teile der Antwort werden über `callback` geliefert, Fehler über `error_callback`.
        Nach Abschluss wird `complete_callback` aufgerufen (falls angegeben).

        Args:
            text: Der zu verarbeitende Text (z.B. das Transkript).
            prompt: Der Prompt, der an das Modell gesendet wird.
            temperature: Kreativitätsparameter (0.0 = deterministisch, 1.0 = kreativ).
            callback: Wird bei jedem eingehenden Teilstring aufgerufen.
            error_callback: Wird bei Fehlern mit einer Fehlermeldung aufgerufen.
            complete_callback: Wird nach erfolgreichem Abschluss aufgerufen.
            cancel_event: Optionales Event zum vorzeitigen Abbruch der Anfrage.
        """
        if not self.available:
            error_callback("Ollama nicht verfügbar (requests nicht installiert)")
            return

        if not text or not text.strip():
            error_callback("Kein Text zum Zusammenfassen")
            return

        if not self.is_model_available():
            error_callback(f"Ollama-Modell '{self.model}' nicht auf Server gefunden.")
            return

        # Interne Stop-Events zurücksetzen
        self._stop_event.clear()
        cancel = cancel_event or threading.Event()

        def worker():
            full_response = ""
            try:
                session = self._get_session()
                if session is None:
                    error_callback("Keine Session (requests nicht verfügbar)")
                    return

                full_prompt = f"{prompt}\n\n{text}"
                payload = {
                    "model": self.model,
                    "prompt": full_prompt,
                    "stream": True,
                    "options": {"temperature": temperature, "num_predict": 2048},
                }
                if self.system_prompt:
                    payload["system"] = self.system_prompt

                if logger.isEnabledFor(logging.DEBUG):
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "ollama",
                            f"Ollama request payload: {json.dumps(payload, indent=2)}",
                        )
                    else:
                        log_debug(
                            "ollama",
                            f"Ollama request: model={self.model}, prompt_len={len(full_prompt)}",
                        )

                response = session.post(
                    f"{self.host}/api/generate",
                    json=payload,
                    stream=True,
                    timeout=self.timeout,
                )

                if response.status_code == 200:
                    for line in response.iter_lines(decode_unicode=True):
                        if self._stop_event.is_set() or cancel.is_set():
                            break
                        if line:
                            try:
                                data = json.loads(line)
                                if "response" in data:
                                    chunk = data["response"]
                                    full_response += chunk
                                    callback(chunk)
                                if data.get("done", False):
                                    break
                            except json.JSONDecodeError:
                                continue

                    if not (self._stop_event.is_set() or cancel.is_set()):
                        if not full_response:
                            error_callback("Leere Antwort von Ollama")
                        else:
                            self.last_result = full_response
                            if complete_callback:
                                complete_callback()
                else:
                    error_callback(f"Ollama Fehler {response.status_code}")
            except self._requests.exceptions.Timeout:
                error_callback(
                    f"Ollama Timeout nach {self.timeout}s – Server nicht erreichbar?"
                )
            except self._requests.exceptions.ConnectionError:
                error_callback("Ollama nicht erreichbar (läuft der Server?)")
            except Exception as e:
                error_callback(f"Fehler: {str(e)}")
            finally:
                # Thread aus der Liste entfernen
                with self._threads_lock:
                    if threading.current_thread() in self._active_threads:
                        self._active_threads.remove(threading.current_thread())

        thread = threading.Thread(
            target=worker, daemon=True, name=f"Ollama-{self.model[:10]}"
        )
        with self._threads_lock:
            self._active_threads.append(thread)
        thread.start()

    def correct_transcript(
        self,
        text: str,
        callback: Callable[[str], None],
        error_callback: Callable[[str], None],
        complete_callback: Optional[Callable[[], None]] = None,
    ) -> None:
        """
        Korrigiert ein Transkript mit einem Standard-Prompt.

        Nutzt die `summarize`-Methode mit einem vordefinierten Prompt zur Textkorrektur.

        Args:
            text: Der zu korrigierende Text.
            callback: Wird bei jedem eingehenden Teilstring aufgerufen.
            error_callback: Wird bei Fehlern mit einer Fehlermeldung aufgerufen.
            complete_callback: Wird nach erfolgreichem Abschluss aufgerufen.
        """
        if not self.available:
            error_callback("Ollama nicht verfügbar (requests fehlt)")
            return
        if not self.is_model_available():
            error_callback(f"Ollama-Modell '{self.model}' nicht auf Server gefunden.")
            return

        prompt = (
            "Du bist ein Assistent, der Transkriptionen korrigiert. "
            "Der folgende Text wurde automatisch transkribiert und enthält typische Fehler: "
            "fehlende Satzzeichen, falsche Groß-/Kleinschreibung, leichte Wortverzerrungen. "
            "Korrigiere diese Fehler und verbessere die Lesbarkeit. "
            "Ändere keine inhaltlichen Aussagen, füge keine neuen Informationen hinzu. "
            "Gib nur den korrigierten Text zurück, ohne Einleitung oder Erklärung.\n\n"
            f"{text}"
        )
        self.summarize(
            text=text,
            prompt=prompt,
            temperature=0.0,
            callback=callback,
            error_callback=error_callback,
            complete_callback=complete_callback,
            cancel_event=None,
        )

    def stop(self) -> None:
        """
        Signalisiert der laufenden Anfrage, abzubrechen.
        Setzt ein internes Event, das im Worker-Thread geprüft wird.
        """
        self._stop_event.set()
        logger.info("OllamaSummarizer: Stop signalisiert")

    def dispose(self) -> None:
        """
        Gibt Ressourcen frei (schließt die HTTP-Session).
        Stoppt laufende Anfragen und wartet auf alle aktiven Threads mit Timeout.
        Sollte beim Beenden des Dialogs oder beim Shutdown aufgerufen werden.
        """
        log_debug("ollama", "OllamaSummarizer.dispose() called")

        # 1. Stop‑Event setzen, um laufende Summarize‑Anfragen abzubrechen
        self.stop()

        # 2. Auf alle noch aktiven Threads warten (mit Timeout)
        with self._threads_lock:
            # Kopie erstellen, da Liste während des Joins modifiziert werden könnte
            threads_to_join = list(self._active_threads)
            for t in threads_to_join:
                if t.is_alive():
                    log_debug("ollama", f"  → Joining thread {t.name}...")
                    t.join(timeout=1.0)  # Maximal 1 Sekunde pro Thread
                    if t.is_alive():
                        logger.warning(
                            f"Thread {t.name} did not terminate within timeout"
                        )
                    else:
                        log_debug("ollama", f"  → Thread {t.name} joined")
                # Aus der Liste entfernen (auch wenn nicht mehr lebt)
                if t in self._active_threads:
                    self._active_threads.remove(t)
            # Sicherheitshalber Liste leeren
            self._active_threads.clear()

        log_debug("ollama", "All summarize threads terminated")

        # 3. HTTP‑Session schließen
        if self._session:
            try:
                self._session.close()
                log_debug("ollama", "HTTP session closed")
            except Exception as e:
                log_debug("ollama", f"Error closing session: {e}")
            self._session = None

        # 4. Caches leeren
        with self._lock:
            self._models_cache = []
            self._models_cache_time = 0.0

        log_debug("ollama", "OllamaSummarizer disposed")


class QueueManager:
    """
    Zentrales Queue-Management für thread-sichere GUI- und Text-Updates.

    Diese Klasse verwaltet zwei Warteschlangen:
    - GUI-Queue: Enthält (msg_type, callback, important)-Tupel für GUI-Updates.
    - Text-Queue: Enthält (update_type, text_data)-Tupel für Transkriptions-/Übersetzungstexte.

    Die Verarbeitung erfolgt in Batches, deren Größe dynamisch an die aktuelle
    Queue-Auslastung angepasst wird. Unwichtige Elemente können bei Überlast
    verworfen werden, um die GUI reaktionsfähig zu halten.

    Features:
        - Dynamische Batch-Größe basierend auf Queue-Auslastung
        - Automatische Queue-Bereinigung bei Überlast
        - Schutz wichtiger Nachrichtentypen (z.B. Status, Fehler)
        - Detailliertes Logging mit Debug-Modus
        - Thread-sichere Zugriffe über Locks
        - Dynamisches Intervall: Bei Leerlauf seltener abfragen

    Attributes:
        gui (DragonWhispererGUI): Referenz auf die Haupt-GUI.
        root (tk.Tk): Das Tkinter-Hauptfenster.
        _gui_update_limiter: Rate-Limiter für GUI-Updates.
        GUI_QUEUE_MAX_SIZE (int): Maximale Größe der GUI-Queue.
        GUI_QUEUE_CLEANUP_TARGET (int): Zielgröße nach Bereinigung.
        TEXT_QUEUE_MAX_SIZE (int): Maximale Größe der Text-Queue.
        TEXT_QUEUE_CLEANUP_TARGET (int): Zielgröße nach Bereinigung.
        GUI_PROCESS_MAX_ITEMS (int): Maximale Anzahl Items pro Batch (GUI).
        TEXT_PROCESS_MAX_ITEMS (int): Maximale Anzahl Items pro Batch (Text).
        GUI_PROCESS_MAX_DURATION (float): Maximale Batch-Laufzeit in Sekunden.
        TEXT_PROCESS_MAX_DURATION (float): Maximale Batch-Laufzeit in Sekunden.
        _gui_queue_lock (threading.RLock): Lock für GUI-Queue.
        _text_queue_lock (threading.RLock): Lock für Text-Queue.
        _important_types_lock (threading.RLock): Lock für wichtige Nachrichtentypen.
        _important_msg_types (set): Menge von Nachrichtentypen, die nie verworfen werden.
        gui_queue (queue.Queue): Queue für GUI-Updates.
        text_queue (queue.Queue): Queue für Text-Updates.
        _last_queue_warning_time (float): Zeitpunkt der letzten Queue-Warnung.
    """

    # Standardwerte (können im Konstruktor überschrieben werden)
    GUI_QUEUE_MAX_SIZE = 200
    GUI_QUEUE_CLEANUP_TARGET = 100
    TEXT_QUEUE_MAX_SIZE = 150
    TEXT_QUEUE_CLEANUP_TARGET = 75
    GUI_PROCESS_MAX_ITEMS = 50
    TEXT_PROCESS_MAX_ITEMS = 20
    GUI_PROCESS_MAX_DURATION = 0.05
    TEXT_PROCESS_MAX_DURATION = 0.05

    def __init__(self, gui: "DragonWhispererGUI", **kwargs):
        """
        Initialisiert den QueueManager.

        Args:
            gui: Referenz auf die Haupt-GUI.
            **kwargs: Überschreibungen für Queue-Größen und Verarbeitungsparameter.
        """
        self.gui = gui
        self.root = gui.root
        self._gui_update_limiter = gui._gui_update_limiter

        # Queue-Größen und Verarbeitungsparameter überschreibbar
        self.GUI_QUEUE_MAX_SIZE = kwargs.get(
            "gui_queue_max_size", self.GUI_QUEUE_MAX_SIZE
        )
        self.GUI_QUEUE_CLEANUP_TARGET = kwargs.get(
            "gui_queue_cleanup_target", self.GUI_QUEUE_CLEANUP_TARGET
        )
        self.TEXT_QUEUE_MAX_SIZE = kwargs.get(
            "text_queue_max_size", self.TEXT_QUEUE_MAX_SIZE
        )
        self.TEXT_QUEUE_CLEANUP_TARGET = kwargs.get(
            "text_queue_cleanup_target", self.TEXT_QUEUE_CLEANUP_TARGET
        )
        self.GUI_PROCESS_MAX_ITEMS = kwargs.get(
            "gui_process_max_items", self.GUI_PROCESS_MAX_ITEMS
        )
        self.TEXT_PROCESS_MAX_ITEMS = kwargs.get(
            "text_process_max_items", self.TEXT_PROCESS_MAX_ITEMS
        )
        self.GUI_PROCESS_MAX_DURATION = kwargs.get(
            "gui_process_max_duration", self.GUI_PROCESS_MAX_DURATION
        )
        self.TEXT_PROCESS_MAX_DURATION = kwargs.get(
            "text_process_max_duration", self.TEXT_PROCESS_MAX_DURATION
        )

        # Locks für Thread-Sicherheit
        self._gui_queue_lock = threading.RLock()
        self._text_queue_lock = threading.RLock()
        self._important_types_lock = threading.RLock()

        # Wichtige Nachrichtentypen, die bei Überlast nicht verworfen werden
        self._important_msg_types = {
            "status",
            "error",
            "file_finished",
            "info",
            "controller_state",
            "stream_info",
        }

        # Queues aus der GUI übernehmen oder Dummy-Queues erstellen
        self.gui_queue = getattr(gui, "gui_queue", None)
        self.text_queue = getattr(gui, "_text_update_queue", None)

        if self.gui_queue is None:
            logger.warning("QueueManager: gui_queue fehlt – verwende DummyQueue")
            self.gui_queue = DummyQueue(maxsize=self.GUI_QUEUE_MAX_SIZE)
        if self.text_queue is None:
            logger.warning("QueueManager: text_queue fehlt – verwende DummyQueue")
            self.text_queue = DummyQueue(maxsize=self.TEXT_QUEUE_MAX_SIZE)

        self._last_queue_warning_time = 0.0

    # -------------------------------------------------------------------------
    # Öffentliche Methoden
    # -------------------------------------------------------------------------
    def cleanup_gui_queue(self, max_size: int) -> int:
        """
        Bereinigt die GUI-Queue auf die angegebene maximale Größe.
        Behält wichtige Nachrichten, verwirft unwichtige.

        Args:
            max_size: Maximale Anzahl Elemente nach der Bereinigung.

        Returns:
            Anzahl der gelöschten Elemente.
        """
        with self._gui_queue_lock:
            return self._cleanup_queue(
                self.gui_queue, max_size, self._gui_queue_lock, "GUI"
            )

    def cleanup_text_queue(self, max_size: int) -> int:
        return self._cleanup_queue(
            self.text_queue, max_size, self._text_queue_lock, "Text"
        )

    def start(self) -> None:
        """
        Startet die periodische Verarbeitung der Queues.
        Wird nach der GUI-Initialisierung aufgerufen.
        """
        self.root.after(50, self._process_gui_queue_dynamic)
        self.root.after(75, self._process_text_updates)
        self.root.after(5000, self._check_queue_sizes)

    def safe_put(self, queue_type: Literal["gui", "text"], item: Any) -> bool:
        """
        Fügt ein Element sicher in eine Queue ein.
        Bei voller Queue werden unwichtige Elemente verworfen oder älteste Elemente entfernt.

        Args:
            queue_type: "gui" oder "text".
            item: Das einzufügende Element.

        Returns:
            True bei Erfolg, False bei Fehler.
        """
        if queue_type == "gui":
            q = self.gui_queue
            lock = self._gui_queue_lock
        elif queue_type == "text":
            q = self.text_queue
            lock = self._text_queue_lock
        else:
            logger.error(f"safe_put: unbekannter queue_type '{queue_type}'")
            return False

        with lock:
            try:
                q.put_nowait(item)
                return True
            except queue.Full:
                logger.warning(
                    f"Queue {queue_type} is full (size={self._safe_qsize(q)}) – versuche, unwichtige Elemente zu verwerfen"
                )
                removed = self._discard_unimportant(q, queue_type)
                if removed > 0:
                    try:
                        q.put_nowait(item)
                        return True
                    except queue.Full:
                        pass
                # Falls immer noch voll: ältestes Element entfernen
                try:
                    q.get_nowait()
                    q.put_nowait(item)
                    if logger.isEnabledFor(logging.DEBUG):
                        log_debug(
                            "queue",
                            f"Queue {queue_type} war voll – ein Element verworfen",
                        )
                    return True
                except (queue.Empty, queue.Full):
                    return False
            except Exception as e:
                logger.warning(f"safe_put error ({queue_type}): {e}")
                return False

    def add_important_type(self, msg_type: str) -> None:
        """
        Fügt einen Nachrichtentyp zur Liste der wichtigen Typen hinzu.
        Wichtige Typen werden bei Queue-Bereinigung nicht verworfen.

        Args:
            msg_type: Der Nachrichtentyp (z.B. "status", "error").
        """
        with self._important_types_lock:
            self._important_msg_types.add(msg_type)

    def get_queue_sizes(self) -> Tuple[int, int]:
        """
        Gibt die aktuellen Größen der GUI- und Text-Queue zurück.

        Returns:
            (gui_size, text_size).
        """
        return (self._safe_qsize(self.gui_queue), self._safe_qsize(self.text_queue))

    # -------------------------------------------------------------------------
    # Private Verarbeitungsmethoden (periodisch)
    # -------------------------------------------------------------------------
    def _process_gui_queue_dynamic(self) -> None:
        """Verarbeitet die GUI-Queue mit dynamischer Batch-Größe."""
        self._process_queue_batch(
            queue_obj=self.gui_queue,
            lock=self._gui_queue_lock,
            max_size_threshold=self.GUI_QUEUE_MAX_SIZE,
            cleanup_target=self.GUI_QUEUE_CLEANUP_TARGET,
            max_items_base=self.GUI_PROCESS_MAX_ITEMS,
            max_duration_base=self.GUI_PROCESS_MAX_DURATION,
            interval_base=50,
            process_func=self._process_gui_item,
            queue_name="GUI",
        )

    def _process_text_updates(self) -> None:
        """Verarbeitet die Text-Queue mit dynamischer Batch-Größe."""
        self._process_queue_batch(
            queue_obj=self.text_queue,
            lock=self._text_queue_lock,
            max_size_threshold=self.TEXT_QUEUE_MAX_SIZE,
            cleanup_target=self.TEXT_QUEUE_CLEANUP_TARGET,
            max_items_base=self.TEXT_PROCESS_MAX_ITEMS,
            max_duration_base=self.TEXT_PROCESS_MAX_DURATION,
            interval_base=150,
            process_func=self._process_text_item,
            queue_name="Text",
        )

    def _process_queue_batch(
        self,
        queue_obj: queue.Queue,
        lock: threading.RLock,
        max_size_threshold: int,
        cleanup_target: int,
        max_items_base: int,
        max_duration_base: float,
        interval_base: int,
        process_func: Callable[[Any], None],
        queue_name: str,
    ) -> None:
        """
        Verarbeitet einen Batch von Elementen aus einer Queue.
        Die Batch-Größe wird dynamisch an die aktuelle Queue-Auslastung angepasst.

        Args:
            queue_obj: Die zu verarbeitende Queue.
            lock: Lock für die Queue (wird hier nicht benötigt, nur für die Bereinigung).
            max_size_threshold: Schwellwert, bei dem eine Bereinigung ausgelöst wird.
            cleanup_target: Zielgröße nach Bereinigung.
            max_items_base: Basis-Batch-Größe (wird mit Lastfaktor multipliziert).
            max_duration_base: Basis-Maximaldauer für Batch-Verarbeitung (Sekunden).
            interval_base: Basis-Intervall für die nächste Verarbeitung (ms).
            process_func: Funktion zur Verarbeitung eines einzelnen Elements.
            queue_name: Name der Queue (für Logging).
        """
        if self.gui._shutting_down or not self._root_exists():
            return

        current_size = self._safe_qsize(queue_obj)

        # Dynamische Batch-Größe basierend auf Auslastung
        if max_size_threshold > 0:
            load_factor = min(1.0, current_size / max_size_threshold)
        else:
            load_factor = 0.5
        max_items = int(max_items_base * (1 + load_factor * 2))
        max_items = min(max_items, max_items_base * 3)
        max_duration = max_duration_base * (1 + load_factor)

        start_time = time.time()
        processed = 0

        try:
            while processed < max_items and (time.time() - start_time) < max_duration:
                try:
                    item = queue_obj.get_nowait()
                except queue.Empty:
                    break
                process_func(item)
                processed += 1

            # Wenn die Queue nach der Verarbeitung zu groß ist, bereinigen
            new_size = self._safe_qsize(queue_obj)
            if new_size > max_size_threshold:
                if logger.isEnabledFor(logging.DEBUG):
                    log_debug(
                        "queue", f"{queue_name} queue zu groß ({new_size}) – bereinige"
                    )
                self._cleanup_queue(queue_obj, cleanup_target, lock, queue_name)

            # ===== Debug‑Ausgabe bei --debug=3 und relevanten Mengen =====
            if DEBUG_LEVEL >= 3 and processed > 5:
                log_debug(
                    "queue",
                    f"{queue_name} queue: {processed} Items verarbeitet, verbleibend: {new_size}",
                )
            # =============================================================

        except Exception as e:
            logger.error(
                f"❌ Kritischer Fehler in {queue_name} queue processing: {e}",
                exc_info=True,
            )

        # Dynamisches Intervall: Bei leerer Queue seltener abfragen
        if current_size == 0:
            next_interval = interval_base * 2
        elif current_size < max_size_threshold / 2:
            next_interval = interval_base
        else:
            next_interval = max(10, interval_base // 2)

        if not self.gui._shutting_down and self._root_exists():
            self.root.after(
                next_interval,
                self._process_queue_batch,
                queue_obj,
                lock,
                max_size_threshold,
                cleanup_target,
                max_items_base,
                max_duration_base,
                interval_base,
                process_func,
                queue_name,
            )

    def _process_gui_item(self, item: Any) -> None:
        """
        Verarbeitet ein einzelnes GUI‑Queue‑Element.
        Erwartet Tupel (msg_type, callback, important) oder (msg_type, callback).

        Args:
            item: Das Queue‑Element.
        """
        # Extrahiere die Bestandteile
        if isinstance(item, tuple) and len(item) in (2, 3):
            msg_type = item[0]
            callback = item[1]
            important = item[2] if len(item) == 3 else False
        else:
            logger.warning(f"⚠️ Unbekanntes Element in GUI‑Queue entfernt: {type(item)}")
            return

        if not callable(callback):
            logger.warning(f"⚠️ GUI‑Queue‑Element ist nicht aufrufbar: {msg_type}")
            return

        # Prüfen, ob GUI noch existiert und der Limiter verfügbar ist
        if not hasattr(self.gui, "_gui_update_limiter"):
            # GUI nicht mehr vorhanden – Element verwerfen
            if DEBUG_LEVEL >= 3:
                log_debug("gui", f"GUI nicht verfügbar, Element verworfen: {msg_type}")
            return

        limiter = self.gui._gui_update_limiter

        # Wichtige Updates werden sofort ausgeführt (ohne Rate‑Limit)
        if important or limiter.can_update(f"gui_{msg_type}"):
            try:
                callback()
            except tk.TclError as e:
                # Erwarteter Fehler (z.B. Widget existiert nicht mehr) – ignorieren
                if logger.isEnabledFor(logging.DEBUG):
                    log_debug("gui", f"GUI callback error ({msg_type}): {e}")
            except Exception as e:
                # Unerwarteter Fehler – loggen, aber Queue‑Verarbeitung fortsetzen
                logger.error(
                    f"❌ Unerwarteter Fehler in GUI‑Callback ({msg_type}): {e}",
                    exc_info=True
                )
                if DEBUG_LEVEL >= 3:
                    log_debug("gui", f"Unexpected exception in callback: {type(e).__name__}")
        else:
            if DEBUG_LEVEL >= 4:
                log_debug("gui", f"Rate‑Limit für {msg_type} – Element verworfen")

    def _process_text_item(self, item: Any) -> None:
        """
        Verarbeitet ein einzelnes Text-Queue-Element.
        Erwartet Tupel (update_type, text_data).

        Args:
            item: Das Queue-Element.
        """
        if not isinstance(item, tuple) or len(item) != 2:
            return
        update_type, text_data = item
        try:
            if update_type == "transcript" and hasattr(self.gui, "transcript_text"):
                if self.gui.transcript_text.winfo_exists():
                    self.gui.transcript_text.insert("end", text_data)
                    if (
                        hasattr(self.gui, "transcript_scroll_var")
                        and self.gui.transcript_scroll_var.get()
                    ):
                        self.gui.transcript_text.see("end")
            elif update_type == "translation" and hasattr(self.gui, "translation_text"):
                if self.gui.translation_text.winfo_exists():
                    self.gui.translation_text.insert("end", text_data)
                    if (
                        hasattr(self.gui, "translation_scroll_var")
                        and self.gui.translation_scroll_var.get()
                    ):
                        self.gui.translation_text.see("end")
        except tk.TclError:
            pass
        except Exception as e:
            logger.warning(f"⚠️ Text update error: {e}")

    # -------------------------------------------------------------------------
    # Queue-Wartung
    # -------------------------------------------------------------------------
    def _check_queue_sizes(self) -> None:
        """
        Periodische Überwachung der Queue-Größen.
        Bei Überschreitung der Schwellwerte wird eine Bereinigung ausgelöst und eine Warnung ausgegeben.
        """
        if self.gui._shutting_down or not self._root_exists():
            return
        try:
            gui_size = self._safe_qsize(self.gui_queue)
            text_size = self._safe_qsize(self.text_queue)  # <-- korrigiert
            now = time.time()

            if gui_size > self.GUI_QUEUE_MAX_SIZE * 0.8:
                log_debug(
                    "queue",
                    f"GUI queue size: {gui_size}/{self.GUI_QUEUE_MAX_SIZE} (high)",
                )
            if text_size > self.TEXT_QUEUE_MAX_SIZE * 0.8:
                log_debug(
                    "queue",
                    f"Text queue size: {text_size}/{self.TEXT_QUEUE_MAX_SIZE} (high)",
                )

            if gui_size > self.GUI_QUEUE_MAX_SIZE:
                logger.warning(
                    f"⚠️ GUI queue size {gui_size} exceeds threshold, cleaning up"
                )
                self._cleanup_queue(
                    self.gui_queue,
                    self.GUI_QUEUE_CLEANUP_TARGET,
                    self._gui_queue_lock,
                    "GUI",
                )
                if now - self._last_queue_warning_time > 60:
                    self.gui.update_status("⚠️ GUI-Queue überlastet – bereinigt")
                    self._last_queue_warning_time = now

            if text_size > self.TEXT_QUEUE_MAX_SIZE:
                logger.warning(
                    f"⚠️ Text queue size {text_size} exceeds threshold, cleaning up"
                )
                self._cleanup_queue(
                    self.text_queue,
                    self.TEXT_QUEUE_CLEANUP_TARGET,
                    self._text_queue_lock,
                    "Text",
                )
                if now - self._last_queue_warning_time > 60:
                    self.gui.update_status("⚠️ Text-Queue überlastet – bereinigt")
                    self._last_queue_warning_time = now

        except Exception as e:
            logger.warning(f"⚠️ Queue size check error: {e}")

        if not self.gui._shutting_down and self._root_exists():
            self.root.after(10000, self._check_queue_sizes)

    # -------------------------------------------------------------------------
    # Hilfsmethoden für Queue-Bereinigung
    # -------------------------------------------------------------------------
    def _discard_unimportant(self, queue_obj: queue.Queue, queue_type: str) -> int:
        """
        Entfernt unwichtige Elemente aus der Queue, behält wichtige.
        Wird bei Überlast aufgerufen.

        Args:
            queue_obj: Die Queue.
            queue_type: "gui" oder "text".

        Returns:
            Anzahl der entfernten Elemente.
        """
        removed = 0
        try:
            items = []
            while not queue_obj.empty():
                try:
                    items.append(queue_obj.get_nowait())
                    removed += 1
                except queue.Empty:
                    break

            important = []
            others = []
            for item in items:
                if self._is_important_item(item, queue_type):
                    important.append(item)
                else:
                    others.append(item)

            # Wichtige Elemente wieder einreihen
            for item in important:
                try:
                    queue_obj.put_nowait(item)
                except queue.Full:
                    break

            remaining_capacity = self._get_maxsize(queue_obj) - self._safe_qsize(
                queue_obj
            )
            if remaining_capacity > 0:
                for item in others[:remaining_capacity]:
                    try:
                        queue_obj.put_nowait(item)
                    except queue.Full:
                        break

            removed_count = len(others) - min(remaining_capacity, len(others))
            if removed_count > 0 and logger.isEnabledFor(logging.DEBUG):
                log_debug(
                    "queue",
                    f"{queue_type} queue: {removed_count} unwichtige Elemente verworfen",
                )
            return removed_count
        except Exception as e:
            logger.warning(f"Fehler beim Verwerfen unwichtiger Elemente: {e}")
            return 0

    def _cleanup_queue(
        self,
        queue_obj: queue.Queue,
        max_size: int,
        lock: threading.RLock,
        queue_name: str = "",
    ) -> None:
        """
        Bereinigt eine Queue auf die angegebene maximale Größe.
        Behält wichtige Elemente, verwirft unwichtige.

        Args:
            queue_obj: Die Queue.
            max_size: Maximale Anzahl Elemente nach Bereinigung.
            lock: Lock für die Queue.
            queue_name: Name für Logging.
        """
        if not queue_obj or self._safe_qsize(queue_obj) <= max_size:
            return

        queue_name_lower = queue_name.lower() if queue_name else "gui"

        with lock:
            try:
                items = []
                while True:
                    try:
                        items.append(queue_obj.get_nowait())
                    except queue.Empty:
                        break

                important = []
                others = []
                for item in items:
                    if self._is_important_item(item, queue_name_lower):
                        important.append(item)
                    else:
                        others.append(item)

                if len(important) < max_size:
                    keep_others = others[-(max_size - len(important)) :]
                    kept = important + keep_others
                else:
                    kept = important[:max_size]

                for item in kept:
                    try:
                        queue_obj.put_nowait(item)
                    except queue.Full:
                        break

                if logger.isEnabledFor(logging.DEBUG) and len(items) > len(kept):
                    discarded = len(items) - len(kept)
                    log_debug(
                        "queue",
                        f"Bereinigung {queue_name}: {discarded} Elemente verworfen "
                        f"({len(important)} wichtige, {len(others)} andere)",
                    )
            except Exception as e:
                logger.warning(f"⚠️ Queue cleanup error: {e}")

    def _is_important_item(self, item: Any, queue_type: str) -> bool:
        """
        Prüft, ob ein Queue-Element wichtig ist (nicht verworfen werden darf).

        Args:
            item: Das Queue-Element.
            queue_type: "gui" oder "text".

        Returns:
            True, wenn das Element wichtig ist.
        """
        if queue_type == "gui":
            if isinstance(item, tuple) and len(item) >= 2:
                msg_type = item[0]
                if (len(item) == 3 and item[2] is True) or self._is_important(msg_type):
                    return True
        return False

    def _is_important(self, msg_type: str) -> bool:
        """Prüft, ob ein Nachrichtentyp als wichtig markiert ist."""
        with self._important_types_lock:
            return msg_type in self._important_msg_types

    # -------------------------------------------------------------------------
    # Hilfsmethoden
    # -------------------------------------------------------------------------
    def _get_maxsize(self, q: queue.Queue) -> int:
        """Gibt die maximale Größe einer Queue zurück (falls vorhanden)."""
        try:
            return q.maxsize
        except AttributeError:
            return 0

    def _safe_qsize(self, q: Optional[queue.Queue]) -> int:
        """Sicherer Zugriff auf qsize() (fängt NotImplementedError ab)."""
        if q is None:
            return 0
        try:
            return q.qsize()
        except (NotImplementedError, AttributeError):
            return 0

    def _root_exists(self) -> bool:
        """Prüft, ob das Tkinter-Hauptfenster noch existiert."""
        try:
            return self.root.winfo_exists()
        except tk.TclError:
            return False


