# =============================================================================
# LinuxPerformanceOptimizer
# =============================================================================
if IS_LINUX and PSUTIL_AVAILABLE:

    class LinuxPerformanceOptimizer:
        """
        Optimierte Linux-Performance-Klasse mit sauberem Thread-Management.
        Der Monitoring-Thread wird explizit mit stop_event und join beendet.
        """

        def __init__(self, gui_ref: "DragonWhispererGUI") -> None:
            self.gui = gui_ref
            self.is_processing = False
            self._original_settings: Dict[str, Any] = {}
            self._optimization_active = False

            # Thread-Steuerung
            self._monitoring_stop_event = threading.Event()
            self._monitoring_thread: Optional[threading.Thread] = None
            self._monitoring_lock = threading.RLock()
            self._monitoring_thread_joined = False

            self._last_gui_access_time = 0.0
            self._gui_access_warning_printed = False

        # -------------------------------------------------------------------------
        # Hilfsmethoden für GUI-Zugriff
        # -------------------------------------------------------------------------
        def _is_gui_available_safe(self) -> bool:
            try:
                if self.gui is None:
                    return False
                return (
                    hasattr(self.gui, "root")
                    and self.gui.root is not None
                    and self.gui.root.winfo_exists()
                    and not getattr(self.gui, "_shutting_down", False)
                )
            except Exception:
                return False

        def _run_in_main_thread(self, func: Callable, *args, **kwargs) -> None:
            """Führt eine Funktion im Hauptthread aus (sicher für GUI-Updates)."""
            if not self._is_gui_available_safe():
                return
            try:
                self.gui.root.after(0, lambda: func(*args, **kwargs))
            except tk.TclError:
                pass

        # -------------------------------------------------------------------------
        # Öffentliche Methoden
        # -------------------------------------------------------------------------
        def optimize_for_processing(self) -> None:
            if not IS_LINUX or self._optimization_active:
                return
            with self._monitoring_lock:
                if self._monitoring_thread and self._monitoring_thread.is_alive():
                    logger.warning(
                        "⚠️ Optimize: Monitoring-Thread läuft bereits – überspringe"
                    )
                    return
                log_debug("linux", "🔧 Aktiviere Linux-Performance-Optimierungen...")
                self._optimize_text_widget("transcript_text")
                self._optimize_text_widget("translation_text")
                self._schedule_batch_interval_increase()
                self._clean_queue_safe(getattr(self.gui, "gui_queue", None), 15)
                self._apply_linux_specific_optimizations()
                self._optimization_active = True
                self.is_processing = True
                self._start_performance_monitoring()
                log_debug("linux", "✅ Linux-Performance-Optimierungen aktiviert")

        def _schedule_batch_interval_increase(self) -> None:
            if not self._is_gui_available_safe():
                return
            if hasattr(self.gui, "_batch_update_interval"):
                self._original_settings["batch_update_interval"] = (
                    self.gui._batch_update_interval
                )

            def task() -> None:
                if self._is_gui_available_safe() and hasattr(
                    self.gui, "_batch_update_interval"
                ):
                    self.gui._batch_update_interval = 250

            self._run_in_main_thread(task)

        def _optimize_text_widget(self, attr_name: str) -> None:
            if not self._is_gui_available_safe():
                return
            widget = getattr(self.gui, attr_name, None)
            if widget and widget.winfo_exists():
                self._original_settings[attr_name] = {
                    "maxundo": widget.cget("maxundo"),
                    "undo": widget.cget("undo"),
                    "autoseparators": widget.cget("autoseparators"),
                }

                def configure():
                    if widget.winfo_exists():
                        widget.configure(
                            maxundo=5, undo=True, autoseparators=True, height=12
                        )

                self._run_in_main_thread(configure)

        def _apply_linux_specific_optimizations(self) -> None:
            if not self._is_gui_available_safe():
                return
            self._detect_compositor()
            self._increase_resource_limits()

        def _detect_compositor(self) -> None:
            try:
                import psutil

                for proc in psutil.process_iter(["name"]):
                    try:
                        name = proc.info["name"].lower()
                        if any(
                            c in name for c in ["compton", "picom", "compiz", "kwin"]
                        ):
                            log_debug("linux", f"  ↪ Compositor erkannt: {name}")
                            break
                    except (psutil.NoSuchProcess, psutil.AccessDenied):
                        continue
            except (ImportError, AttributeError):
                pass

        def _increase_resource_limits(self) -> None:
            try:
                import resource

                try:
                    soft, hard = resource.getrlimit(resource.RLIMIT_DATA)
                    new_soft = min(hard, 1024 * 1024 * 1024)
                    if new_soft > soft:
                        resource.setrlimit(resource.RLIMIT_DATA, (new_soft, hard))
                        log_debug(
                            "linux", f"  ↪ Daten-Limit erhöht: {soft} → {new_soft}"
                        )
                except (resource.error, ValueError, PermissionError) as e:
                    log_debug(
                        "linux", f"  ⚠️ Daten-Limit konnte nicht erhöht werden: {e}"
                    )
                try:
                    soft_fd, hard_fd = resource.getrlimit(resource.RLIMIT_NOFILE)
                    new_soft_fd = min(hard_fd, 8192)
                    if new_soft_fd > soft_fd:
                        resource.setrlimit(
                            resource.RLIMIT_NOFILE, (new_soft_fd, hard_fd)
                        )
                        log_debug(
                            "linux",
                            f"  ↪ Dateideskriptoren-Limit erhöht: {soft_fd} → {new_soft_fd}",
                        )
                except (resource.error, ValueError, PermissionError) as e:
                    log_debug(
                        "linux",
                        f"  ⚠️ Dateideskriptoren-Limit konnte nicht erhöht werden: {e}",
                    )
                try:
                    os.nice(-5)
                    log_debug("linux", "  ↪ CPU-Priorität erhöht (nice -5)")
                except PermissionError:
                    log_debug(
                        "linux",
                        "  ⚠️ CPU-Priorität konnte nicht erhöht werden (keine root-Rechte)",
                    )
                except Exception as e:
                    log_debug(
                        "linux", f"  ↪ CPU-Priorität konnte nicht angepasst werden: {e}"
                    )
            except ImportError:
                log_debug(
                    "linux",
                    "  resource-Modul nicht verfügbar – überspringe Limit-Erhöhung",
                )
            except Exception as e:
                log_debug(
                    "linux",
                    f"  ⚠️ Unerwarteter Fehler in _increase_resource_limits: {e}",
                )

        def _start_performance_monitoring(self) -> None:
            with self._monitoring_lock:
                if self._monitoring_thread and self._monitoring_thread.is_alive():
                    return
                self._monitoring_stop_event.clear()
                self._monitoring_thread_joined = False

                def monitor_worker() -> None:
                    log_debug("linux", "🔍 Linux-Performance-Monitoring gestartet")
                    check_count = 0
                    max_checks = 240
                    while not self._monitoring_stop_event.is_set():
                        if self._monitoring_stop_event.wait(30):
                            break
                        if not self._is_gui_available_safe():
                            log_debug(
                                "linux",
                                "⚠️ GUI nicht mehr verfügbar – stoppe Monitoring",
                            )
                            break
                        check_count += 1
                        if check_count > max_checks:
                            log_debug(
                                "linux", "⏰ Monitoring-Zeitlimit erreicht – beende"
                            )
                            break
                        system_load = self._get_system_load()
                        memory_usage = self._get_memory_usage()
                        if system_load > 0.8 or memory_usage > 0.85:
                            self._schedule_adjustments(system_load, memory_usage)
                        if check_count % 12 == 0:
                            self._print_performance_report(system_load, memory_usage)
                    log_debug("linux", "✅ Linux-Performance-Monitoring beendet")

                self._monitoring_thread = threading.Thread(
                    target=monitor_worker, daemon=False, name="LinuxPerfMon"
                )
                self._monitoring_thread.start()
                log_debug("linux", "  ↺ Monitoring-Thread gestartet (nicht-Daemon)")

        def _get_system_load(self) -> float:
            try:
                load_avg = os.getloadavg()
                cpu_count = os.cpu_count() or 1
                return load_avg[0] / cpu_count
            except (OSError, ValueError):
                return 0.0

        def _get_memory_usage(self) -> float:
            try:
                import psutil

                memory = psutil.virtual_memory()
                return memory.percent / 100.0
            except Exception:
                return 0.0

        def _schedule_adjustments(self, load: float, memory: float) -> None:
            if not self._is_gui_available_safe():
                return

            def task() -> None:
                if (
                    not self._optimization_active
                    or self._monitoring_stop_event.is_set()
                ):
                    return
                if not self._is_gui_available_safe():
                    return
                adjustments: List[str] = []
                if memory > 0.85 and hasattr(self.gui, "gui_queue"):
                    cleared = self._clean_queue_safe(self.gui.gui_queue, 5)
                    if cleared > 0:
                        adjustments.append(f"Queue: -{cleared}")
                if load > 0.8 and hasattr(self.gui, "_batch_update_interval"):
                    current = self.gui._batch_update_interval
                    if current < 500:
                        self.gui._batch_update_interval = min(500, current + 50)
                        adjustments.append(
                            f"Update: {current}→{self.gui._batch_update_interval}ms"
                        )
                if adjustments:
                    log_debug("linux", f"🔧 Anpassungen: {', '.join(adjustments)}")

            self._run_in_main_thread(task)

        def _clean_queue_safe(
            self, queue_obj: Optional[queue.Queue], target_size: int
        ) -> int:
            if not queue_obj:
                return 0
            try:
                if queue_obj.qsize() <= target_size:
                    return 0
            except Exception:
                return 0
            cleared = 0
            try:
                while queue_obj.qsize() > target_size and cleared < 50:
                    queue_obj.get_nowait()
                    cleared += 1
            except queue.Empty:
                pass
            except Exception as e:
                log_debug("linux", f"⚠️ Queue-Cleanup-Fehler: {e}")
            return cleared

        def _print_performance_report(self, load: float, memory: float) -> None:
            try:
                stats = {
                    "System-Last": f"{load:.1%}",
                    "RAM-Auslastung": f"{memory:.1%}",
                    "Status": "Aktiv" if self.is_processing else "Inaktiv",
                }
                log_debug(
                    "linux",
                    "🐧 Linux-Performance-Report: "
                    + " | ".join(f"{k}: {v}" for k, v in stats.items()),
                )
            except Exception:
                pass

        def restore_normal_mode(self) -> None:
            if not IS_LINUX or not self._optimization_active:
                return
            log_debug("linux", "🔧 Linux-Optimierer: Fahre herunter...")
            self._monitoring_stop_event.set()
            self._optimization_active = False
            self.is_processing = False

            if (
                self._monitoring_thread
                and self._monitoring_thread.is_alive()
                and not self._monitoring_thread_joined
            ):
                log_debug("shutdown", "  → Joining LinuxPerfMon thread...")
                self._monitoring_thread.join(timeout=5.0)
                self._monitoring_thread_joined = True
                if self._monitoring_thread.is_alive():
                    logger.warning(
                        "LinuxPerfMon thread did not terminate within timeout"
                    )
                else:
                    log_debug("shutdown", "  → LinuxPerfMon thread joined")
            self._monitoring_thread = None

            if self._is_gui_available_safe():
                log_debug("linux", "  ↪ Stelle GUI-Einstellungen wieder her...")
                self._restore_text_widget("transcript_text")
                self._restore_text_widget("translation_text")
                if "batch_update_interval" in self._original_settings:
                    saved_interval = self._original_settings["batch_update_interval"]

                    def restore_batch_interval():
                        if self._is_gui_available_safe() and hasattr(
                            self.gui, "_batch_update_interval"
                        ):
                            self.gui._batch_update_interval = saved_interval

                    self._run_in_main_thread(restore_batch_interval)
            self._original_settings.clear()
            log_debug("linux", "✅ Linux-Optimierer heruntergefahren")

        def _restore_text_widget(self, attr_name: str) -> None:
            if not self._is_gui_available_safe():
                return
            widget = getattr(self.gui, attr_name, None)
            if (
                widget
                and widget.winfo_exists()
                and attr_name in self._original_settings
            ):
                settings = self._original_settings[attr_name]

                def configure():
                    if widget.winfo_exists():
                        widget.configure(**settings)
                        log_debug("linux", f"    ✅ {attr_name} wiederhergestellt")

                self._run_in_main_thread(configure)
            else:
                log_debug(
                    "linux",
                    f"    ⚠️ {attr_name} nicht wiederhergestellt (fehlt im Original oder Widget existiert nicht)",
                )

        def emergency_optimize(self) -> None:
            if self._monitoring_stop_event.is_set():
                return
            log_debug("linux", "🚨 Führe Notfall-Optimierungen durch...")
            if not self._is_gui_available_safe():
                return

            def task() -> None:
                if not self._is_gui_available_safe():
                    return
                self._clean_queue_safe(getattr(self.gui, "gui_queue", None), 3)
                self._clean_queue_safe(getattr(self.gui, "_text_update_queue", None), 2)
                for attr in ["transcript_text", "translation_text"]:
                    widget = getattr(self.gui, attr, None)
                    if widget and widget.winfo_exists():
                        try:
                            widget.configure(height=6, maxundo=1)
                        except Exception:
                            pass
                if hasattr(self.gui, "_batch_update_interval"):
                    self.gui._batch_update_interval = 500
                gc.collect()
                log_debug("linux", "✅ Notfall-Optimierungen abgeschlossen")

            self._run_in_main_thread(task)

        def get_optimization_status(self) -> Dict[str, Any]:
            return {
                "platform": SYSTEM,
                "optimization_active": self._optimization_active,
                "processing_active": self.is_processing,
                "monitoring_active": self._monitoring_thread
                and self._monitoring_thread.is_alive(),
                "shutdown_event_set": self._monitoring_stop_event.is_set(),
                "original_settings_count": len(self._original_settings),
                "linux_specific": IS_LINUX,
                "gui_available": self._is_gui_available_safe(),
            }

        def dispose(self) -> None:
            """Gibt alle Ressourcen frei und stoppt den Monitoring-Thread endgültig."""
            log_debug("linux", "🧹 Linux-Performance-Optimierer wird entsorgt...")
            self._monitoring_stop_event.set()
            try:
                self.restore_normal_mode()
            except Exception as e:
                log_debug("linux", f"⚠️ restore_normal_mode fehlgeschlagen: {e}")

            if self._monitoring_thread and self._monitoring_thread.is_alive():
                log_debug("shutdown", "  → Final join of LinuxPerfMon thread...")
                self._monitoring_thread.join(timeout=2.0)
                if self._monitoring_thread.is_alive():
                    logger.warning("LinuxPerfMon thread still alive after final join")
                else:
                    log_debug("shutdown", "  → LinuxPerfMon thread finally terminated")
            self._monitoring_thread = None

            self._original_settings.clear()
            gc.collect()
            log_debug("linux", "✅ Linux-Performance-Optimierer entsorgt")

else:
    # Dummy-Klasse für andere Plattformen oder wenn psutil fehlt
    class LinuxPerformanceOptimizer:
        def __init__(self, gui_ref: "DragonWhispererGUI") -> None:
            self.gui = gui_ref
            self.is_processing = False
            log_debug(
                "linux",
                "🐧 LinuxPerformanceOptimizer: Dummy-Modus (psutil fehlt oder nicht Linux)",
            )

        def optimize_for_processing(self) -> None:
            log_debug(
                "linux", "LinuxPerformanceOptimizer (Dummy): optimize_for_processing"
            )

        def restore_normal_mode(self) -> None:
            log_debug("linux", "LinuxPerformanceOptimizer (Dummy): restore_normal_mode")

        def emergency_optimize(self) -> None:
            log_debug("linux", "LinuxPerformanceOptimizer (Dummy): emergency_optimize")

        def get_optimization_status(self) -> Dict[str, Any]:
            return {
                "platform": SYSTEM,
                "dummy_mode": True,
                "psutil_missing": not PSUTIL_AVAILABLE,
            }

        def dispose(self) -> None:
            pass


@dataclass
class AdvancedSettings:
    """Erweiterte Einstellungen für Dragon Whisperer.
    Enthält Parameter für Transkription, Übersetzung, GUI und System."""

    # =========================================================================
    # Transkriptions-Parameter
    # =========================================================================
    beam_size: int = 10
    temperature: float = Config.DEFAULT_TEMPERATURE
    vad_filter: bool = False
    gpu_acceleration: bool = True
    max_cache_size: int = 200
    auto_save_interval: int = 300
    enable_sentiment_analysis: bool = False
    enable_speaker_diarization: bool = False
    max_memory_mb: int = 1024
    optimize_translations: bool = False

    # =========================================================================
    # Konfigurationstypen und Audio
    # =========================================================================
    config_type: str = "high_accuracy"
    transcript_max_lines: int = 400
    translation_max_lines: int = 300
    translation_engine: str = "google"
    ollama_model: str = "llama3.1:8b"
    ollama_host: str = "http://localhost:11434"

    # =========================================================================
    # Modi
    # =========================================================================
    asian_mode: bool = False
    precision_mode: bool = False
    audio_profile: str = "transcription"
    adaptive_chunk: bool = False

    # =========================================================================
    # Duplikate & Confidence
    # =========================================================================
    duplicate_similarity_threshold: float = 0.98
    adaptive_chunk_low_words: int = 3
    adaptive_chunk_high_words: int = 10
    min_confidence: float = 0.1

    # =========================================================================
    # VAD (Voice Activity Detection)
    # =========================================================================
    vad_threshold: float = 0.2
    vad_min_speech_duration_ms: int = 150
    vad_min_silence_duration_ms: int = 50
    max_empty_reads: int = 30

    # =========================================================================
    # Blacklist & Text-Filter
    # =========================================================================
    blacklist: List[str] = field(
        default_factory=lambda: [
            "Untertitelung des ZDF für funk",
            "Untertitelung des ZDF",
            "Untertitelung: ZDF",
            "Untertitelung BR",
            "Untertitelung WDR",
            "Untertitelung NDR",
            "© 2025",
            "© 2024",
            "Copyright",
            "All rights reserved",
            "Abonniert den Kanal",
            "Liken, teilen, abonnieren",
            "Vielen Dank fürs Zuschauen",
            "Bis zum nächsten Mal",
        ]
    )
    blacklist_mode: str = "word"
    enable_noise_reduction: bool = False
    enable_duplicate_check: bool = False
    hotwords: str = ""

    # =========================================================================
    # Performance (Threads)
    # =========================================================================
    transcription_workers: int = 2
    translation_workers: int = 1

    # =========================================================================
    # Text-to-Speech
    # =========================================================================
    tts_engine: str = "piper"
    tts_voice: str = "de_DE-thorsten-medium"
    tts_length_scale: float = 0.9
    tts_sentence_silence: float = 0.1

    # =========================================================================
    # Erweiterte Whisper-Parameter
    # =========================================================================
    best_of: int = 5
    patience: float = 1.0
    log_prob_threshold: float = -1.2
    compression_ratio_threshold: float = 2.8
    condition_on_previous_text: bool = True
    no_speech_threshold: float = 0.6
    suppress_tokens: str = "-1"

    # =========================================================================
    # VAD-Fallback & Proxy
    # =========================================================================
    vad_fallback_enabled: bool = True
    proxy_url: str = "socks5://127.0.0.1:18080"
    proxy_enabled: bool = False

    # =========================================================================
    # Zusammenfassung (Ollama)
    # =========================================================================
    summarize_temperature: float = 0.1
    summarize_model: str = "qwen2.5:7b"

    # =========================================================================
    # Erweiterte Pfade (für Dateizugriff)
    # =========================================================================
    allowed_dirs: List[str] = field(default_factory=list)

    # =========================================================================
    # Auto‑TTS
    # =========================================================================
    auto_tts_transcript: bool = False
    auto_tts_translation: bool = False
    auto_tts_delay_ms: int = 1500

    # =========================================================================
    # Zielsprache (für Übersetzung)
    # =========================================================================
    target_language: str = "de"

    # =========================================================================
    # Satzpufferung (für kontinuierliche Übersetzung)
    # =========================================================================
    sentence_flush_interval: float = 3.0  # Sekunden
    sentence_flush_word_threshold: int = 30  # Anzahl Wörter

    # =========================================================================
    # Interna (nicht direkt speicherbar)
    # =========================================================================
    config: Config = field(init=False, repr=False, compare=False)
    _chunk_duration: float = field(
        default=Config.BASE_CHUNK_DURATION, init=False, repr=False
    )

    # -------------------------------------------------------------------------
    # Property chunk_duration mit Setter, der config.CHUNK_DURATION aktualisiert
    # -------------------------------------------------------------------------
    @property
    def chunk_duration(self) -> float:
        return self._chunk_duration

    @chunk_duration.setter
    def chunk_duration(self, value: float) -> None:
        if hasattr(self, "config") and self.config is not None:
            min_dur = self.config.MIN_CHUNK_DURATION
            max_dur = self.config.MAX_CHUNK_DURATION
            if not (min_dur <= value <= max_dur):
                logger.warning(
                    f"Chunk duration {value}s out of range, clamping to [{min_dur}, {max_dur}]"
                )
                value = max(min_dur, min(value, max_dur))
        self._chunk_duration = value
        if hasattr(self, "config") and self.config is not None:
            self.config.CHUNK_DURATION = value

    # -------------------------------------------------------------------------
    # Initialisierung
    # -------------------------------------------------------------------------
    def __post_init__(self) -> None:
        log_debug("settings", f"Target language: {self.target_language}")
        self._recreate_config()
        self.chunk_duration = self.config.CHUNK_DURATION
        self._apply_mode_overrides()
        logger.info("🔊 Settings initialized (dataclass)")
        if DEBUG_LEVEL >= 3:
            log_debug(
                "settings",
                f"Auto‑TTS: transcript={self.auto_tts_transcript}, "
                f"translation={self.auto_tts_translation}, "
                f"delay={self.auto_tts_delay_ms}ms",
            )
            log_debug(
                "settings",
                f"Sentence flush: interval={self.sentence_flush_interval}s, "
                f"word_threshold={self.sentence_flush_word_threshold}",
            )
            log_debug(
                "settings",
                f"TTS: engine={self.tts_engine}, voice={self.tts_voice}, "
                f"length_scale={self.tts_length_scale}, sentence_silence={self.tts_sentence_silence}",
            )

    def _recreate_config(self) -> None:
        if self.config_type == "realtime":
            self.config = RealtimeConfig()
        elif self.config_type == "high_accuracy":
            self.config = HighAccuracyConfig()
        elif self.config_type == "youtube":
            self.config = YouTubeOptimizedConfig()
        else:
            self.config = Config()
        self.config.SAMPLE_RATE = Config.SAMPLE_RATE
        self.config.CHANNELS = Config.CHANNELS
        self.config.AUDIO_FORMAT = Config.AUDIO_FORMAT
        self._chunk_duration = self.config.CHUNK_DURATION

    def _apply_mode_overrides(self) -> None:
        if not hasattr(self, "config") or self.config is None:
            return

        if self.asian_mode:
            self.chunk_duration = 10.0
            self.vad_threshold = 0.35
            self.vad_min_speech_duration_ms = 300
            self.vad_min_silence_duration_ms = 120

        if self.precision_mode:
            self.chunk_duration = 7.0
            self.beam_size = 15
            self.temperature = 0.0
            self.vad_threshold = 0.25
            self.vad_min_speech_duration_ms = 260
            self.vad_min_silence_duration_ms = 110

    # -------------------------------------------------------------------------
    # Persistenz
    # -------------------------------------------------------------------------
    @classmethod
    def load_from_file(
        cls, filename: str = "dragon_advanced_settings.json"
    ) -> "AdvancedSettings":
        """Lädt erweiterte Einstellungen robust, typensicher und mit automatischer Typableitung."""
        import re
        from typing import get_origin, get_args, Union

        try:
            config_dir = PlatformUtils.get_platform_config_dir()
            file_path = config_dir / filename

            if not file_path.exists():
                logger.info(
                    "📝 Keine gespeicherten erweiterten Einstellungen, verwende Standard"
                )
                return cls()

            with open(file_path, "r", encoding="utf-8") as f:
                data = json.load(f)

            field_names = {f.name for f in fields(cls) if f.init}
            filtered = {}

            # Default-Instanz nur einmal erzeugen
            default_instance = cls()

            # Typen automatisch aus Dataclass ableiten
            type_map = {}
            for f in fields(cls):
                if not f.init:
                    continue

                typ = f.type
                origin = get_origin(typ)

                if origin is Union:
                    args = [t for t in get_args(typ) if t is not type(None)]
                    if args:
                        typ = args[0]

                if typ in (int, float, bool, str, list):
                    type_map[f.name] = typ

            def safe_convert(value, target_type, default):
                if value is None:
                    return default

                try:
                    if target_type is bool:
                        if isinstance(value, bool):
                            return value
                        if isinstance(value, (int, float)):
                            return bool(value)
                        if isinstance(value, str):
                            return value.strip().lower() in (
                                "true",
                                "1",
                                "yes",
                                "on",
                                "ja",
                                "wahr",
                                "y",
                                "enable",
                            )
                        return default

                    elif target_type in (int, float):
                        return target_type(value)

                    elif target_type is list:
                        if isinstance(value, list):
                            return [v for v in value if str(v).strip()]

                        if isinstance(value, str):
                            parts = [
                                v.strip() for v in re.split(r"[;,]", value) if v.strip()
                            ]
                            return parts

                        return []

                    else:
                        return target_type(value)

                except (ValueError, TypeError):
                    logger.warning(
                        f"⚠️ Konvertierung von '{value}' zu {target_type.__name__} fehlgeschlagen, verwende Standard {default}"
                    )
                    return default

            # Felder verarbeiten
            for key in field_names:
                if key not in data:
                    continue

                value = data[key]
                target = type_map.get(key)
                default_value = getattr(default_instance, key)

                if target:
                    filtered[key] = safe_convert(value, target, default_value)
                else:
                    filtered[key] = value

            # Spezialfall chunk_duration (Property)
            chunk_duration_val = filtered.pop("chunk_duration", None)

            instance = cls(**filtered)

            if chunk_duration_val is not None:
                try:
                    instance.chunk_duration = float(chunk_duration_val)
                except (ValueError, TypeError):
                    logger.warning(
                        f"⚠️ Ungültiger Wert für chunk_duration: {chunk_duration_val}"
                    )

            logger.info(
                f"✅ Erweiterte Einstellungen geladen (Konfigurationstyp: {instance.config_type})"
            )
            return instance

        except Exception as e:
            logger.error(
                f"❌ Fehler beim Laden der erweiterten Einstellungen: {e}",
                exc_info=True,
            )
            return cls()

    def save_to_file(self, filename: str = "dragon_advanced_settings.json") -> None:
        try:
            config_dir = PlatformUtils.get_platform_config_dir()
            config_dir.mkdir(parents=True, exist_ok=True)
            file_path = config_dir / filename
            temp_path = file_path.with_suffix(".tmp")

            data = asdict(self)
            data.pop("config", None)
            data.pop("_chunk_duration", None)
            data["chunk_duration"] = self.chunk_duration

            with open(temp_path, "w", encoding="utf-8") as f:
                json.dump(data, f, indent=2, ensure_ascii=False)

            try:
                os.replace(temp_path, file_path)
            except AttributeError:
                temp_path.replace(file_path)
            except FileNotFoundError:
                config_dir.mkdir(parents=True, exist_ok=True)
                os.replace(temp_path, file_path)

            logger.info(
                f"💾 Settings saved to {file_path} (Config Type: {self.config_type})"
            )
        except Exception as e:
            logger.error(f"❌ Fehler beim Speichern der Einstellungen: {e}")

    # -------------------------------------------------------------------------
    # Validierung und Reparatur
    # -------------------------------------------------------------------------
    def validate(self) -> List[str]:
        issues = []
        if not (1 <= self.beam_size <= 20):
            issues.append(f"beam_size {self.beam_size} außerhalb 1-20")
        if not (0.0 <= self.temperature <= 2.0):
            issues.append(f"temperature {self.temperature} außerhalb 0.0-2.0")
        if not (100 <= self.max_memory_mb <= 16384):
            issues.append(f"max_memory_mb {self.max_memory_mb} außerhalb 100-16384")
        if self.config_type not in ("default", "realtime", "high_accuracy", "youtube"):
            issues.append(f"Ungültiger config_type '{self.config_type}'")
        if self.config:
            min_dur = self.config.MIN_CHUNK_DURATION
            max_dur = self.config.MAX_CHUNK_DURATION
            if not (min_dur <= self.chunk_duration <= max_dur):
                issues.append(
                    f"chunk_duration {self.chunk_duration}s außerhalb [{min_dur}, {max_dur}]"
                )
        else:
            min_dur = ConfigDefaults.MIN_CHUNK_DURATION
            max_dur = ConfigDefaults.MAX_CHUNK_DURATION
            if not (min_dur <= self.chunk_duration <= max_dur):
                issues.append(
                    f"chunk_duration {self.chunk_duration}s außerhalb [{min_dur}, {max_dur}] (config missing)"
                )

        if not (100 <= self.transcript_max_lines <= 5000):
            issues.append(
                f"transcript_max_lines {self.transcript_max_lines} außerhalb 100-5000"
            )
        if not (100 <= self.translation_max_lines <= 5000):
            issues.append(
                f"translation_max_lines {self.translation_max_lines} außerhalb 100-5000"
            )
        if self.translation_engine not in ("google", "ollama", "argos"):
            issues.append(f"translation_engine '{self.translation_engine}' ungültig")
        if not (0.5 <= self.duplicate_similarity_threshold <= 1.0):
            issues.append(
                f"duplicate_similarity_threshold {self.duplicate_similarity_threshold} außerhalb 0.5-1.0"
            )
        if not (0.0 <= self.min_confidence <= 1.0):
            issues.append(f"min_confidence {self.min_confidence} außerhalb 0.0-1.0")
        if not (0.0 <= self.vad_threshold <= 1.0):
            issues.append(f"vad_threshold {self.vad_threshold} außerhalb 0.0-1.0")
        if self.vad_min_speech_duration_ms < 0:
            issues.append("vad_min_speech_duration_ms negativ")
        if self.vad_min_silence_duration_ms < 0:
            issues.append("vad_min_silence_duration_ms negativ")
        if self.blacklist_mode not in ("word", "substring"):
            issues.append(f"blacklist_mode '{self.blacklist_mode}' ungültig")
        if self.tts_engine not in ("piper", "pyttsx3"):
            issues.append(f"tts_engine '{self.tts_engine}' ungültig")
        if not (1 <= self.best_of <= 20):
            issues.append(f"best_of {self.best_of} außerhalb 1-20")
        if not (0.0 <= self.patience <= 2.0):
            issues.append(f"patience {self.patience} außerhalb 0.0-2.0")
        if not (0.0 <= self.no_speech_threshold <= 1.0):
            issues.append(
                f"no_speech_threshold {self.no_speech_threshold} außerhalb 0.0-1.0"
            )
        if not (-5.0 <= self.log_prob_threshold <= 0.0):
            issues.append(
                f"log_prob_threshold {self.log_prob_threshold} außerhalb -5.0-0.0"
            )
        if not (1.0 <= self.compression_ratio_threshold <= 5.0):
            issues.append(
                f"compression_ratio_threshold {self.compression_ratio_threshold} außerhalb 1.0-5.0"
            )
        if self.proxy_url and not any(
            self.proxy_url.startswith(s)
            for s in ("http://", "https://", "socks4://", "socks5://")
        ):
            issues.append(f"proxy_url '{self.proxy_url}' ungültiges Schema")
        if not (0.0 <= self.summarize_temperature <= 1.0):
            issues.append(
                f"summarize_temperature {self.summarize_temperature} außerhalb 0.0-1.0"
            )
        if not self.summarize_model or not isinstance(self.summarize_model, str):
            issues.append("summarize_model ungültig")
        if not (0.5 <= self.sentence_flush_interval <= 10.0):
            issues.append(
                f"sentence_flush_interval {self.sentence_flush_interval} außerhalb 0.5-10.0"
            )
        if not (5 <= self.sentence_flush_word_threshold <= 100):
            issues.append(
                f"sentence_flush_word_threshold {self.sentence_flush_word_threshold} außerhalb 5-100"
            )
        return issues

    def repair(self) -> List[str]:
        repairs = []
        default_instance = AdvancedSettings()
        for field_name, field_value in asdict(default_instance).items():
            if not hasattr(self, field_name) or getattr(self, field_name) is None:
                setattr(self, field_name, field_value)
                repairs.append(f"Added missing {field_name}")

        if hasattr(self, "ollama_model") and self.ollama_model == "llama3":
            self.ollama_model = "llama3.1:8b"
            repairs.append("Updated ollama_model from llama3 to llama3.1:8b")

        if not hasattr(self, "config") or self.config is None:
            self._recreate_config()
            repairs.append("Recreated config")

        self._apply_mode_overrides()
        self.chunk_duration = self._chunk_duration

        # Sicherstellen, dass die neuen Felder existieren
        for new_field in ("sentence_flush_interval", "sentence_flush_word_threshold"):
            if not hasattr(self, new_field):
                setattr(self, new_field, getattr(default_instance, new_field))
                repairs.append(f"Added missing {new_field}")

        if repairs:
            logger.info(f"✅ Repairs made: {', '.join(repairs)}")
            self.save_to_file()
        else:
            logger.info("✅ No repairs needed")
        return repairs

    # -------------------------------------------------------------------------
    # Hilfsmethoden
    # -------------------------------------------------------------------------
    def set_config_type(self, config_type: str) -> bool:
        """
        Ändert den Konfigurationstyp und benachrichtigt alle Abonnenten (z. B. AudioProcessor).

        Args:
            config_type: Einer von 'default', 'realtime', 'high_accuracy', 'youtube'

        Returns:
            True bei Erfolg, sonst False
        """
        if config_type == self.config_type:
            return True

        if config_type not in ("default", "realtime", "high_accuracy", "youtube"):
            logger.warning(f"⚠️ Ungültiger config_type '{config_type}'")
            return False

        old_type = self.config_type
        old_chunk = self.chunk_duration

        # Konfiguration wechseln
        self.config_type = config_type
        self._recreate_config()
        self.chunk_duration = old_chunk
        self._apply_mode_overrides()

        logger.info(
            f"🔄 Config type geändert: {old_type} → {config_type}, "
            f"neue CHUNK_DURATION: {self.config.CHUNK_DURATION}s"
        )

        # ========== NEU: Event-Bus benachrichtigen ==========
        try:
            # AppContext ist ein Singleton – über dieses holen wir den Event-Bus
            from . import AppContext  # oder den korrekten Import-Pfad anpassen

            event_bus = AppContext().event_bus
            if event_bus:
                event_bus.emit(
                    "config_changed",
                    {
                        "config_type": config_type,
                        "old_type": old_type,
                        "chunk_duration": self.chunk_duration,
                        "sample_rate": self.config.SAMPLE_RATE,
                        "channels": self.config.CHANNELS,
                        "bytes_per_second": self.config.BYTES_PER_SECOND,
                    },
                )
                log_debug("settings", f"Sent config_changed event for {config_type}")
            else:
                logger.debug("Event-Bus nicht verfügbar – Überspringe Benachrichtigung")
        except Exception as e:
            logger.warning(f"Konnte config_changed Event nicht senden: {e}")
        # ====================================================

        return True

    def get_audio_filter(
        self, language: Optional[str] = None, profile: Optional[str] = None
    ) -> str:
        return self.config.get_audio_filter(language, profile or self.audio_profile)

    def get_youtube_headers(self, is_manifest: bool = False) -> Dict[str, str]:
        return self.config.get_youtube_headers(is_manifest)

    def get_platform_config(self, platform: Optional[str] = None) -> Dict[str, Any]:
        return self.config.get_platform_config(platform)

